/// Maximum node-local governance transactions accepted through admin/API ingress before
/// block production drains them. Pending ingress is node-local but durable through the
/// governance ingress WAL; canonicality still starts only when the transaction is included
/// in an L1 block and finalized.
pub const MAX_PENDING_GOVERNANCE_TXS_V1: usize = 1024;

/// Per-block cap for governance transactions drained from the node-local queue.
pub const MAX_PENDING_GOVERNANCE_TXS_PER_BLOCK_V1: usize = 64;

thread_local! {
    static NFT_EVENT_REPLAY_SINK_V1: RefCell<Option<Vec<nft::NftEventV1>>> = RefCell::new(None);
}

fn nft_event_sink_start_v1() {
    NFT_EVENT_REPLAY_SINK_V1.with(|sink| {
        *sink.borrow_mut() = Some(Vec::new());
    });
}

fn nft_event_sink_abort_v1() {
    NFT_EVENT_REPLAY_SINK_V1.with(|sink| {
        *sink.borrow_mut() = None;
    });
}

fn nft_event_sink_finish_v1() -> Vec<nft::NftEventV1> {
    NFT_EVENT_REPLAY_SINK_V1.with(|sink| sink.borrow_mut().take().unwrap_or_default())
}

fn nft_event_sink_push_v1(event: nft::NftEventV1) {
    NFT_EVENT_REPLAY_SINK_V1.with(|sink| {
        if let Some(events) = sink.borrow_mut().as_mut() {
            events.push(event);
        }
    });
}

