#[derive(Clone, Debug, PartialEq, Eq)]
pub enum GovernanceIngressError {
    GovernanceDisabled,
    DuplicateProposalId(String),
    DuplicateVote {
        proposal_id: String,
        voter_pubkey_hex: String,
    },
    EmptyProposalId,
    InvalidProposalId(String),
    InvalidProposalHash(String),
    InvalidVoteSignature {
        proposal_id: String,
        reason: String,
    },
    MissingSignature(String),
    ProposalNotFound(String),
    ProposalNotPending(String),
    MissingProposalHash(String),
    VoteProposalHashMismatch {
        proposal_id: String,
        expected: String,
        got: String,
    },
    InvalidVoterPubkey(String),
    VoterNotCouncilMember {
        proposal_id: String,
        voter: String,
    },
    QueueFull {
        len: usize,
        limit: usize,
    },
    DurableWriteFailed(String),
    DurableReplayFailed(String),
}

impl std::fmt::Display for GovernanceIngressError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            GovernanceIngressError::GovernanceDisabled => write!(f, "governance_disabled"),
            GovernanceIngressError::DuplicateProposalId(id) => {
                write!(f, "duplicate_proposal_id:{id}")
            }
            GovernanceIngressError::DuplicateVote {
                proposal_id,
                voter_pubkey_hex,
            } => {
                write!(
                    f,
                    "duplicate_governance_vote:{proposal_id}:{voter_pubkey_hex}"
                )
            }
            GovernanceIngressError::EmptyProposalId => write!(f, "empty_proposal_id"),
            GovernanceIngressError::InvalidProposalId(id) => {
                write!(f, "invalid_governance_proposal_id:{id}")
            }
            GovernanceIngressError::InvalidProposalHash(hash) => {
                write!(f, "invalid_governance_proposal_hash:{hash}")
            }
            GovernanceIngressError::InvalidVoteSignature {
                proposal_id,
                reason,
            } => {
                write!(
                    f,
                    "invalid_governance_vote_signature:{proposal_id}:{reason}"
                )
            }
            GovernanceIngressError::MissingSignature(id) => write!(f, "missing_signature:{id}"),
            GovernanceIngressError::ProposalNotFound(id) => write!(f, "proposal_not_found:{id}"),
            GovernanceIngressError::ProposalNotPending(id) => {
                write!(f, "proposal_not_pending:{id}")
            }
            GovernanceIngressError::MissingProposalHash(id) => {
                write!(f, "missing_proposal_hash:{id}")
            }
            GovernanceIngressError::VoteProposalHashMismatch {
                proposal_id,
                expected,
                got,
            } => {
                write!(
                    f,
                    "vote_proposal_hash_mismatch:{proposal_id}:expected={expected}:got={got}"
                )
            }
            GovernanceIngressError::InvalidVoterPubkey(voter) => {
                write!(f, "invalid_voter_pubkey:{voter}")
            }
            GovernanceIngressError::VoterNotCouncilMember { proposal_id, voter } => {
                write!(f, "voter_not_council_member:{proposal_id}:{voter}")
            }
            GovernanceIngressError::QueueFull { len, limit } => {
                write!(f, "governance_queue_full:{len}/{limit}")
            }
            GovernanceIngressError::DurableWriteFailed(err) => {
                write!(f, "governance_ingress_durable_write_failed:{err}")
            }
            GovernanceIngressError::DurableReplayFailed(err) => {
                write!(f, "governance_ingress_durable_replay_failed:{err}")
            }
        }
    }
}

impl GovernanceIngressError {
    pub fn reason_code(&self) -> &'static str {
        match self {
            GovernanceIngressError::GovernanceDisabled => "governance_disabled",
            GovernanceIngressError::DuplicateProposalId(_) => "duplicate_proposal_id",
            GovernanceIngressError::DuplicateVote { .. } => "duplicate_governance_vote",
            GovernanceIngressError::EmptyProposalId => "empty_proposal_id",
            GovernanceIngressError::InvalidProposalId(_) => "invalid_governance_proposal_id",
            GovernanceIngressError::InvalidProposalHash(_) => "invalid_governance_proposal_hash",
            GovernanceIngressError::InvalidVoteSignature { .. } => {
                "invalid_governance_vote_signature"
            }
            GovernanceIngressError::MissingSignature(_) => "missing_signature",
            GovernanceIngressError::ProposalNotFound(_) => "proposal_not_found",
            GovernanceIngressError::ProposalNotPending(_) => "proposal_not_pending",
            GovernanceIngressError::MissingProposalHash(_) => "missing_proposal_hash",
            GovernanceIngressError::VoteProposalHashMismatch { .. } => {
                "vote_proposal_hash_mismatch"
            }
            GovernanceIngressError::InvalidVoterPubkey(_) => "invalid_voter_pubkey",
            GovernanceIngressError::VoterNotCouncilMember { .. } => "voter_not_council_member",
            GovernanceIngressError::QueueFull { .. } => "governance_queue_full",
            GovernanceIngressError::DurableWriteFailed(_) => {
                "governance_ingress_durable_write_failed"
            }
            GovernanceIngressError::DurableReplayFailed(_) => {
                "governance_ingress_durable_replay_failed"
            }
        }
    }
}

