#[allow(dead_code)]
const CTRL34_COOLDOWN_MIN: u64 = 4;

const PPM: u64 = 1_000_000;
const BASE_FEE_SHADOW_SCALE: u64 = PPM;
const EMISSION_MULTIPLIER_BPS_FP_SCALE: u128 = PPM as u128;
const REWARD_EFFECTIVE_CARRY_DENOM_FP: u128 = 10_000u128 * 10_000u128;
const CTRL34_BACKLOG_TARGET_PPM: u32 = 300_000;
const CTRL34_BACKLOG_DEADBAND_PPM: u32 = 50_000;
const CTRL34_STABILITY_APPLY_MIN_PPM: u32 = 550_000;
const CTRL34_COOLDOWN_SCALE_MIN_PPM: u32 = 650_000;
const CTRL34_WINDOW_SCALE_MIN_PPM: u32 = 650_000;

fn parse_scaled_u32_decimal(s: &str, scale: u32, max: u32) -> Option<u32> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }

    // Se contiene '.', lo trattiamo come frazione (0.6 -> scale*0.6)
    if let Some((ip, fp)) = s.split_once('.') {
        let ip = ip.trim();
        if ip == "1" {
            return Some(scale.min(max));
        }
        if ip != "0" && !ip.is_empty() {
            // tipo "2.3" → clamp a max
            return Some(max);
        }

        let frac = fp.trim();
        if frac.is_empty() {
            return Some(0);
        }

        // prendiamo fino a 18 cifre per stare comodi in u128
        let frac_digits = frac.chars().take(18).collect::<String>();
        let d = frac_digits.len() as u32;

        let frac_u: u128 = frac_digits.parse::<u128>().ok()?;
        let scale_u: u128 = scale as u128;
        let ten_pow: u128 = 10u128.pow(d);

        // rounding: (frac*scale + ten_pow/2) / ten_pow
        let scaled: u128 = (frac_u * scale_u + (ten_pow / 2)) / ten_pow;
        let out: u32 = (scaled as u32).min(max);
        return Some(out);
    }

    // Intero: se <=1 lo interpretiamo come ratio (0 o 1). Se >1, lo interpretiamo come già-scalato.
    let n: u64 = s.parse::<u64>().ok()?;
    if n <= 1 {
        let out = (n as u32).saturating_mul(scale);
        return Some(out.min(max));
    }

    Some((n.min(max as u64)) as u32)
}

fn de_opt_ratio_ppm<'de, D>(deserializer: D) -> Result<Option<u32>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    use serde::Deserialize;

    let v: Option<serde_json::Value> = Option::<serde_json::Value>::deserialize(deserializer)?;
    let Some(v) = v else {
        return Ok(None);
    };

    let s = match v {
        serde_json::Value::Number(n) => n.to_string(),
        serde_json::Value::String(s) => s,
        _ => return Err(serde::de::Error::custom("expected number or string")),
    };

    Ok(parse_scaled_u32_decimal(&s, PPM as u32, PPM as u32))
}

fn ema_u64(prev: u64, obs: u64, alpha_ppm: u32) -> u64 {
    let a = alpha_ppm.min(PPM as u32) as u128;
    let prev = prev as u128;
    let obs = obs as u128;
    (((prev * ((PPM as u128).saturating_sub(a))) + (obs * a)) / (PPM as u128)) as u64
}

fn clamp_u64(x: u64, lo: u64, hi: u64) -> u64 {
    x.max(lo).min(hi)
}

