#[derive(Serialize, Deserialize, Debug, Clone)]
#[serde(rename_all = "snake_case")]
pub(crate) enum RewardModel {
    Halving,
    DecayEpoch,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub(crate) struct RewardSchedule {
    pub model: RewardModel,
    pub start_height: u64,
    pub initial_per_block: u64,
    pub floor_per_block: u64,

    // halving
    pub halving_interval_blocks: u64,

    // decay_epoch
    pub epoch_blocks: u64,
    pub decay_num: u64,
    pub decay_den: u64,

    // routing
    pub reward_to_treasury_bps: u64,

    /// Percentuale (in bps) della reward piena riconosciuta ai blocchi vuoti/keepalive.
    /// 10_000 = 100% (uguale ai blocchi con tx), 1_000 = 10%, 0 = disabilitato.
    ///
    /// Sicurezza/compatibilità: se il campo manca (vecchi JSON), default = 0 (disabilitato).
    #[serde(default)]
    pub empty_block_reward_bps: u64,

    /// Altezza oltre la quale la reward per i blocchi vuoti viene disattivata (end esclusivo).
    /// Default: mai (u64::MAX).
    #[serde(default = "default_u64_max")]
    pub empty_block_reward_end_height: u64,
}

fn default_u64_max() -> u64 {
    u64::MAX
}

impl Default for RewardSchedule {
    fn default() -> Self {
        Self {
            model: RewardModel::DecayEpoch,
            start_height: 0,
            initial_per_block: 0,
            floor_per_block: 0,
            halving_interval_blocks: 0,
            epoch_blocks: 100_000,
            decay_num: 99,
            decay_den: 100,
            reward_to_treasury_bps: 0,
            empty_block_reward_bps: 0,
            empty_block_reward_end_height: u64::MAX,
        }
    }
}

impl RewardSchedule {
    fn reward_total_at(&self, height: u64) -> u64 {
        if height < self.start_height {
            return 0;
        }
        let h = height - self.start_height;

        let mut r = self.initial_per_block;

        match self.model {
            RewardModel::Halving => {
                if self.halving_interval_blocks == 0 {
                    return r.max(self.floor_per_block);
                }
                let epochs = h / self.halving_interval_blocks;
                // shift safe
                if epochs >= 63 {
                    r = 0;
                } else {
                    r >>= epochs;
                }
            }
            RewardModel::DecayEpoch => {
                if self.epoch_blocks == 0 || self.decay_den == 0 {
                    return r.max(self.floor_per_block);
                }
                let epochs = h / self.epoch_blocks;
                for _ in 0..epochs {
                    r = ((r as u128) * (self.decay_num as u128) / (self.decay_den as u128)) as u64;
                    if r == 0 {
                        break;
                    }
                }
            }
        }

        r.max(self.floor_per_block)
    }
}

