impl EconomicControllerReasonCode {
    pub(crate) const fn as_str(self) -> &'static str {
        match self {
            Self::Startup => "startup",
            Self::UnderfundedColdRaise => "underfunded_cold_raise",
            Self::FeeOnlyLower => "fee_only_lower",
            Self::FeeOnlyHotHold => "fee_only_hot_hold",
            Self::OverfundedHotLower => "overfunded_hot_lower",
            Self::UnderfundedHotHold => "underfunded_hot_hold",
            Self::OnTargetHold => "on_target_hold",
            Self::BoundedHold => "bounded_hold",
            Self::LowerSuppressedBacklogHotOrCongested => {
                "lower_suppressed_backlog_hot_or_congested"
            }
            Self::NoSignal => "no_signal",
            Self::CooldownHoldHighPressure => "cooldown_hold_high_pressure",
            Self::CooldownHold => "cooldown_hold",
            Self::RaiseSignalApplied => "raise_signal_applied",
            Self::LowerSignalApplied => "lower_signal_applied",
            Self::MixedSignalApplied => "mixed_signal_applied",
            Self::ColdLower => "cold_lower",
            Self::NormalHold => "normal_hold",
            Self::HotRaise => "hot_raise",
            Self::CriticalRaise => "critical_raise",
            Self::RecoveryHold => "recovery_hold",
            Self::RecoveryLower => "recovery_lower",
            Self::MinFeeClamp => "min_fee_clamp",
            Self::MaxFeeClamp => "max_fee_clamp",
            Self::RaiseDeltaCapped => "raise_delta_capped",
            Self::LowerDeltaCapped => "lower_delta_capped",
            Self::CriticalRaiseBlockedByMaxFee => "critical_raise_blocked_by_max_fee",
            Self::CriticalRaiseBlockedByGovernanceOverride => {
                "critical_raise_blocked_by_governance_override"
            }
            Self::CriticalRaiseBlockedByZeroDelta => "critical_raise_blocked_by_zero_delta",
            Self::CriticalRaiseBlockedByStaleRuntime => "critical_raise_blocked_by_stale_runtime",
        }
    }

    pub(crate) const fn all_values() -> &'static [&'static str] {
        &ECONOMIC_CONTROLLER_REASON_CODE_VALUES_V4
    }
}

