#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FeePressureStateV1 {
    Cold,
    Normal,
    Hot,
    Critical,
    Recovery,
}

impl FeePressureStateV1 {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Cold => "cold",
            Self::Normal => "normal",
            Self::Hot => "hot",
            Self::Critical => "critical",
            Self::Recovery => "recovery",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EmissionDecisionKindV1 {
    Hold,
    IncreaseSmall,
    DecreaseSmall,
    RecoveryHold,
    EmergencyClamp,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct EmissionDecisionV1 {
    kind: EmissionDecisionKindV1,
    action: EconomicControllerAction,
    reason_code: EconomicControllerReasonCode,
    raise_allowed: bool,
    lower_allowed: bool,
}

impl EmissionDecisionV1 {
    const fn hold(reason_code: EconomicControllerReasonCode) -> Self {
        Self {
            kind: EmissionDecisionKindV1::Hold,
            action: EconomicControllerAction::Hold,
            reason_code,
            raise_allowed: false,
            lower_allowed: false,
        }
    }

    const fn increase_small(reason_code: EconomicControllerReasonCode) -> Self {
        Self {
            kind: EmissionDecisionKindV1::IncreaseSmall,
            action: EconomicControllerAction::Raise,
            reason_code,
            raise_allowed: true,
            lower_allowed: false,
        }
    }

    const fn decrease_small(reason_code: EconomicControllerReasonCode) -> Self {
        Self {
            kind: EmissionDecisionKindV1::DecreaseSmall,
            action: EconomicControllerAction::Lower,
            reason_code,
            raise_allowed: false,
            lower_allowed: true,
        }
    }

    const fn recovery_hold(reason_code: EconomicControllerReasonCode) -> Self {
        Self {
            kind: EmissionDecisionKindV1::RecoveryHold,
            action: EconomicControllerAction::Hold,
            reason_code,
            raise_allowed: false,
            lower_allowed: false,
        }
    }

    const fn emergency_clamp(reason_code: EconomicControllerReasonCode) -> Self {
        Self {
            kind: EmissionDecisionKindV1::EmergencyClamp,
            action: EconomicControllerAction::Hold,
            reason_code,
            raise_allowed: false,
            lower_allowed: false,
        }
    }
}

