fn nft_extra_fee_for_op_cfg(
    op: &crate::nft::NftOpV1,
    gov: Option<&crate::governance::GovernanceState>,
) -> u64 {
    match op {
        crate::nft::NftOpV1::CreateCollection { .. } => nft_create_fee_native_cfg(gov),
        crate::nft::NftOpV1::Mint { .. } => nft_mint_fee_native_cfg(gov),
        crate::nft::NftOpV1::Transfer { .. } => nft_transfer_fee_native_cfg(gov),
        crate::nft::NftOpV1::Approve { .. } | crate::nft::NftOpV1::SetApprovalForAll { .. } => {
            nft_approval_fee_native_cfg(gov)
        }
        crate::nft::NftOpV1::Burn { .. } => nft_burn_fee_native_cfg(gov),
        crate::nft::NftOpV1::Revoke { .. } => nft_revoke_fee_native_cfg(gov),
        crate::nft::NftOpV1::SetTokenUri { .. } | crate::nft::NftOpV1::SetCollectionUri { .. } => {
            nft_metadata_update_fee_native_cfg(gov)
        }
        crate::nft::NftOpV1::FreezeToken { .. } => nft_freeze_fee_native_cfg(gov),
        crate::nft::NftOpV1::SetCollectionPolicy { .. } => nft_policy_update_fee_native_cfg(gov),
        crate::nft::NftOpV1::SetIssuer { .. } => nft_issuer_update_fee_native_cfg(gov),
        crate::nft::NftOpV1::SetPaused { .. } => nft_pause_fee_native_cfg(gov),
    }
}

fn validate_nft_runtime_policy_v1(
    tx: &crate::transaction::Transaction,
    op: &crate::nft::NftOpV1,
    gov: Option<&crate::governance::GovernanceState>,
) -> Result<(), String> {
    if !nft_enabled_cfg(gov) {
        return Err("nft_disabled".to_string());
    }
    if !nft_metadata_hash_required_cfg(gov) {
        return Err("nft_metadata_hash_required_must_remain_true".to_string());
    }
    let memo_len = tx.memo.as_deref().map(|m| m.len()).unwrap_or(0);
    let max_memo = nft_max_memo_bytes_cfg(gov) as usize;
    if memo_len == 0 || memo_len > max_memo {
        return Err(format!(
            "nft_memo_policy_limit_exceeded: len={} max={}",
            memo_len, max_memo
        ));
    }
    let max_uri = nft_max_uri_bytes_cfg(gov) as usize;
    let max_name = nft_max_name_bytes_cfg(gov) as usize;
    let max_symbol = nft_max_symbol_bytes_cfg(gov) as usize;
    match op {
        crate::nft::NftOpV1::CreateCollection {
            symbol,
            name,
            base_uri,
            max_supply,
            ..
        } => {
            if !nft_public_create_enabled_cfg(gov) {
                return Err("nft_create_disabled".to_string());
            }
            if symbol.len() > max_symbol {
                return Err(format!(
                    "nft_symbol_policy_limit_exceeded: len={} max={}",
                    symbol.len(),
                    max_symbol
                ));
            }
            if name.len() > max_name {
                return Err(format!(
                    "nft_name_policy_limit_exceeded: len={} max={}",
                    name.len(),
                    max_name
                ));
            }
            if base_uri.len() > max_uri {
                return Err(format!(
                    "nft_uri_policy_limit_exceeded: len={} max={}",
                    base_uri.len(),
                    max_uri
                ));
            }
            if let Some(max_supply) = max_supply {
                let cap = nft_max_tokens_per_collection_cfg(gov);
                if cap > 0 && *max_supply > cap {
                    return Err(format!(
                        "nft_collection_max_supply_exceeds_policy: max_supply={} cap={}",
                        max_supply, cap
                    ));
                }
            }
        }
        crate::nft::NftOpV1::Mint { token_uri, .. } => {
            if !nft_public_mint_enabled_cfg(gov) {
                return Err("nft_mint_disabled".to_string());
            }
            if token_uri.len() > max_uri {
                return Err(format!(
                    "nft_uri_policy_limit_exceeded: len={} max={}",
                    token_uri.len(),
                    max_uri
                ));
            }
        }
        crate::nft::NftOpV1::Transfer { .. } => {
            if !nft_public_transfer_enabled_cfg(gov) {
                return Err("nft_transfer_disabled".to_string());
            }
        }
        crate::nft::NftOpV1::Approve { .. } | crate::nft::NftOpV1::SetApprovalForAll { .. } => {
            if !nft_public_approval_enabled_cfg(gov) {
                return Err("nft_approval_disabled".to_string());
            }
        }
        crate::nft::NftOpV1::Burn { .. } => {
            if !nft_public_burn_enabled_cfg(gov) {
                return Err("nft_burn_disabled".to_string());
            }
        }
        crate::nft::NftOpV1::Revoke { .. } => {
            if !nft_public_revoke_enabled_cfg(gov) {
                return Err("nft_revoke_disabled".to_string());
            }
        }
        crate::nft::NftOpV1::SetTokenUri { token_uri, .. } => {
            if !nft_public_metadata_update_enabled_cfg(gov) {
                return Err("nft_metadata_update_disabled".to_string());
            }
            if token_uri.len() > max_uri {
                return Err(format!(
                    "nft_uri_policy_limit_exceeded: len={} max={}",
                    token_uri.len(),
                    max_uri
                ));
            }
        }
        crate::nft::NftOpV1::SetCollectionUri { base_uri, .. } => {
            if !nft_public_metadata_update_enabled_cfg(gov) {
                return Err("nft_metadata_update_disabled".to_string());
            }
            if base_uri.len() > max_uri {
                return Err(format!(
                    "nft_uri_policy_limit_exceeded: len={} max={}",
                    base_uri.len(),
                    max_uri
                ));
            }
        }
        crate::nft::NftOpV1::FreezeToken { .. } => {
            if !nft_public_freeze_enabled_cfg(gov) {
                return Err("nft_freeze_disabled".to_string());
            }
        }
        crate::nft::NftOpV1::SetCollectionPolicy { .. } => {
            if !nft_public_policy_update_enabled_cfg(gov) {
                return Err("nft_policy_update_disabled".to_string());
            }
        }
        crate::nft::NftOpV1::SetIssuer { .. } => {
            if !nft_public_issuer_update_enabled_cfg(gov) {
                return Err("nft_issuer_update_disabled".to_string());
            }
        }
        crate::nft::NftOpV1::SetPaused { .. } => {
            if !nft_public_pause_enabled_cfg(gov) {
                return Err("nft_pause_disabled".to_string());
            }
        }
    }
    Ok(())
}

fn is_public_mode_enabled() -> bool {
    crate::runtime_mode::public_mode_enabled()
}

fn unsafe_pruned_boot_bypass_allowed_v1(env_value: &str, public_mode: bool) -> bool {
    env_value == "1" && !public_mode
}

fn unsafe_pruned_boot_bypass_env_allowed_v1(env_name: &str) -> bool {
    let env_value = std::env::var(env_name).unwrap_or_default();
    let public_mode = is_public_mode_enabled();
    if env_value == "1" && public_mode {
        ng_error!(target: "storage.boot", "unsafe pruned boot bypass rejected in public mode env={}", env_name);
    }
    unsafe_pruned_boot_bypass_allowed_v1(&env_value, public_mode)
}

fn unsafe_economy_boot_bypass_env_allowed_v1(env_name: &str) -> bool {
    let env_value = std::env::var(env_name).unwrap_or_default();
    let public_mode = is_public_mode_enabled();
    if env_value == "1" && public_mode {
        ng_error!(target: "storage.boot", "unsafe economy boot bypass rejected in public mode env={}", env_name);
    }
    unsafe_pruned_boot_bypass_allowed_v1(&env_value, public_mode)
}

fn validate_economy_policy_version_fields(
    policy_version: u32,
    policy_compat_version: u32,
) -> Result<(u32, u32), NgError> {
    if policy_version < 1 {
        return Err(NgError::invalid(
            "economy policy policy_version must be >= 1",
        ));
    }
    if policy_compat_version < 1 {
        return Err(NgError::invalid(
            "economy policy policy_compat_version must be >= 1",
        ));
    }
    if policy_compat_version > policy_version {
        return Err(NgError::invalid(format!(
            "economy policy policy_compat_version={} exceeds policy_version={}",
            policy_compat_version, policy_version
        )));
    }
    if policy_compat_version > SUPPORTED_ECONOMY_POLICY_COMPAT_VERSION {
        return Err(NgError::new(
            ErrorKind::ProtocolMismatch,
            format!(
                "unsupported economy policy compat_version={} supported_max={}",
                policy_compat_version, SUPPORTED_ECONOMY_POLICY_COMPAT_VERSION
            ),
        ));
    }
    Ok((policy_version, policy_compat_version))
}

fn economy_policy_file_version_fields(file: &EconomyPolicyFile) -> (u32, u32) {
    (
        file.policy_version
            .unwrap_or_else(default_economy_policy_version),
        file.policy_compat_version
            .unwrap_or_else(default_economy_policy_compat_version),
    )
}

fn validate_fee_controller_bounds_file_fields(file: &EconomyPolicyFile) -> Result<(), NgError> {
    let base_fee_min = file.base_fee_min.unwrap_or(ECONOMY_DEFAULT_BASE_FEE_MIN);
    let base_fee_max = file.base_fee_max.unwrap_or(ECONOMY_DEFAULT_BASE_FEE_MAX);
    if base_fee_min == 0 {
        return Err(NgError::invalid(
            "economy policy fee bounds invalid: base_fee_min must be > 0",
        ));
    }
    if base_fee_max < base_fee_min {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: base_fee_max={} below base_fee_min={}",
            base_fee_max, base_fee_min
        )));
    }
    if let Some(base_fee) = file.base_fee_per_tx {
        if base_fee < base_fee_min || base_fee > base_fee_max {
            return Err(NgError::invalid(format!(
                "economy policy fee bounds invalid: base_fee_per_tx={} outside [{}..={}]",
                base_fee, base_fee_min, base_fee_max
            )));
        }
    }

    let configured_legacy_delta_cap = file
        .base_fee_delta_max_bps
        .unwrap_or(CTRL34_FEE_MAX_RAISE_PER_APPLY_BPS as u64);
    if configured_legacy_delta_cap == 0 || configured_legacy_delta_cap > 10_000 {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: base_fee_delta_max_bps={} must be in [1..=10000]",
            configured_legacy_delta_cap
        )));
    }
    let legacy_delta_cap = configured_legacy_delta_cap
        .max(CTRL34_FEE_MAX_RAISE_PER_APPLY_BPS as u64)
        .min(10_000);

    let max_raise = file
        .fee_max_raise_per_apply_bps
        .unwrap_or_else(default_ctrl34_fee_max_raise_per_apply_bps);
    let max_lower = file
        .fee_max_lower_per_apply_bps
        .unwrap_or_else(default_ctrl34_fee_max_lower_per_apply_bps);
    if max_raise == 0 {
        return Err(NgError::invalid(
            "economy policy fee bounds invalid: fee_max_raise_per_apply_bps must be > 0",
        ));
    }
    if max_lower == 0 {
        return Err(NgError::invalid(
            "economy policy fee bounds invalid: fee_max_lower_per_apply_bps must be > 0",
        ));
    }
    if (max_raise as u64) > legacy_delta_cap {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: fee_max_raise_per_apply_bps={} exceeds base_fee_delta_max_bps={}",
            max_raise, legacy_delta_cap
        )));
    }
    if (max_lower as u64) > legacy_delta_cap {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: fee_max_lower_per_apply_bps={} exceeds base_fee_delta_max_bps={}",
            max_lower, legacy_delta_cap
        )));
    }

    let hot_raise = file
        .fee_hot_raise_bps
        .unwrap_or_else(default_ctrl34_fee_hot_raise_bps);
    let critical_raise = file
        .fee_critical_raise_bps
        .unwrap_or_else(default_ctrl34_fee_critical_raise_bps);
    let cold_lower = file
        .fee_cold_lower_bps
        .unwrap_or_else(default_ctrl34_fee_cold_lower_bps);
    let recovery_lower = file
        .fee_recovery_lower_bps
        .unwrap_or_else(default_ctrl34_fee_recovery_lower_bps);

    if hot_raise == 0 {
        return Err(NgError::invalid(
            "economy policy fee bounds invalid: fee_hot_raise_bps must be > 0",
        ));
    }
    if critical_raise < hot_raise {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: fee_critical_raise_bps={} below fee_hot_raise_bps={}",
            critical_raise, hot_raise
        )));
    }
    if hot_raise > max_raise {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: fee_hot_raise_bps={} exceeds fee_max_raise_per_apply_bps={}",
            hot_raise, max_raise
        )));
    }
    if critical_raise > max_raise {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: fee_critical_raise_bps={} exceeds fee_max_raise_per_apply_bps={}",
            critical_raise, max_raise
        )));
    }
    if cold_lower == 0 {
        return Err(NgError::invalid(
            "economy policy fee bounds invalid: fee_cold_lower_bps must be > 0",
        ));
    }
    if recovery_lower == 0 {
        return Err(NgError::invalid(
            "economy policy fee bounds invalid: fee_recovery_lower_bps must be > 0",
        ));
    }
    if cold_lower > max_lower {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: fee_cold_lower_bps={} exceeds fee_max_lower_per_apply_bps={}",
            cold_lower, max_lower
        )));
    }
    if recovery_lower > max_lower {
        return Err(NgError::invalid(format!(
            "economy policy fee bounds invalid: fee_recovery_lower_bps={} exceeds fee_max_lower_per_apply_bps={}",
            recovery_lower, max_lower
        )));
    }

    if let Some(v) = file.fee_recovery_hold_blocks {
        if v == 0 {
            return Err(NgError::invalid(
                "economy policy fee bounds invalid: fee_recovery_hold_blocks must be >= 1 when explicitly set",
            ));
        }
    }
    let recovery_streak = file
        .fee_empty_recovery_streak_blocks
        .unwrap_or_else(default_ctrl34_fee_empty_recovery_streak_blocks);
    if recovery_streak == 0 {
        return Err(NgError::invalid(
            "economy policy fee bounds invalid: fee_empty_recovery_streak_blocks must be >= 1",
        ));
    }
    if let Some(neutral_revert_lower) = file.fee_neutral_revert_lower_bps {
        if neutral_revert_lower == 0 {
            return Err(NgError::invalid(
                "economy policy fee bounds invalid: fee_neutral_revert_lower_bps must be > 0",
            ));
        }
        if (neutral_revert_lower as u64) > legacy_delta_cap {
            return Err(NgError::invalid(format!(
                "economy policy fee bounds invalid: fee_neutral_revert_lower_bps={} exceeds base_fee_delta_max_bps={}",
                neutral_revert_lower, legacy_delta_cap
            )));
        }
    }
    if let Some(v) = file.fee_neutral_revert_apply_interval_blocks {
        if v == 0 {
            return Err(NgError::invalid(
                "economy policy fee bounds invalid: fee_neutral_revert_apply_interval_blocks must be >= 1",
            ));
        }
    }
    if let Some(v) = file.fee_neutral_revert_min_streak_blocks {
        if v == 0 {
            return Err(NgError::invalid(
                "economy policy fee bounds invalid: fee_neutral_revert_min_streak_blocks must be >= 1",
            ));
        }
    }

    Ok(())
}

/// Legge il JSON economy. Se manca ritorna Ok(None). Se è invalido o incompatibile, fallisce in modo esplicito.
pub(crate) fn load_economy_policy_from_disk(
    path: &str,
) -> Result<Option<EconomyPolicyFile>, NgError> {
    let resolved_path = NodePaths::resolve_config_path(path);
    ng_debug!(target: "economy.boot", "Economy policy load attempt path={:?}", resolved_path);

    if !resolved_path.exists() {
        ng_debug!(target: "economy.boot", "Economy policy file not found path={:?}", resolved_path);
        return Ok(None);
    }

    let contents = fs::read_to_string(&resolved_path).map_err(|e| {
        ng_error!(target: "economy.boot", "Economy policy read failed path={:?} err={}", resolved_path, e);
        NgError::invalid(format!("economy policy read failed path={:?} err={}", resolved_path, e))
    })?;

    match serde_json::from_str::<serde_json::Value>(&contents) {
        Ok(serde_json::Value::Object(map)) => {
            for legacy_field in ["controller_mode", "k_fill"] {
                if map.contains_key(legacy_field) {
                    ng_error!(
                        target: "economy.boot",
                        "Economy policy rejected path={:?} legacy_field={} err=legacy_field_not_supported",
                        resolved_path,
                        legacy_field
                    );
                    return Err(NgError::invalid(format!(
                        "economy policy contains unsupported legacy field={} path={:?}",
                        legacy_field, resolved_path
                    )));
                }
            }
        }
        Ok(_) => {}
        Err(e) => {
            ng_error!(target: "economy.boot", "Economy policy parse failed path={:?} err={}", resolved_path, e);
            return Err(NgError::invalid(format!(
                "economy policy parse failed path={:?} err={}",
                resolved_path, e
            )));
        }
    }

    let policy = serde_json::from_str::<EconomyPolicyFile>(&contents).map_err(|e| {
        ng_error!(target: "economy.boot", "Economy policy parse failed path={:?} err={}", resolved_path, e);
        NgError::invalid(format!("economy policy parse failed path={:?} err={}", resolved_path, e))
    })?;

    let (policy_version, policy_compat_version) = economy_policy_file_version_fields(&policy);
    validate_economy_policy_version_fields(policy_version, policy_compat_version)?;
    validate_fee_controller_bounds_file_fields(&policy)?;

    ng_info!(
        target: "economy.boot",
        "Economy policy admission accepted path={:?} policy_version={} policy_compat_version={} supported_policy_version={} supported_policy_compat_max={} base_fee_per_tx={:?}",
        resolved_path,
        policy_version,
        policy_compat_version,
        CURRENT_ECONOMY_POLICY_VERSION,
        SUPPORTED_ECONOMY_POLICY_COMPAT_VERSION,
        policy.base_fee_per_tx
    );

    Ok(Some(policy))
}

