#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct SecurityRuntime {
    pub min_fee_per_tx: u64,
    pub min_fee_per_byte: u64,
    pub max_block_size: u64,
}

impl Default for SecurityRuntime {
    fn default() -> Self {
        Self::from_policy(&SecurityPolicy::default())
    }
}

impl SecurityRuntime {
    pub fn from_policy(policy: &SecurityPolicy) -> Self {
        SecurityRuntime {
            min_fee_per_tx: policy.min_fee_per_tx,
            min_fee_per_byte: policy.min_fee_per_byte,
            max_block_size: policy.max_block_size,
        }
    }
}

// ===========================================
// STEP 49 – Slashing base PoA (modello v1)
// ===========================================

#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum SlashingReason {
    DoubleProposalSameHeight,
    InvalidBlockSevere,
    P2PPolicyViolationSevere,
    /// Light monetary leak for missed turns. It must not be counted as a major reputation slash.
    InactivityLeak,
    /// Byzantine equivocation / conflicting consensus statements.
    Equivocation,
    /// Proven finality-critical malicious behavior. Governance/revocation path required.
    MaliciousFinality,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum ValidatorSlashSeverityV1 {
    /// Monetary debt + light misbehavior only. Does not increment canonical slashed_count.
    InactivityLeak,
    /// Real validator fault: increments canonical slashed_count and cooldown.
    MajorSlash,
    /// Severe consensus fault: major slash plus stronger misbehavior points / jail.
    CriticalSlash,
    /// Finality/malicious fault: revoke/jail candidate; no automatic silent recovery.
    MaliciousFinality,
}

impl SlashingReason {
    pub fn severity_v1(&self) -> ValidatorSlashSeverityV1 {
        match self {
            SlashingReason::InactivityLeak => ValidatorSlashSeverityV1::InactivityLeak,
            SlashingReason::DoubleProposalSameHeight => ValidatorSlashSeverityV1::MajorSlash,
            SlashingReason::InvalidBlockSevere
            | SlashingReason::P2PPolicyViolationSevere
            | SlashingReason::Equivocation => ValidatorSlashSeverityV1::CriticalSlash,
            SlashingReason::MaliciousFinality => ValidatorSlashSeverityV1::MaliciousFinality,
        }
    }

    pub fn reputation_misbehavior_points_v1(&self) -> u32 {
        match self.severity_v1() {
            ValidatorSlashSeverityV1::InactivityLeak => 1,
            ValidatorSlashSeverityV1::MajorSlash => 35,
            ValidatorSlashSeverityV1::CriticalSlash => 65,
            ValidatorSlashSeverityV1::MaliciousFinality => 100,
        }
    }

    pub fn counts_as_major_reputation_slash_v1(&self) -> bool {
        !matches!(self.severity_v1(), ValidatorSlashSeverityV1::InactivityLeak)
    }

    pub fn requires_revoke_candidate_v1(&self) -> bool {
        matches!(
            self.severity_v1(),
            ValidatorSlashSeverityV1::MaliciousFinality
        )
    }
}

#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct ValidatorSlashingInfo {
    pub total_slashed_amount: u64,
    pub pending_slash_debt: u64,
    pub slash_events_count: u32,
    pub last_slash_height: u64,
    #[serde(default)]
    pub last_reward_apply_height: u64,
    pub jailed_until_height: Option<u64>,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct SlashingEvent {
    pub validator_pubkey: String,
    pub reason: SlashingReason,
    pub height: u64,
    pub evidence_block_hash: String,
    pub penalty_amount: u64,
    pub jailed_until_height: Option<u64>,
}

#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct SlashingState {
    /// Stato “permanentemente” ricostruibile per ogni validator.
    pub validators: HashMap<String, ValidatorSlashingInfo>,

    /// Log degli eventi di slashing (append-only, limitabile in futuro).
    pub events: Vec<SlashingEvent>,

    /// Mappa runtime non serializzata per rilevare double-sign.
    #[serde(skip)]
    pub seen_blocks: HashMap<(u64, String), String>,
}

#[derive(Clone, Serialize, Debug)]
pub struct SecurityMetricsSnapshot {
    pub min_fee_per_tx: u64,
    pub min_fee_per_byte: u64,
    pub max_block_size: u64,
    pub peers_total: u64,
    pub good: u64,
    pub probation: u64,
    pub banned: u64,
    pub ascore_avg_x10: u32, // es: 4979 = 497.9
    pub slashing_events: u64,
}

impl SlashingState {
    /// Ledger-only slashing mutation. Runtime paths that also have governance state MUST use
    /// Blockchain::register_slash_and_apply_reputation_effect_v1(...) so canonical validator/wallet
    /// reputation cannot drift from monetary slashing state.
    fn register_slash_ledger_only_v1(
        &mut self,
        validator_pubkey: &str,
        reason: SlashingReason,
        height: u64,
        evidence_block_hash: &str,
        penalty_amount: u64,
        jailed_until_height: Option<u64>,
    ) {
        // Canonicalize pubkey -> hex to avoid base64/hex mismatches in maps (reward-debt, jail, etc).
        let pk_hex = keyfmt::pk_hex_from_any(validator_pubkey)
            .unwrap_or_else(|_| validator_pubkey.trim().to_string());

        let info = self.validators.entry(pk_hex.clone()).or_default();

        info.pending_slash_debt = info.pending_slash_debt.saturating_add(penalty_amount);
        info.total_slashed_amount = info.total_slashed_amount.saturating_add(penalty_amount);
        info.slash_events_count = info.slash_events_count.saturating_add(1);
        info.last_slash_height = height;

        info.jailed_until_height = match (info.jailed_until_height, jailed_until_height) {
            (Some(cur), Some(new)) => Some(cur.max(new)),
            (None, Some(new)) => Some(new),
            (Some(cur), None) => Some(cur),
            (None, None) => None,
        };

        let ev = SlashingEvent {
            validator_pubkey: pk_hex.clone(),
            reason: reason.clone(),
            height,
            evidence_block_hash: evidence_block_hash.to_string(),
            penalty_amount,
            jailed_until_height: info.jailed_until_height,
        };
        self.events.push(ev);

        ng_warn!(
            target: "slash",
            "validator={} reason={:?} height={} penalty={} jailed_until={:?}",
            pk_hex,
            reason,
            height,
            penalty_amount,
            info.jailed_until_height
        );
    }

    /// Applica il “debito di slashing” ad una reward futura.
    /// Preview (non-mutating) of reward-debt consumption on a reward.
    /// Returns (reward_after_debt, cut_to_treasury).
    pub fn preview_on_reward(&self, validator_pubkey: &str, reward: u64) -> (u64, u64) {
        // Canonicalize pubkey -> hex to ensure consistent lookups.
        let pk_hex = keyfmt::pk_hex_from_any(validator_pubkey)
            .unwrap_or_else(|_| validator_pubkey.trim().to_string());

        let debt = self
            .validators
            .get(&pk_hex)
            .map(|i| i.pending_slash_debt)
            .unwrap_or(0);
        let cut = reward.min(debt);
        (reward.saturating_sub(cut), cut)
    }

    /// Ritorna (reward_finale_per_validator, cut_slash_per_treasury).
    pub fn apply_on_reward(
        &mut self,
        validator_pubkey: &str,
        current_height: u64,
        reward: u64,
    ) -> (u64, u64) {
        // Canonicalize pubkey -> hex to ensure idempotence and consistent state updates.
        let pk_hex = keyfmt::pk_hex_from_any(validator_pubkey)
            .unwrap_or_else(|_| validator_pubkey.trim().to_string());

        let info = self.validators.entry(pk_hex.clone()).or_default();

        // Idempotence: avoid consuming reward-debt twice for the same block height
        // (e.g. double-calls to on_block_applied on reorg/replay paths).
        if info.last_reward_apply_height == current_height {
            return (reward, 0);
        }

        if info.pending_slash_debt == 0 {
            info.last_reward_apply_height = current_height;
            return (reward, 0);
        }

        let cut = reward.min(info.pending_slash_debt);
        info.pending_slash_debt -= cut;
        info.last_reward_apply_height = current_height;

        if cut > 0 {
            ng_info!(
                target: "slash",
                "reward debt consumed validator={} height={} reward={} cut={} remaining_debt={}",
                pk_hex,
                current_height,
                reward,
                cut,
                info.pending_slash_debt
            );
        }

        (reward.saturating_sub(cut), cut)
    }

    /// Ritorna Some(jail_height) se il validator è in jail fino a quella height.
    pub fn jailed_until(&self, validator_pubkey: &str) -> Option<u64> {
        // Canonicalize pubkey -> hex to avoid base64/hex mismatch.
        let pk_hex = keyfmt::pk_hex_from_any(validator_pubkey)
            .unwrap_or_else(|_| validator_pubkey.trim().to_string());

        self.validators
            .get(&pk_hex)
            .and_then(|info| info.jailed_until_height)
    }
    pub fn is_jailed_at(&self, validator_pubkey: &str, current_height: u64) -> bool {
        matches!(self.jailed_until(validator_pubkey), Some(h) if current_height <= h)
    }
}

// BEGIN STEP 32B: Soft-PoA+ helper
/// Ritorna true se negli ultimi TRUST_WINDOW blocchi della catena
/// c’è almeno un blocco firmato da un miner **revocato on-chain** (governance.validator_reputation).
///
/// Scelta architetturale (A): la "banned/revoked list" deve essere deterministica e on-chain.
/// La telemetria P2P locale non può essere usata per bannare miner/validator senza un handshake firmato.
pub fn has_banned_miners_in_tail(chain: &Blockchain) -> bool {
    if chain.chain.is_empty() {
        return false;
    }
    let Some(gov) = chain.governance.as_ref() else {
        return false;
    };

    let start = chain.chain.len().saturating_sub(TRUST_WINDOW);
    for b in &chain.chain[start..] {
        let miner_hex = keyfmt::pk_hex_from_any(&b.miner_pub_key)
            .unwrap_or_else(|_| b.miner_pub_key.trim().to_string());
        if let Some(rep) = gov.validator_reputation.get(&miner_hex) {
            if rep.is_revoked_at(b.index) {
                return true;
            }
        }
    }
    false
}
// END STEP 32B

