pub(crate) const SNAPSHOT_ECONOMY_STATE_VERSION_V1: u32 = 1;

/// Snapshot-side recovery contract for post-tip economy/controller state.
///
/// Blocks and SMT roots remain the canonical source for balances and applied block
/// economics. This sidecar carries the deterministic post-apply controller state
/// needed by a follower imported from snapshot to continue with the same
/// prospective fee/emission policy without replaying from genesis. The sidecar is
/// stored in the hashed snapshot payload header and mirrored in storage meta only
/// after import validation.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub(crate) struct SnapshotEconomyStateV1 {
    pub version: u32,
    pub height: u64,
    pub base_height: u64,
    pub block_hash: String,
    pub state_root: String,
    pub genesis_hash: String,
    pub total_supply: u64,
    pub treasury_balance: u64,
    /// Base fee actually committed by the snapshot tip block/state-root.
    pub tip_applied_base_fee_per_tx: Option<u64>,
    /// Post-tip prospective policy/controller state used for the next block.
    pub policy: MonetaryPolicy,
    pub policy_hash_hex: String,
}

impl SnapshotEconomyStateV1 {
    pub(crate) fn policy_hash_for(policy: &MonetaryPolicy) -> Result<String, String> {
        let bytes = serde_json::to_vec(policy)
            .map_err(|e| format!("snapshot economy policy serialize failed: {e}"))?;
        let mut h = Sha256::new();
        h.update(&bytes);
        Ok(hex::encode(h.finalize()))
    }

    pub(crate) fn validate_basic(&self) -> Result<(), String> {
        if self.version != SNAPSHOT_ECONOMY_STATE_VERSION_V1 {
            return Err(format!(
                "snapshot economy state unsupported version: {}",
                self.version
            ));
        }
        if self.height < self.base_height {
            return Err(format!(
                "snapshot economy state invalid height/base_height: {} < {}",
                self.height, self.base_height
            ));
        }
        let is_hex32 = |value: &str| -> bool {
            let value = value.trim();
            value.len() == 64 && value.as_bytes().iter().all(|b| b.is_ascii_hexdigit())
        };
        if !is_hex32(&self.block_hash) {
            return Err("snapshot economy state block_hash must be 32-byte hex".to_string());
        }
        if self.state_root.trim() != "0" && !is_hex32(&self.state_root) {
            return Err("snapshot economy state state_root must be 32-byte hex or 0".to_string());
        }
        if !is_hex32(&self.genesis_hash) {
            return Err("snapshot economy state genesis_hash must be 32-byte hex".to_string());
        }
        let expected = Self::policy_hash_for(&self.policy)?;
        if self.policy_hash_hex.trim() != expected {
            return Err("snapshot economy state policy_hash mismatch".to_string());
        }
        Ok(())
    }
}

