    pub(crate) fn taper_days_remaining_for_api(&self) -> u64 {
        if self.policy.emission_state.phase != EmissionSunsetPhase::Taper {
            return 0;
        }
        let start = self
            .policy
            .emission_state
            .phase_start_day_index
            .unwrap_or(self.policy.emission_window.current_day_index);
        let elapsed = self
            .policy
            .emission_window
            .current_day_index
            .saturating_sub(start);
        (self.policy.emission_controller.taper_days as u64).saturating_sub(elapsed)
    }

