    #[cfg(test)]
    pub(crate) fn seed_attached_storage_with_genesis_state_for_tests(
        &mut self,
    ) -> Result<(), String> {
        let Some(genesis) = self.chain.first() else {
            return Ok(());
        };
        let expected_root = self.validate_block_nft_events_v1("", genesis)?;
        let existing_root = genesis.state_root.trim();
        if !existing_root.is_empty() && existing_root != expected_root {
            return Err(format!(
                "test_genesis_state_root_mismatch:{}:{}:{}",
                genesis.index, existing_root, expected_root
            ));
        }
        Ok(())
    }

