    fn governance_ingress_wal_replay_skips_vote_with_invalid_signature() {
        let _guard = governance_ingress_test_lock();
        let data_dir = std::env::temp_dir().join(format!(
            "newgen_gov_ingress_skip_bad_vote_sig_{}_{}",
            std::process::id(),
            1u64
        ));
        let _ = std::fs::remove_dir_all(&data_dir);
        std::fs::create_dir_all(&data_dir).unwrap();
        std::env::set_var(EFFECTIVE_DATA_DIR_ENV, &data_dir);
        std::env::set_var("NEWGEN_GOVERNANCE_INGRESS_DURABLE", "1");
        std::env::remove_var("NEWGEN_GOVERNANCE_INGRESS_WAL_PATH");

        let mut chain = Blockchain::new();
        let id = "wal-bad-sig-govp-00000000000000000000000000000001";
        install_pending_proposal_for_vote(&mut chain, id);
        let mut bad_vote = vote(id);
        bad_vote.signature = "not-valid-base64-signature".to_string();

        let wal_path = governance_ingress_wal_path_v1().expect("wal path");
        if let Some(parent) = wal_path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        let bad = GovernanceIngressWalRecordV1 {
            version: GOVERNANCE_INGRESS_WAL_VERSION_V1,
            op: GovernanceIngressWalOpV1::Enqueue,
            tx: crate::governance::GovernanceTx::Vote(bad_vote),
        };
        std::fs::write(
            &wal_path,
            format!("{}\n", serde_json::to_string(&bad).unwrap()),
        )
        .unwrap();

        let restored = chain
            .replay_durable_governance_ingress_wal_v1()
            .expect("wal replay should skip invalid vote signatures without failing");
        assert_eq!(restored, 0);
        assert_eq!(chain.pending_governance_queue_len_v1(), 0);
        assert!(!wal_text().contains(id));

        std::env::remove_var(EFFECTIVE_DATA_DIR_ENV);
        std::env::remove_var("NEWGEN_GOVERNANCE_INGRESS_DURABLE");
        let _ = std::fs::remove_dir_all(&data_dir);
    }

