    #[test]
    fn governance_ingress_wal_replay_skips_noncanonical_records() {
        let _guard = governance_ingress_test_lock();
        let data_dir = std::env::temp_dir().join(format!(
            "newgen_gov_ingress_skip_noncanonical_{}_{}",
            std::process::id(),
            1u64
        ));
        let _ = std::fs::remove_dir_all(&data_dir);
        std::fs::create_dir_all(&data_dir).unwrap();
        std::env::set_var(EFFECTIVE_DATA_DIR_ENV, &data_dir);
        std::env::set_var("NEWGEN_GOVERNANCE_INGRESS_DURABLE", "1");
        std::env::remove_var("NEWGEN_GOVERNANCE_INGRESS_WAL_PATH");

        let valid_id = "wal-valid-govp-00000000000000000000000000000001";
        let wal_path = governance_ingress_wal_path_v1().expect("wal path");
        if let Some(parent) = wal_path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        let bad = GovernanceIngressWalRecordV1 {
            version: GOVERNANCE_INGRESS_WAL_VERSION_V1,
            op: GovernanceIngressWalOpV1::Enqueue,
            tx: crate::governance::GovernanceTx::Proposal(proposal("p-legacy")),
        };
        let good = GovernanceIngressWalRecordV1 {
            version: GOVERNANCE_INGRESS_WAL_VERSION_V1,
            op: GovernanceIngressWalOpV1::Enqueue,
            tx: crate::governance::GovernanceTx::Proposal(proposal(valid_id)),
        };
        let mut raw = String::new();
        raw.push_str(&serde_json::to_string(&bad).unwrap());
        raw.push('\n');
        raw.push_str(&serde_json::to_string(&good).unwrap());
        raw.push('\n');
        std::fs::write(&wal_path, raw).unwrap();

        let mut restarted = Blockchain::new();
        let restored = restarted
            .replay_durable_governance_ingress_wal_v1()
            .expect("wal replay should skip noncanonical records without failing");
        assert_eq!(restored, 1);
        assert_eq!(restarted.pending_governance_queue_len_v1(), 1);
        let wal = wal_text();
        assert!(!wal.contains("p-legacy"));
        assert!(wal.contains(valid_id));

        std::env::remove_var(EFFECTIVE_DATA_DIR_ENV);
        std::env::remove_var("NEWGEN_GOVERNANCE_INGRESS_DURABLE");
        let _ = std::fs::remove_dir_all(&data_dir);
    }

    #[test]
    fn governance_ingress_drain_and_restore_preserve_fifo_order() {
        let _guard = governance_ingress_test_lock();
        std::env::remove_var("NEWGEN_GOVERNANCE_INGRESS_WAL_PATH");
        std::env::remove_var(EFFECTIVE_DATA_DIR_ENV);
        let mut chain = Blockchain::new();
        chain
            .enqueue_governance_proposal_v1(proposal(
                "fifo-one-govp-00000000000000000000000000000001",
            ))
            .unwrap();
        chain
            .enqueue_governance_proposal_v1(proposal(
                "fifo-two-govp-00000000000000000000000000000002",
            ))
            .unwrap();

        let drained = chain.drain_pending_governance_txs_for_block_v1(10, &test_sk(), 16);
        assert_eq!(drained.len(), 2);
        assert_eq!(chain.pending_governance_queue_len_v1(), 0);

        chain.restore_pending_governance_txs_front_v1(drained);
        assert_eq!(chain.pending_governance_queue_len_v1(), 2);

        let drained_again = chain.drain_pending_governance_txs_for_block_v1(10, &test_sk(), 16);
        let ids: Vec<String> = drained_again
            .iter()
            .filter_map(|tx| match tx {
                crate::governance::GovernanceTx::Proposal(p) => Some(p.id.clone()),
                _ => None,
            })
            .collect();
        assert_eq!(
            ids,
            vec![
                "fifo-one-govp-00000000000000000000000000000001".to_string(),
                "fifo-two-govp-00000000000000000000000000000002".to_string()
            ]
        );
    }

    #[test]
    fn governance_ingress_vote_requires_existing_pending_proposal() {
        let _guard = governance_ingress_test_lock();
        std::env::remove_var("NEWGEN_GOVERNANCE_INGRESS_WAL_PATH");
        std::env::remove_var(EFFECTIVE_DATA_DIR_ENV);
        let mut chain = Blockchain::new();
        let missing = chain
            .enqueue_governance_vote_v1(vote("missing-govp-00000000000000000000000000000001"))
            .expect_err("unknown proposal rejected");
        assert!(matches!(
            missing,
            GovernanceIngressError::ProposalNotFound(id) if id == "missing-govp-00000000000000000000000000000001"
        ));

        install_pending_proposal_for_vote(
            &mut chain,
            "vote-one-govp-00000000000000000000000000000001",
        );
        let accepted = chain
            .enqueue_governance_vote_v1(vote("vote-one-govp-00000000000000000000000000000001"))
            .expect("valid council vote queued");
        assert_eq!(
            accepted.proposal_id,
            "vote-one-govp-00000000000000000000000000000001"
        );
        assert_eq!(accepted.queue_depth, 1);

        let dup = chain
            .enqueue_governance_vote_v1(vote("vote-one-govp-00000000000000000000000000000001"))
            .expect_err("duplicate pending vote rejected");
        assert!(matches!(dup, GovernanceIngressError::DuplicateVote { .. }));
    }

    #[test]
    fn governance_ingress_pending_vote_key_is_hash_aware_and_stale_hash_does_not_block_revote() {
        let _guard = governance_ingress_test_lock();
        std::env::remove_var("NEWGEN_GOVERNANCE_INGRESS_WAL_PATH");
        std::env::remove_var(EFFECTIVE_DATA_DIR_ENV);
        let mut chain = Blockchain::new();
        install_pending_proposal_for_vote(
            &mut chain,
            "vote-rehash-govp-00000000000000000000000000000001",
        );

        let voter_hex = crate::keyfmt::pk_hex_from_any(&test_pk_b64()).unwrap();
        let stale_hash = "22".repeat(32);
        let current_hash = "11".repeat(32);
        let stale_key = governance_vote_pending_key_v1(
            "vote-rehash-govp-00000000000000000000000000000001",
            &voter_hex,
            &stale_hash,
        );
        let current_key = governance_vote_pending_key_v1(
            "vote-rehash-govp-00000000000000000000000000000001",
            &voter_hex,
            &current_hash,
        );
        assert_ne!(
            stale_key, current_key,
            "runtime pending vote dedupe must be hash-aware"
        );

        chain.pending_governance_vote_ids.insert(stale_key);
        chain
            .pending_governance_txs
            .push_back(crate::governance::GovernanceTx::Vote(vote_with_hash(
                "vote-rehash-govp-00000000000000000000000000000001",
                &stale_hash,
            )));

        let accepted = chain
            .enqueue_governance_vote_v1(vote_with_hash(
                "vote-rehash-govp-00000000000000000000000000000001",
                &current_hash,
            ))
            .expect("current-hash revote must not be blocked by stale pending vote");
        assert_eq!(
            accepted.proposal_id,
            "vote-rehash-govp-00000000000000000000000000000001"
        );
        assert!(chain.pending_governance_vote_ids.contains(&current_key));
    }

