    fn open_test_storage(label: &str) -> Arc<crate::storage::DbStore> {
        Arc::new(crate::storage::open_clean_test_dbstore(label).unwrap())
    }

    fn linear_blocks(count: u64) -> Vec<Block> {
        let template = Blockchain::new();
        let mut out = Vec::new();
        let mut prev_hash = "0".to_string();
        for idx in 0..count {
            let mut block = template.create_block_dummy();
            block.index = idx;
            block.previous_hash = prev_hash.clone();
            block.timestamp = idx + 1;
            block.hash = block.calculate_hash();
            prev_hash = block.hash.clone();
            out.push(block);
        }
        out
    }

    fn put_tip_economy_snapshot_for_blocks(
        storage: &Arc<crate::storage::DbStore>,
        blocks: &[Block],
        base_height: u64,
    ) {
        let tip = blocks.last().expect("test chain must have a tip");
        let mut chain = Blockchain::from_blocks(blocks.to_vec());
        chain.base_height = base_height;
        let snap = chain
            .build_snapshot_economy_state_v1(tip)
            .expect("test economy snapshot must be buildable");
        let json = serde_json::to_string(&snap).expect("test economy snapshot must serialize");
        storage
            .put_economy_snapshot(tip.index, &json, false)
            .expect("test economy snapshot must persist");
    }

    fn put_test_finality_meta_for_blocks(storage: &Arc<crate::storage::DbStore>, blocks: &[Block]) {
        let tip = blocks
            .last()
            .expect("test finality fixture requires a non-empty block window");
        let finalized_height = tip.index;
        let finalized_hash = tip.hash.clone();
        let finality_json = serde_json::json!({
            "finalized_height": finalized_height,
            "finalized_hash": finalized_hash.clone(),
            "highest_qc_height": finalized_height,
            "highest_qc_round": 0u32,
            "highest_qc_block_hash": finalized_hash.clone(),
        })
        .to_string();
        storage
            .finality_bft_meta_store()
            .insert_sync(b"finality_bft_meta_v1", finality_json.as_bytes())
            .expect("test finality metadata must persist before validator-capable snapshot export");
    }

    fn build_pos_state_root(
        storage: &Arc<crate::storage::DbStore>,
        committee: &[(String, u64)],
        epoch_len: u64,
    ) -> String {
        build_pos_state_root_with_epoch_committees(storage, &[committee.to_vec()], epoch_len)
    }

    fn build_pos_state_root_with_epoch_committees(
        storage: &Arc<crate::storage::DbStore>,
        epoch_committees: &[Vec<(String, u64)>],
        epoch_len: u64,
    ) -> String {
        let smt = StateSmt::new(storage.state_node_store());
        let mut root = smt.empty_root();
        let committee_size = epoch_committees
            .iter()
            .map(|c| c.len() as u64)
            .max()
            .unwrap_or(1);

        let params = crate::staking::PosParamsV1 {
            min_stake: 1,
            unbonding_epochs: 1,
            epoch_len,
            committee_size,
        };
        root = smt
            .update_account(
                root,
                crate::staking::k_stake_params(),
                crate::staking::encode_params_state(&params).unwrap(),
            )
            .unwrap();

        for (epoch, committee) in epoch_committees.iter().enumerate() {
            let seed = [11u8.saturating_add(epoch as u8); 32];
            root = smt
                .update_account(
                    root,
                    crate::pos::k_seed(epoch as u64),
                    crate::pos::encode_seed_state(&seed).unwrap(),
                )
                .unwrap();

            let committee_state = crate::pos::CommitteeV2 {
                members: committee
                    .iter()
                    .map(|(pk, stake)| crate::pos::CommitteeMemberV2 {
                        pk_hex: pk.clone(),
                        stake: *stake,
                    })
                    .collect(),
            };
            root = smt
                .update_account(
                    root,
                    crate::pos::k_committee(epoch as u64),
                    crate::pos::encode_committee_state_v2(&committee_state).unwrap(),
                )
                .unwrap();
        }

        use std::collections::BTreeMap;
        let mut validators: BTreeMap<String, u64> = BTreeMap::new();
        for committee in epoch_committees.iter() {
            for (pk, stake) in committee.iter() {
                let entry = validators.entry(pk.clone()).or_insert(0);
                *entry = (*entry).max(*stake);
            }
        }
        for (idx, (pk, stake)) in validators.into_iter().enumerate() {
            let rec = crate::staking::ValidatorRecordV1 {
                owner: format!("owner-{}", idx),
                consensus_pubkey_b64: pk.clone(),
                net_addr: String::new(),
                commission_bps: 0,
                status: crate::staking::ValidatorStatusV1::Active,
                bonded: stake,
                jailed_until_epoch: 0,
                metadata: String::new(),
            };
            root = smt
                .update_account(
                    root,
                    crate::staking::k_validator(&pk),
                    crate::staking::encode_validator_state(&rec).unwrap(),
                )
                .unwrap();
        }

        hex::encode(root)
    }

    fn build_pos_params_only_state_root(
        storage: &Arc<crate::storage::DbStore>,
        params: crate::staking::PosParamsV1,
    ) -> String {
        let smt = StateSmt::new(storage.state_node_store());
        let mut root = smt.empty_root();
        root = smt
            .update_account(
                root,
                crate::staking::k_stake_params(),
                crate::staking::encode_params_state(&params).unwrap(),
            )
            .unwrap();
        hex::encode(root)
    }

    fn append_linear_chain_with_state_roots_to_storage(
        storage: &Arc<crate::storage::DbStore>,
        state_roots: &[String],
        miner_cycle: &[String],
    ) -> Vec<Block> {
        assert!(!state_roots.is_empty(), "state_roots must not be empty");
        assert!(!miner_cycle.is_empty(), "miner_cycle must not be empty");
        let tip_height = state_roots.len().saturating_sub(1) as u64;
        let mut genesis = Blockchain::new().chain[0].clone();
        genesis.state_root = state_roots[0].clone();
        genesis.hash = genesis.calculate_hash();
        storage.append_block(&genesis).unwrap();

        let mut out = vec![genesis.clone()];
        let mut prev = genesis;
        for idx in 1..=tip_height {
            let mut blk = prev.clone();
            blk.index = idx;
            blk.previous_hash = prev.hash.clone();
            blk.timestamp = prev.timestamp.saturating_add(30);
            blk.transactions.clear();
            blk.state_root = state_roots[idx as usize].clone();
            blk.miner_pub_key = miner_cycle[(idx as usize - 1) % miner_cycle.len()].clone();
            blk.hash = blk.calculate_hash();
            storage.append_block(&blk).unwrap();
            out.push(blk.clone());
            prev = blk;
        }
        put_tip_economy_snapshot_for_blocks(
            storage,
            &out,
            out.first().map(|b| b.index).unwrap_or(0),
        );
        put_test_finality_meta_for_blocks(storage, &out);
        out
    }

    fn append_linear_chain_to_storage(
        storage: &Arc<crate::storage::DbStore>,
        tip_height: u64,
        state_root: &str,
        miner_cycle: &[String],
    ) -> Vec<Block> {
        assert!(!miner_cycle.is_empty(), "miner_cycle must not be empty");
        let mut genesis = Blockchain::new().chain[0].clone();
        genesis.state_root = state_root.to_string();
        genesis.hash = genesis.calculate_hash();
        storage.append_block(&genesis).unwrap();

        let mut out = vec![genesis.clone()];
        let mut prev = genesis;
        for idx in 1..=tip_height {
            let mut blk = prev.clone();
            blk.index = idx;
            blk.previous_hash = prev.hash.clone();
            blk.timestamp = prev.timestamp.saturating_add(30);
            blk.transactions.clear();
            blk.state_root = state_root.to_string();
            blk.miner_pub_key = miner_cycle[(idx as usize - 1) % miner_cycle.len()].clone();
            blk.hash = blk.calculate_hash();
            storage.append_block(&blk).unwrap();
            out.push(blk.clone());
            prev = blk;
        }
        put_tip_economy_snapshot_for_blocks(
            storage,
            &out,
            out.first().map(|b| b.index).unwrap_or(0),
        );
        put_test_finality_meta_for_blocks(storage, &out);
        out
    }

    fn load_blocks_from_storage(
        storage: &Arc<crate::storage::DbStore>,
        tip_height: u64,
    ) -> Vec<Block> {
        (0..=tip_height)
            .map(|h| storage.get_block(h).unwrap().unwrap())
            .collect()
    }

    fn import_snapshot_bootstrap_chain_multi_epoch() -> (
        Blockchain,
        GovernanceState,
        Block,
        Arc<crate::storage::DbStore>,
        crate::snapshot::SnapshotConsensusBootstrapContext,
        Vec<(String, u64)>,
        Vec<(String, u64)>,
    ) {
        let export_storage = open_test_storage("snapshot_import_bootstrap_multiepoch_export");
        let a = test_validator_pk_hex(0x91);
        let b = test_validator_pk_hex(0x92);
        let c = test_validator_pk_hex(0x93);
        let e0 = vec![(a.clone(), 11), (b.clone(), 17), (c.clone(), 23)];
        let e1 = vec![(a.clone(), 13), (b.clone(), 19), (c.clone(), 29)];
        let e2 = vec![(a.clone(), 31), (b.clone(), 37), (c.clone(), 41)];
        let e3 = vec![(a.clone(), 43), (b.clone(), 47), (c.clone(), 53)];
        let e4 = vec![(a.clone(), 59), (b.clone(), 61), (c.clone(), 67)];
        let epoch_len = 10;
        let tip_height = 29u64;
        let state_root = build_pos_state_root_with_epoch_committees(
            &export_storage,
            &[e0.clone(), e1.clone(), e2.clone(), e3.clone(), e4.clone()],
            epoch_len,
        );
        let miner_cycle = vec![a.clone(), b.clone(), c.clone()];
        append_linear_chain_to_storage(&export_storage, tip_height, &state_root, &miner_cycle);

        let bundle_dir = tempfile::tempdir().unwrap();
        let meta = export_storage
            .export_snapshot_v2_bundle(
                bundle_dir.path(),
                Some(tip_height),
                Some(0),
                true,
                true,
                64 * 1024,
                10 * 1024 * 1024,
            )
            .unwrap();
        let _ctx = meta
            .consensus_bootstrap_context
            .clone()
            .expect("snapshot export must include consensus bootstrap context");

        let import_storage = open_test_storage("snapshot_import_bootstrap_multiepoch_import");
        import_storage
            .import_snapshot_v2_bundle(bundle_dir.path(), true)
            .unwrap();
        let persisted_ctx = import_storage
            .get_snapshot_consensus_bootstrap_context()
            .unwrap()
            .expect("import must persist consensus bootstrap context");
        import_storage.clear_state_nodes().unwrap();

        let mut bc = Blockchain::from_blocks_with_storage(
            load_blocks_from_storage(&import_storage, tip_height),
            import_storage.clone(),
        );
        let gov = test_governance(&[(a.clone(), 1), (b.clone(), 1), (c.clone(), 1)]);
        bc.governance = Some(gov.clone());
        let prev = bc.chain.last().cloned().unwrap();

        (bc, gov, prev, import_storage, persisted_ctx, e2, e3)
    }

    fn test_chain_with_prev_block(
        committee: &[(String, u64)],
        validator_weights: &[(String, u32)],
        prev_timestamp: u64,
    ) -> (
        Blockchain,
        GovernanceState,
        Block,
        Arc<crate::storage::DbStore>,
    ) {
        let storage = open_test_storage("consensus_diag");
        let state_root = build_pos_state_root(&storage, committee, 100);
        let mut bc = Blockchain::new();
        bc.attach_storage(storage.clone());
        let gov = test_governance(validator_weights);
        bc.governance = Some(gov.clone());
        bc.chain[0].state_root = state_root.clone();

        let mut prev = bc.chain[0].clone();
        prev.index = 1;
        prev.timestamp = prev_timestamp;
        prev.state_root = state_root;
        prev.hash = "prev-h1".to_string();
        prev.previous_hash = bc.chain[0].hash.clone();
        bc.chain.push(prev.clone());

        (bc, gov, prev, storage)
    }

    #[test]
    fn committee_resolution_falls_back_cleanly_when_historical_state_nodes_are_missing() {
        let _lock = test_process_lock();
        let a = test_validator_pk_hex(0x31);
        let b = test_validator_pk_hex(0x32);
        let c = test_validator_pk_hex(0x33);
        let committee = vec![(a.clone(), 11), (b.clone(), 17), (c.clone(), 23)];
        let validator_weights = vec![(a.clone(), 3), (b.clone(), 5), (c.clone(), 7)];
        let (bc, gov, prev, storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);

        storage.clear_state_nodes().unwrap();

        let (epoch, resolved) = bc
            .resolve_committee_view_at_state_root_diagnostic(&prev.state_root, 2, Some(&gov))
            .unwrap();

        assert_eq!(epoch, bc.fallback_pos_epoch_for_height(2));
        assert_eq!(
            resolved.resolution_mode,
            ConsensusResolutionMode::CanonicalFallback
        );
        assert!(resolved.consensus_stake_weights.is_empty());
        assert_eq!(
            resolved.members,
            bc.canonical_active_validator_pubkeys_hex_at_with_gov(Some(&gov), 2)
        );
    }

    #[test]
    fn reachable_snapshot_without_consensus_bootstrap_blocks_validator_runtime() {
        let _lock = test_process_lock();
        let storage = open_test_storage("reachable_snapshot_missing_bootstrap_blocks_validator");
        let a = test_validator_pk_hex(0xa1);
        let b = test_validator_pk_hex(0xa2);
        let c = test_validator_pk_hex(0xa3);
        let state_root = build_pos_state_root(
            &storage,
            &[(a.clone(), 11), (b.clone(), 17), (c.clone(), 23)],
            10,
        );

        let mut bc = Blockchain::new();
        bc.attach_storage(storage.clone());
        bc.governance = Some(test_governance(&[
            (a.clone(), 1),
            (b.clone(), 1),
            (c.clone(), 1),
        ]));
        bc.chain[0].state_root = state_root.clone();

        storage
            .put_snapshot_reachable_state_import_marker(
                &crate::storage::SnapshotReachableStateImportMarker {
                    height: 0,
                    state_root: state_root.clone(),
                    window_from_height: 0,
                    window_to_height: 0,
                    state_coverage_mode:
                        crate::snapshot::SnapshotStateCoverageMode::TipReachableOnly,
                    historical_state_roots_queryable: false,
                },
                false,
            )
            .unwrap();
        storage
            .clear_snapshot_consensus_bootstrap_context(false)
            .unwrap();

        let err = bc
            .runtime_consensus_bootstrap_ready_for_next_height()
            .unwrap_err();
        assert!(
            err.contains("local_snapshot_consensus_context_invalid:bootstrap_context_required_after_reachable_snapshot"),
            "unexpected error: {}",
            err
        );

        let view = bc.local_consensus_runtime_view_for_next_block();
        assert!(!view.consensus_bootstrap_ready);
        assert_eq!(
            view.consensus_bootstrap_fault.unwrap().scope,
            "bootstrap_context_required_after_reachable_snapshot"
        );
    }

    #[test]
    fn proposer_selection_fails_closed_when_committee_is_missing_without_canonical_fallback() {
        let _lock = test_process_lock();
        let storage = open_test_storage("proposer_missing_committee_fails_closed");
        let state_root = build_pos_params_only_state_root(
            &storage,
            crate::staking::PosParamsV1 {
                min_stake: 1,
                unbonding_epochs: 7,
                epoch_len: 10,
                committee_size: 3,
            },
        );
        let mut bc = Blockchain::new();
        bc.attach_storage(storage.clone());
        let a = test_validator_pk_hex(0xb1);
        let b = test_validator_pk_hex(0xb2);
        let c = test_validator_pk_hex(0xb3);
        let gov = test_governance(&[(a.clone(), 1), (b.clone(), 1), (c.clone(), 1)]);
        bc.governance = Some(gov.clone());
        bc.chain[0].state_root = state_root.clone();

        let err = bc
            .expected_pos_proposer_for_slot_round_at_state_root(&state_root, 1, 1, 0, Some(&gov))
            .unwrap_err();
        assert!(
            err.contains("local_snapshot_consensus_context_invalid:committee_missing")
                || err.contains("consensus_context_committee_empty"),
            "unexpected error: {}",
            err
        );
        assert!(
            !err.contains("canonical_fallback"),
            "proposer selection must not use canonical fallback: {}",
            err
        );
    }

