    #[test]
    fn strict_snapshot_consensus_context_rejects_live_pos_params_mismatch() {
        let _lock = test_process_lock();
        let e0 = vec![
            (test_validator_pk_hex(0xe1), 11),
            (test_validator_pk_hex(0xe2), 17),
            (test_validator_pk_hex(0xe3), 23),
        ];
        let e1 = vec![
            (test_validator_pk_hex(0xf1), 13),
            (test_validator_pk_hex(0xf2), 19),
            (test_validator_pk_hex(0xf3), 29),
        ];
        let storage = open_test_storage("strict_snapshot_consensus_ctx_params_mismatch");
        let state_root =
            build_pos_state_root_with_epoch_committees(&storage, &[e0.clone(), e1.clone()], 10);
        let mut bc = Blockchain::new();
        bc.attach_storage(storage.clone());
        let gov = test_governance(&[
            (e0[0].0.clone(), 1),
            (e0[1].0.clone(), 1),
            (e0[2].0.clone(), 1),
            (e1[0].0.clone(), 1),
            (e1[1].0.clone(), 1),
            (e1[2].0.clone(), 1),
        ]);
        bc.governance = Some(gov.clone());
        bc.chain[0].state_root = state_root.clone();

        let mut prev = bc.chain[0].clone();
        prev.index = 15;
        prev.timestamp = 150;
        prev.state_root = state_root;
        prev.hash = "strict-prev-h15".to_string();
        prev.previous_hash = bc.chain[0].hash.clone();
        bc.chain.push(prev.clone());

        let wrong_params = crate::staking::PosParamsV1 {
            min_stake: 1,
            unbonding_epochs: 1,
            epoch_len: 8,
            committee_size: 2,
        };
        let ctx = crate::snapshot::SnapshotConsensusBootstrapContext::from_epoch_contexts(
            prev.index,
            prev.state_root.clone(),
            vec![crate::snapshot::SnapshotConsensusEpochBootstrapContext {
                epoch: 2,
                coverage_start_height: 16,
                coverage_end_height: 23,
                pos_params: wrong_params,
                params_source: Some(crate::snapshot::SnapshotConsensusContextSource {
                    block_height: Some(prev.index),
                    state_root: prev.state_root.clone(),
                    kind: crate::snapshot::SnapshotConsensusContextSourceKind::SnapshotStateRoot,
                }),
                seed_source: None,
                committee_source: None,
                legacy_params_source_height: None,
                legacy_params_source_state_root: None,
                seed_epoch: 2,
                seed_hex: hex::encode([13u8; 32]),
                committee: crate::snapshot::SnapshotConsensusCommitteeContext::V2 {
                    members: e1
                        .iter()
                        .map(|(pk, stake)| crate::pos::CommitteeMemberV2 {
                            pk_hex: pk.clone(),
                            stake: *stake,
                        })
                        .collect(),
                },
            }],
        );
        storage
            .put_snapshot_consensus_bootstrap_context(&ctx, false)
            .unwrap();

        let err = bc
            .resolve_pos_epoch_context_strict_at_state_root(&prev.state_root, 16, Some(&gov))
            .unwrap_err();
        assert!(
            err.contains("local_snapshot_consensus_context_invalid:pos_params_mismatch"),
            "unexpected error: {}",
            err
        );

        let ready_err = bc
            .runtime_consensus_bootstrap_ready_for_next_height()
            .unwrap_err();
        assert!(
            ready_err.contains("local_snapshot_consensus_context_invalid:pos_params_mismatch"),
            "unexpected runtime bootstrap error: {}",
            ready_err
        );

        let local_view = bc.local_consensus_runtime_view_for_next_block();
        assert!(!local_view.consensus_bootstrap_ready);
        assert_eq!(local_view.consensus_bootstrap_next_height, 16);
        let fault = local_view
            .consensus_bootstrap_fault
            .expect("local runtime view must expose bootstrap fault");
        assert_eq!(
            fault.class,
            LocalConsensusBootstrapFaultClass::SnapshotContextInvalid
        );
        assert_eq!(fault.scope, "pos_params_mismatch");
    }

    #[test]
    fn extract_local_post_snapshot_consensus_fault_parses_scope_and_detail() {
        let fault = Blockchain::extract_local_post_snapshot_consensus_fault(
            "consensus_context_expected_proposer_failed:height=16 slot=1 err=local_snapshot_consensus_context_invalid:committee_mismatch:height=16 epoch=2",
        )
        .expect("fault must be parsed");
        assert_eq!(
            fault.class,
            LocalConsensusBootstrapFaultClass::SnapshotContextInvalid
        );
        assert_eq!(fault.scope, "committee_mismatch");
        assert!(fault
            .detail
            .as_deref()
            .unwrap_or_default()
            .contains("height=16 epoch=2"));
    }

