    #[test]
    fn finality_receive_vote_ignores_snapshot_limited_historical_state_without_error() {
        let _lock = test_process_lock();
        let (_seed_a, a, a_sk_b64) = test_signing_key_material(0x54);
        let b = test_validator_pk_hex(0x55);
        let c = test_validator_pk_hex(0x56);
        let committee = vec![(a.clone(), 11), (b.clone(), 17), (c.clone(), 23)];
        let validator_weights = vec![(a.clone(), 3), (b.clone(), 5), (c.clone(), 7)];
        let (mut bc, gov, prev, storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);
        bc.governance = Some(gov.clone());

        let mut blk = prev.clone();
        blk.index = 2;
        blk.timestamp = 40;
        blk.miner_pub_key = a.clone();
        blk.pos_round = 0;
        blk.pos_epoch = 0;
        blk.pos_slot = bc.slot_of_ts(blk.timestamp);
        blk.hash = "ab".repeat(32);
        bc.chain.push(blk.clone());

        storage.clear_state_nodes().unwrap();

        let sk_bytes = STANDARD.decode(a_sk_b64).unwrap();
        let sk_arr: [u8; 32] = sk_bytes.as_slice().try_into().unwrap();
        let sk = SigningKey::from_bytes(&sk_arr);
        let vote = finality_bft::sign_vote_v1(
            &sk,
            crate::chain_identity::chain_id(),
            0,
            blk.index,
            blk.pos_round,
            &blk.hash,
        )
        .unwrap();

        let res = bc.finality_bft_receive_vote_v1(vote).unwrap();
        assert!(res.is_none(), "snapshot-limited vote ingest must fail-soft");
    }

