    #[test]
    fn downtime_skip_plan_only_updates_current_producer() {
        let a = test_validator_pk_hex(0x11);
        let b = test_validator_pk_hex(0x22);
        let c = test_validator_pk_hex(0x33);

        let mut gov = test_governance(&[(a.clone(), 10), (b.clone(), 20), (c.clone(), 30)]);
        gov.validator_reputation.insert(
            a.clone(),
            ValidatorGovReputation {
                downtime_consecutive_missed_turns: 7,
                last_produced_height: 9,
                last_seen_height: 12,
                ..ValidatorGovReputation::default()
            },
        );
        gov.validator_reputation.insert(
            b.clone(),
            ValidatorGovReputation {
                downtime_consecutive_missed_turns: 5,
                last_produced_height: 8,
                last_seen_height: 10,
                ..ValidatorGovReputation::default()
            },
        );
        gov.validator_reputation.insert(
            c.clone(),
            ValidatorGovReputation {
                downtime_consecutive_missed_turns: 6,
                last_produced_height: 7,
                last_seen_height: 11,
                ..ValidatorGovReputation::default()
            },
        );

        let mut curr = Blockchain::new().create_block_dummy();
        curr.index = 42;
        curr.miner_pub_key = a.clone();

        let plan = DowntimePlan {
            skip_missed_turn_attribution: true,
            gap_slots: 9,
            max_gap_slots: 2,
            unique_validator_count: 3,
            expected_missed_proposers: Vec::new(),
            producer_pk_hex: Some(a.clone()),
            warning: Some("test_skip".to_string()),
        };

        let policy = Blockchain::new().policy.clone();
        Blockchain::apply_downtime_policy_plan(&mut gov, &curr, &policy, None, plan);

        let rep_a = gov.validator_reputation.get(&a).unwrap();
        let rep_b = gov.validator_reputation.get(&b).unwrap();
        let rep_c = gov.validator_reputation.get(&c).unwrap();

        assert_eq!(rep_a.last_produced_height, 42);
        assert_eq!(rep_a.last_seen_height, 42);
        assert_eq!(rep_a.downtime_consecutive_missed_turns, 0);
        assert_eq!(rep_b.last_produced_height, 8);
        assert_eq!(rep_b.last_seen_height, 10);
        assert_eq!(rep_b.downtime_consecutive_missed_turns, 5);
        assert_eq!(rep_c.last_produced_height, 7);
        assert_eq!(rep_c.last_seen_height, 11);
        assert_eq!(rep_c.downtime_consecutive_missed_turns, 6);
    }

    #[test]
    fn downtime_plan_uses_real_expected_proposers_for_missed_slots() {
        let _lock = test_process_lock();
        let a = test_validator_pk_hex(0x41);
        let b = test_validator_pk_hex(0x42);
        let c = test_validator_pk_hex(0x43);
        let committee = vec![(a.clone(), 11), (b.clone(), 17), (c.clone(), 23)];
        let validator_weights = vec![(a.clone(), 1), (b.clone(), 1), (c.clone(), 1)];
        let (bc, gov, prev, _storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);

        let mut curr = prev.clone();
        curr.index = 2;
        curr.timestamp = 40;
        curr.miner_pub_key = a.clone();

        let plan = bc.plan_downtime_policy_between_blocks(&gov, &prev, &curr, 0, 10, true);
        assert!(!plan.skip_missed_turn_attribution);
        assert_eq!(plan.expected_missed_proposers.len(), 2);

        let expected: Vec<String> = (2..4)
            .map(|slot| {
                bc.expected_pos_proposer_for_slot_round_at_state_root(
                    &prev.state_root,
                    curr.index,
                    slot,
                    0,
                    Some(&gov),
                )
                .unwrap()
            })
            .collect();

        assert_eq!(plan.expected_missed_proposers, expected);
    }

    #[test]
    fn validator_outside_committee_is_not_penalized_and_status_marks_it_ineligible() {
        let _lock = test_process_lock();
        let a = test_validator_pk_hex(0x51);
        let b = test_validator_pk_hex(0x52);
        let c = test_validator_pk_hex(0x53);
        let committee = vec![(a.clone(), 13), (b.clone(), 19)];
        let validator_weights = vec![(a.clone(), 3), (b.clone(), 5), (c.clone(), 7)];
        let (mut bc, gov, prev, _storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);
        bc.governance = Some(gov.clone());

        let mut curr = prev.clone();
        curr.index = 2;
        curr.timestamp = 40;
        curr.miner_pub_key = a.clone();

        let plan = bc.plan_downtime_policy_between_blocks(&gov, &prev, &curr, 0, 10, true);
        assert!(!plan.expected_missed_proposers.iter().any(|pk| pk == &c));

        let mut gov_after = gov.clone();
        let policy = bc.policy.clone();
        Blockchain::apply_downtime_policy_plan(&mut gov_after, &curr, &policy, None, plan);
        let rep_c = gov_after
            .validator_reputation
            .get(&c)
            .cloned()
            .unwrap_or_default();
        assert_eq!(rep_c.downtime_missed_turns_total, 0);
        assert_eq!(rep_c.downtime_consecutive_missed_turns, 0);

        let views = bc.governance_validator_status_views_for_next_block();
        let view_c = views.iter().find(|v| v.pub_key == c).unwrap();
        assert!(!view_c.committee_member_current_epoch);
        assert!(!view_c.consensus_eligible_now);
        assert!(view_c
            .ineligibility_reasons
            .contains(&ConsensusIneligibilityReason::NotInCommittee));
    }

    #[test]
    fn status_view_serialization_is_consensus_explicit() {
        let _lock = test_process_lock();
        let a = test_validator_pk_hex(0x61);
        let b = test_validator_pk_hex(0x62);
        let committee = vec![(a.clone(), 7), (b.clone(), 29)];
        let validator_weights = vec![(a.clone(), 99), (b.clone(), 5)];
        let (mut bc, gov, _prev, _storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);
        bc.governance = Some(gov);

        let views = bc.governance_validator_status_views_for_next_block_onchain();
        let view_a = views.iter().find(|v| v.pub_key == a).unwrap();
        let js = serde_json::to_value(view_a).unwrap();

        assert_eq!(js["consensus_eligible_now"], js["onchain_eligible"]);
        assert_eq!(js["active"], js["onchain_eligible"]);
        assert!(js.get("local_validator").is_none());
        assert!(js.get("runtime_readiness_observed").is_none());
        assert!(js.get("runtime_sync_caught_up").is_none());
        assert!(js.get("runtime_bootstrap_complete").is_none());
        assert!(js.get("consensus_ready").is_none());
        assert_eq!(js["last_seen_height"], serde_json::json!(0));
        assert_eq!(js["last_produced_height"], serde_json::json!(0));
        assert_eq!(js["resolution_mode"], serde_json::json!("committee_smt"));
        assert_eq!(js["governance_weight"], serde_json::json!(99));
        assert_eq!(js["weight"], serde_json::json!(99));
        assert_eq!(js["consensus_stake_weight"], serde_json::json!(7));
        assert_ne!(js["governance_weight"], js["consensus_stake_weight"]);
    }

