    #[test]
    fn live_status_view_uses_remote_runtime_observations_for_peer_rows() {
        let (mut bc, a, b) = configured_status_view_blockchain();
        bc.set_proposal_gate_open(true);
        bc.set_p2p_ready_for_mining(true);
        bc.set_runtime_bootstrap_complete(true);
        bc.set_runtime_sync_caught_up(true);
        let vsh = bc.current_validator_set_hash_hex();
        assert!(bc.record_validator_runtime_observation(
            &b,
            false,
            false,
            false,
            "peer-b",
            &vsh,
            11,
            now_secs()
        ));

        let view = bc.governance_validator_status_views_for_next_block();
        let local = view.iter().find(|item| item.pub_key == a).unwrap();
        let remote = view.iter().find(|item| item.pub_key == b).unwrap();

        assert!(local.local_validator);
        assert_eq!(local.runtime_readiness_observed, true);
        assert_eq!(local.consensus_ready, Some(true));
        assert!(local.active);

        assert!(!remote.local_validator);
        assert_eq!(remote.runtime_readiness_observed, true);
        assert_eq!(remote.runtime_bootstrap_complete, Some(false));
        assert_eq!(remote.runtime_sync_caught_up, Some(false));
        assert_eq!(remote.consensus_ready, Some(false));
        assert!(!remote.active);
    }

