    #[test]
    fn runtime_observation_rejects_replay_and_allows_same_bucket_state_replacement() {
        let mut bc = Blockchain::new();
        let seed_b = [0x23u8; 32];
        let b = hex::encode(
            ed25519_dalek::SigningKey::from_bytes(&seed_b)
                .verifying_key()
                .to_bytes(),
        );
        let ts = now_secs();
        let vsh = bc.current_validator_set_hash_hex();
        assert!(
            bc.record_validator_runtime_observation(&b, true, true, true, "peer-b", &vsh, 7, ts)
        );
        assert!(
            !bc.record_validator_runtime_observation(&b, true, true, true, "peer-b", &vsh, 7, ts)
        );
        assert!(
            bc.record_validator_runtime_observation(&b, false, false, false, "peer-b", &vsh, 7, ts)
        );
        assert!(
            bc.record_validator_runtime_observation(&b, false, false, false, "peer-b", &vsh, 8, ts)
        );
        assert!(!bc.record_validator_runtime_observation(
            &b,
            false,
            false,
            false,
            "peer-b",
            &vsh,
            6,
            ts.saturating_sub(1)
        ));
    }

