    #[test]
    fn runtime_observation_replaces_same_bucket_when_runtime_state_changes() {
        let mut bc = Blockchain::new();
        bc.runtime_bootstrap_complete = true;
        bc.runtime_sync_caught_up = true;
        let validator = bc.governance.as_ref().unwrap().validator_set.entries[0]
            .pub_key
            .clone();
        let vsh = bc.current_validator_set_hash_hex();
        let ts = now_secs();
        assert!(bc.record_validator_runtime_observation(
            &validator, false, true, false, "peer-1", &vsh, 9, ts,
        ));
        assert!(bc.record_validator_runtime_observation(
            &validator, true, true, true, "peer-1", &vsh, 9, ts,
        ));
        let obs = bc
            .validator_runtime_observation_for_status(&validator, now_secs())
            .cloned()
            .expect("updated observation must remain visible");
        assert!(obs.runtime_sync_caught_up);
        assert!(obs.runtime_bootstrap_complete);
        assert!(obs.p2p_ready_for_mining);
    }

    #[test]
    fn runtime_observation_with_validator_set_hash_mismatch_is_not_counted() {
        let (mut bc, _, _) = configured_status_view_blockchain();
        bc.set_runtime_bootstrap_complete(true);
        bc.set_runtime_sync_caught_up(true);
        bc.set_proposal_gate_open(true);
        bc.set_p2p_ready_for_mining(true);
        let local_vsh = bc.current_validator_set_hash_hex();
        let bad_vsh = if local_vsh == "ff".repeat(32) {
            "ee".repeat(32)
        } else {
            "ff".repeat(32)
        };
        let now = now_secs();
        let _ = bc.record_validator_runtime_observation(
            &sample_pub(2),
            true,
            true,
            true,
            "12D3KooWSamplePeerMismatch111111111111111111111111",
            &bad_vsh,
            25,
            now,
        );
        let views = bc.governance_validator_status_views_for_next_block();
        let remote = views.iter().find(|v| v.pub_key == sample_pub(2)).unwrap();
        assert_eq!(remote.runtime_readiness_observed, true);
        assert_eq!(remote.runtime_validator_set_hash_match, Some(false));
        assert!(remote
            .ineligibility_reasons
            .contains(&ConsensusIneligibilityReason::RuntimeValidatorSetHashMismatch));
        assert_eq!(remote.consensus_ready, Some(false));

        let local_view = bc.local_consensus_runtime_view_for_next_block();
        assert_eq!(local_view.operational_runtime_validator_count, 2);
        assert_eq!(local_view.operational_runtime_quorum_k, 2);
        assert!(local_view.operational_runtime_quorum_ready);
        assert!(bc.runtime_operational_quorum_ready_for_next_block());
    }

