    #[test]
    fn restart_like_rebuild_preserves_consensus_diagnostics_and_downtime_plan() {
        let _lock = test_process_lock();
        let a = test_validator_pk_hex(0x71);
        let b = test_validator_pk_hex(0x72);
        let c = test_validator_pk_hex(0x73);
        let committee = vec![(a.clone(), 5), (b.clone(), 11), (c.clone(), 17)];
        let validator_weights = vec![(a.clone(), 2), (b.clone(), 3), (c.clone(), 4)];
        let (bc1, gov, prev, storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);

        let mut curr = prev.clone();
        curr.index = 2;
        curr.timestamp = 40;
        curr.miner_pub_key = b.clone();

        let plan1 = bc1.plan_downtime_policy_between_blocks(&gov, &prev, &curr, 0, 10, true);
        let status1 = bc1.governance_consensus_status_for_next_block().unwrap();
        let proposer1 = bc1
            .governance_expected_proposer_view(curr.index, 2, 0)
            .unwrap();

        let mut bc2 = Blockchain::from_blocks_with_storage(bc1.chain.clone(), storage.clone());
        bc2.governance = Some(gov.clone());

        let plan2 = bc2.plan_downtime_policy_between_blocks(&gov, &prev, &curr, 0, 10, true);
        let status2 = bc2.governance_consensus_status_for_next_block().unwrap();
        let proposer2 = bc2
            .governance_expected_proposer_view(curr.index, 2, 0)
            .unwrap();

        assert_eq!(
            plan1.expected_missed_proposers,
            plan2.expected_missed_proposers
        );
        assert_eq!(
            plan1.skip_missed_turn_attribution,
            plan2.skip_missed_turn_attribution
        );
        assert_eq!(status1.resolution_mode, status2.resolution_mode);
        assert_eq!(status1.committee_members, status2.committee_members);
        assert_eq!(status1.expected_proposer_now, status2.expected_proposer_now);
        assert_eq!(proposer1.proposer, proposer2.proposer);
        assert_eq!(proposer1.committee_members, proposer2.committee_members);
        assert_eq!(proposer1.resolution_mode, proposer2.resolution_mode);
    }

    #[test]
    fn refresh_local_miner_authorization_reenables_after_jail_expiry() {
        let _lock = test_process_lock();
        let miner_seed = [0xAB; 32];
        let miner_pk_hex = hex::encode(
            SigningKey::from_bytes(&miner_seed)
                .verifying_key()
                .to_bytes(),
        );
        let v2 = test_validator_pk_hex(0xBC);
        let v3 = test_validator_pk_hex(0xCD);

        let mut bc = Blockchain::new();
        bc.set_miner_sk_b64(STANDARD.encode(miner_seed));
        bc.governance = Some(test_governance(&[
            (miner_pk_hex.clone(), 10),
            (v2, 10),
            (v3, 10),
        ]));

        {
            let gov = bc.governance.as_mut().unwrap();
            let rep = gov
                .validator_reputation
                .entry(miner_pk_hex.clone())
                .or_default();
            rep.jailed_from_height = Some(1);
            // Semantica canonica: jail attivo per h in [from, until), quindi
            // per restare disabilitato anche al prossimo blocco deve valere until=3.
            rep.jailed_until_height = Some(3);
        }

        assert!(!bc.refresh_local_miner_authorization().unwrap());
        assert!(!bc.is_authorized_miner);

        let mut b1 = bc.chain[0].clone();
        b1.index = 1;
        b1.hash = "auth-test-h1".to_string();
        b1.previous_hash = bc.chain[0].hash.clone();
        b1.timestamp = bc.chain[0].timestamp.saturating_add(30);
        bc.chain.push(b1.clone());
        bc.on_block_applied(&b1, None);
        assert!(!bc.is_authorized_miner);

        let mut b2 = b1.clone();
        b2.index = 2;
        b2.hash = "auth-test-h2".to_string();
        b2.previous_hash = b1.hash.clone();
        b2.timestamp = b1.timestamp.saturating_add(30);
        bc.chain.push(b2.clone());
        bc.on_block_applied(&b2, None);
        assert!(
            bc.is_authorized_miner,
            "local miner should be re-enabled once jail expires"
        );
    }

