    #[test]
    fn revoked_validator_remains_excluded_even_when_jail_override_is_active() {
        let _lock = test_process_lock();
        let (_seed, miner_pk_hex, miner_sk_b64) = test_signing_key_material(0xA1);
        let v2 = test_validator_pk_hex(0xA2);
        let v3 = test_validator_pk_hex(0xA3);
        let v4 = test_validator_pk_hex(0xA4);

        let committee = vec![
            (miner_pk_hex.clone(), 11),
            (v2.clone(), 13),
            (v3.clone(), 17),
            (v4.clone(), 19),
        ];
        let validator_weights = vec![
            (miner_pk_hex.clone(), 1),
            (v2.clone(), 1),
            (v3.clone(), 1),
            (v4.clone(), 1),
        ];
        let (mut bc, mut gov, _prev, _storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);
        bc.set_miner_sk_b64(miner_sk_b64);

        for pk in [miner_pk_hex.clone(), v2.clone(), v3.clone(), v4.clone()] {
            let rep = gov.validator_reputation.entry(pk).or_default();
            rep.jailed_from_height = Some(1);
            rep.jailed_until_height = Some(500);
        }
        {
            let rep = gov
                .validator_reputation
                .entry(miner_pk_hex.clone())
                .or_default();
            rep.temporarily_revoked = true;
            rep.banned_until_height = None;
        }

        bc.governance = Some(gov.clone());

        let (pk, authorized, reason) = bc.local_miner_authorization_status().unwrap();
        assert_eq!(pk, miner_pk_hex);
        assert!(
            !authorized,
            "revoked validator must remain excluded even when jail override is active"
        );
        assert_eq!(reason, "revoked_at_height=2");

        let status = bc.governance_consensus_status_for_next_block().unwrap();
        assert!(
            !status.committee_members.iter().any(|m| m == &miner_pk_hex),
            "revoked validator must never re-enter the effective committee"
        );
        assert_eq!(status.committee_members.len(), 3);
    }

    #[test]
    fn restart_like_rebuild_preserves_override_active_and_revoked_exclusion() {
        let _lock = test_process_lock();
        let (_a_seed, a_pk, _a_sk_b64) = test_signing_key_material(0xB1);
        let (_b_seed, b_pk, b_sk_b64) = test_signing_key_material(0xB2);
        let (_c_seed, c_pk, _c_sk_b64) = test_signing_key_material(0xB3);
        let (_d_seed, d_pk, _d_sk_b64) = test_signing_key_material(0xB4);

        let committee = vec![
            (a_pk.clone(), 11),
            (b_pk.clone(), 13),
            (c_pk.clone(), 17),
            (d_pk.clone(), 19),
        ];
        let validator_weights = vec![
            (a_pk.clone(), 1),
            (b_pk.clone(), 1),
            (c_pk.clone(), 1),
            (d_pk.clone(), 1),
        ];
        let (mut bc1, mut gov, prev, storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);
        bc1.set_miner_sk_b64(b_sk_b64.clone());

        // Below quorum among non-revoked validators: only A is active, B/C jailed, D revoked.
        for pk in [b_pk.clone(), c_pk.clone()] {
            let rep = gov.validator_reputation.entry(pk).or_default();
            rep.jailed_from_height = Some(1);
            rep.jailed_until_height = Some(500);
        }
        {
            let rep = gov.validator_reputation.entry(d_pk.clone()).or_default();
            rep.temporarily_revoked = true;
            rep.banned_until_height = None;
            rep.jailed_from_height = Some(1);
            rep.jailed_until_height = Some(500);
        }
        bc1.governance = Some(gov.clone());

        let auth1 = bc1.local_miner_authorization_status().unwrap();
        assert_eq!(auth1.0, b_pk);
        assert!(auth1.1, "local miner must stay authorized via override");
        assert_eq!(auth1.2, "validator_set_liveness_override_ignore_jail");

        let status1 = bc1.governance_consensus_status_for_next_block().unwrap();
        assert!(status1.committee_members.iter().any(|m| m == &a_pk));
        assert!(status1.committee_members.iter().any(|m| m == &b_pk));
        assert!(status1.committee_members.iter().any(|m| m == &c_pk));
        assert!(
            !status1.committee_members.iter().any(|m| m == &d_pk),
            "revoked validator must remain excluded before restart"
        );
        assert_eq!(status1.committee_members.len(), 3);

        let proposer1 = bc1
            .governance_expected_proposer_view(prev.index + 1, 2, 0)
            .unwrap();
        assert!(
            proposer1.proposer == a_pk || proposer1.proposer == b_pk || proposer1.proposer == c_pk
        );
        assert_ne!(proposer1.proposer, d_pk);

        let mut bc2 = Blockchain::from_blocks_with_storage(bc1.chain.clone(), storage.clone());
        bc2.set_miner_sk_b64(b_sk_b64);
        bc2.governance = Some(gov);

        let auth2 = bc2.local_miner_authorization_status().unwrap();
        let status2 = bc2.governance_consensus_status_for_next_block().unwrap();
        let proposer2 = bc2
            .governance_expected_proposer_view(prev.index + 1, 2, 0)
            .unwrap();

        assert_eq!(auth1, auth2);
        assert_eq!(status1.resolution_mode, status2.resolution_mode);
        assert_eq!(status1.committee_members, status2.committee_members);
        assert_eq!(status1.expected_proposer_now, status2.expected_proposer_now);
        assert_eq!(proposer1.proposer, proposer2.proposer);
        assert_eq!(proposer1.committee_members, proposer2.committee_members);
        assert_eq!(proposer1.resolution_mode, proposer2.resolution_mode);
        assert!(
            !status2.committee_members.iter().any(|m| m == &d_pk),
            "revoked validator must remain excluded after restart-like rebuild"
        );
    }

    #[test]
    fn validator_compute_transition_exit_pending_remains_visible_to_downtime_policy() {
        let _lock = test_process_lock();
        let a = test_validator_pk_hex(0x91);
        let b = test_validator_pk_hex(0x92);
        let c = test_validator_pk_hex(0x93);
        let mut gov = test_governance(&[(a.clone(), 1), (b.clone(), 1), (c.clone(), 1)]);
        gov.downtime_policy.enabled = true;
        gov.downtime_policy.consecutive_missed_turns_threshold = 100;
        gov.validator_compute_transitions.insert(
            b.clone(),
            crate::governance::ValidatorComputeTransitionRecordV1 {
                validator_pubkey: b.clone(),
                operator_wallet_pubkey: b.clone(),
                status: crate::governance::ValidatorComputeTransitionStatusV1::ExitPending,
                requested_at_height: 10,
                decided_at_height: Some(10),
                finalized_at_height: None,
                proposal_id: Some("pending-validator-compute-transition-test".to_string()),
                deny_reasons: Vec::new(),
                reason: Some("pending exit must remain validator-accountable".to_string()),
            },
        );

        let curr = Block {
            index: 12,
            miner_pub_key: a,
            ..Block::default()
        };
        let policy = Blockchain::new().policy.clone();
        let plan = DowntimePlan {
            expected_missed_proposers: vec![b.clone()],
            producer_pk_hex: None,
            gap_slots: 1,
            unique_validator_count: 3,
            max_gap_slots: 10,
            skip_missed_turn_attribution: false,
            warning: None,
        };

        Blockchain::apply_downtime_policy_plan(&mut gov, &curr, &policy, None, plan);

        let rep_b = gov
            .validator_reputation
            .get(&b)
            .cloned()
            .unwrap_or_default();
        assert_eq!(rep_b.downtime_missed_turns_total, 1);
        assert_eq!(rep_b.downtime_consecutive_missed_turns, 1);
        assert!(
            gov.validator_set.entries.iter().any(|entry| entry.pub_key == b),
            "pending validator->compute transition must not remove the validator before finalization"
        );
    }

