    #[test]
    fn on_block_applied_persists_tip_governance_snapshot_when_storage_attached() {
        let _lock = test_process_lock();
        let a = test_validator_pk_hex(0xb1);
        let b = test_validator_pk_hex(0xb2);
        let committee = vec![(a.clone(), 3), (b.clone(), 5)];
        let validator_weights = vec![(a.clone(), 11), (b.clone(), 13)];
        let (mut bc, _gov, prev, storage) =
            test_chain_with_prev_block(&committee, &validator_weights, 10);

        let mut new_block = Block::default();
        new_block.index = prev.index + 1;
        new_block.previous_hash = prev.hash.clone();
        new_block.hash = "tip-h2".to_string();
        new_block.state_root = prev.state_root.clone();
        new_block.timestamp = prev.timestamp + 30;
        new_block.miner_pub_key = a.clone();

        if let Some(gov) = bc.governance.as_mut() {
            gov.validator_set.version = 77;
        }

        bc.chain.push(new_block.clone());
        bc.on_block_applied(&new_block, None);

        let (snap_h, snap_json) = storage.get_governance_snapshot().unwrap().unwrap();
        assert_eq!(snap_h, new_block.index);
        let persisted: GovernanceState = serde_json::from_str(&snap_json).unwrap();
        assert_eq!(persisted.validator_set.version, 77);
    }

    /// TEST KILLER: verifica che il fast-path (empty block) produca lo stesso state_root
    /// del percorso "slow" completo (fast-path disabilitato), a parità di input.
    ///
    /// Nota: se questo fallisce, hai un rischio hard-fork.
    #[test]
    fn test_empty_block_fastpath_matches_slow_path() {
        // DB temporaneo e due tree separati (evita contaminazioni tra i due calcoli).
        let smt_fast = StateSmt::ephemeral();
        let smt_slow = StateSmt::ephemeral();

        // Coinbase meta V2 coerente con un blocco vuoto.
        let reward: u64 = 50_000_000;
        let meta = CoinbaseEconMetaV2 {
            v: 2,
            base_fee_per_tx: 100,
            user_txs: 0,
            total_fees: 0,
            burned: 0,
            to_treasury_from_fees: 0,
            slashed_to_treasury: 0,
            reward_total: reward,
            reward_to_treasury: 0,
            reward_to_miner_base: reward,
        };
        let memo_str = serde_json::to_string(&meta).unwrap();

        // TX coinbase (firma/hash non rilevanti qui: è coinbase).
        let coinbase_tx = Transaction {
            sender: "COINBASE".to_string(),
            receiver: "MINER_TEST_PUBKEY_B64".to_string(),
            amount: reward,
            max_fee_per_tx: 0,
            nonce: 0,
            signature: "".to_string(),
            hash: "tx_hash_dummy".to_string(),
            is_coinbase: true,
            memo: Some(memo_str),
        };
        let txs = vec![coinbase_tx];

        // prev_root vuoto -> empty_root
        let prev_root_hex = "";

        // A) produzione: fast-path abilitato (empty block => prende la scorciatoia)
        let root_fast = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt_fast,
            prev_root_hex,
            0,
            &txs,
            true,
            None,
            None,
            None,
        )
        .expect("fast-path failed");

        // B) slow-path forzato: stessa logica ma senza early-return al fast-path
        let root_slow = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt_slow,
            prev_root_hex,
            0,
            &txs,
            false,
            None,
            None,
            None,
        )
        .expect("slow-path failed");

        assert_eq!(
            root_fast, root_slow,
            "CRITICAL: empty-block fast-path diverge dal slow-path"
        );
    }

    /// STEP 49 – Verifica che un double proposal alla stessa height
    /// generi slashing (debito + jail) per il validator.
    #[test]
    fn slashing_double_proposal_creates_debt_and_jail() {
        let mut chain = Blockchain::new();

        // Miner fittizio
        let miner = "MINER_X";

        // Primo blocco "visto" alla height 1
        let mut b1 = Block::new(1, 0, "prev_hash_0".to_string(), Vec::new());
        b1.miner_pub_key = miner.to_string();
        b1.hash = "HASH_1".to_string();

        // Secondo blocco alla stessa height e stesso miner, ma hash diverso
        let mut b2 = b1.clone();
        b2.hash = "HASH_2".to_string();

        // All'inizio nessuno slashing
        assert!(chain.slashing.validators.is_empty());

        // Applichiamo il primo blocco: non deve ancora slashtare
        chain.on_block_applied(&b1, None);
        assert!(chain.slashing.validators.is_empty());

        // Applichiamo il secondo blocco: ora deve scattare il double-sign slashing
        chain.on_block_applied(&b2, None);

        let info = chain
            .slashing
            .validators
            .get(miner)
            .expect("Validator slashing info should exist");

        assert!(
            info.pending_slash_debt > 0,
            "Nessun debito di slashing registrato"
        );
        assert!(
            info.jailed_until_height.is_some(),
            "Validator non risulta in jail dopo double-sign"
        );
    }
    /// STEP 52 – Verifica base del RewardSchedule (Halving).
    #[test]
    fn reward_schedule_halving_basic() {
        let rs = RewardSchedule {
            model: RewardModel::Halving,
            start_height: 0,
            initial_per_block: 100,
            floor_per_block: 0,
            halving_interval_blocks: 10,
            ..RewardSchedule::default()
        };

        assert_eq!(rs.reward_total_at(0), 100);
        assert_eq!(rs.reward_total_at(9), 100);
        assert_eq!(rs.reward_total_at(10), 50);
        assert_eq!(rs.reward_total_at(20), 25);
    }

    /// STEP 52 – Verifica base del RewardSchedule (DecayEpoch).
    #[test]
    fn reward_schedule_decay_epoch_basic() {
        let rs = RewardSchedule {
            model: RewardModel::DecayEpoch,
            start_height: 0,
            initial_per_block: 100,
            floor_per_block: 0,
            epoch_blocks: 10,
            decay_num: 9,
            decay_den: 10,
            ..RewardSchedule::default()
        };

        assert_eq!(rs.reward_total_at(0), 100);
        assert_eq!(rs.reward_total_at(9), 100);

        // dopo 1 epoch: 100 * 9/10 = 90
        assert_eq!(rs.reward_total_at(10), 90);

        // dopo 2 epoch: 90 * 9/10 = 81
        assert_eq!(rs.reward_total_at(20), 81);
    }

