    #[test]
    fn economy_apply_report_fallback_legacy_without_memo_is_consistent() {
        let mut chain = Blockchain::new();
        chain.policy.base_fee_per_tx = 10;
        chain.policy.burn_bps = 500;
        chain.policy.treasury_pct_base_bps = 3000;
        chain.policy.reward_schedule.initial_per_block = 100;
        chain.policy.reward_schedule.floor_per_block = 100;
        chain.policy.reward_schedule.epoch_blocks = 1_000_000;
        chain.policy.reward_schedule.decay_num = 1;
        chain.policy.reward_schedule.decay_den = 1;
        chain.policy.reward_schedule.reward_to_treasury_bps = 1000;

        let block = Block {
            index: 1,
            timestamp: 1001,
            transactions: vec![
                Transaction {
                    sender: "alice".to_string(),
                    receiver: "bob".to_string(),
                    amount: 1,
                    max_fee_per_tx: 10,
                    nonce: 1,
                    signature: String::new(),
                    hash: "u1".to_string(),
                    is_coinbase: false,
                    memo: None,
                },
                Transaction {
                    sender: "alice".to_string(),
                    receiver: "carol".to_string(),
                    amount: 1,
                    max_fee_per_tx: 10,
                    nonce: 2,
                    signature: String::new(),
                    hash: "u2".to_string(),
                    is_coinbase: false,
                    memo: None,
                },
                Transaction {
                    sender: "COINBASE".to_string(),
                    receiver: "miner".to_string(),
                    amount: 108,
                    max_fee_per_tx: 0,
                    nonce: 0,
                    signature: String::new(),
                    hash: "cb-legacy".to_string(),
                    is_coinbase: true,
                    memo: None,
                },
            ],
            previous_hash: "prev".to_string(),
            hash: "h1".to_string(),
            tx_root: String::new(),
            state_root: String::new(),
            miner_pub_key: "m".to_string(),
            signature: None,
            governance_txs: vec![],
            cognitive_txs: vec![],
            pos_epoch: 0,
            pos_slot: 0,
            pos_round: 0,
            pos_proof: None,
            finality_qc: None,
            evidence: vec![],
            nft_events: vec![],
        };
        let report = chain.build_economy_apply_report(
            &block,
            EconomyApplySource::RemoteApplied,
            10,
            "steady".to_string(),
            0,
            0,
            500,
            3000,
            &chain.policy.reward_schedule,
            0,
        );
        assert_eq!(report.total_fees, 20);
        assert_eq!(report.burn_bps_before, 500);
        assert_eq!(report.treasury_pct_base_bps_before, 3000);
        assert_eq!(report.burned, 1);
        assert_eq!(report.to_treasury_from_fees, 5);
        let (expected_reward_total, expected_reward_to_miner_base, expected_reward_to_treasury) =
            Blockchain::effective_reward_split_for_policy(&chain.policy, block.index, false);
        assert_eq!(report.reward_total, expected_reward_total);
        assert_eq!(report.reward_to_treasury, expected_reward_to_treasury);
        assert_eq!(report.reward_to_miner_base, expected_reward_to_miner_base);
        let after_burn = report.total_fees.saturating_sub(report.burned);
        let fees_to_miner_final = after_burn.saturating_sub(report.to_treasury_from_fees);
        let expected_slashed = expected_reward_to_miner_base
            .saturating_add(fees_to_miner_final)
            .saturating_sub(report.coinbase_amount);
        assert_eq!(report.slashed_to_treasury, expected_slashed);
    }

