    #[test]
    fn coinbase_empty_block_reward_is_reduced_and_parsable() {
        let mut chain = Blockchain::new();

        // Config di test: reward piena 100, blocco vuoto = 10% (bps=1000)
        chain.policy.reward_schedule.start_height = 0;
        chain.policy.reward_schedule.initial_per_block = 100;
        chain.policy.reward_schedule.floor_per_block = 0;
        chain.policy.reward_schedule.epoch_blocks = 1_000_000;
        chain.policy.reward_schedule.decay_num = 1;
        chain.policy.reward_schedule.decay_den = 1;
        chain.policy.reward_schedule.reward_to_treasury_bps = 0;
        chain.policy.reward_schedule.empty_block_reward_bps = 1000;

        let miner_pk_b64 = "MINER_PK_B64";
        let miner_pub_hex = "MINER_PUB_HEX";
        let next_height = 1;

        let tx = chain.create_coinbase_empty_block_tx(miner_pk_b64, miner_pub_hex, next_height);

        assert!(tx.is_coinbase);
        assert_eq!(tx.max_fee_per_tx, 0);
        assert_eq!(tx.nonce, 0);

        // Reward attesa: 100 * 10% = 10
        assert_eq!(tx.amount, 10);

        let memo = tx.memo.expect("memo should exist");
        let meta = serde_json::from_str::<CoinbaseEconMetaV3>(&memo)
            .expect("memo should parse as CoinbaseEconMetaV3");

        assert_eq!(meta.v, 3);
        assert_eq!(meta.user_txs, 0);
        assert_eq!(meta.total_fees, 0);
        assert_eq!(meta.burned, 0);
        assert_eq!(meta.to_treasury_from_fees, 0);
        assert_eq!(meta.reward_total, 10);
        assert_eq!(meta.reward_to_miner_base, 10);
        assert_eq!(meta.reward_to_treasury, 0);
    }

    #[test]
    fn empty_block_ignores_fee_fields_in_legacy_non_strict_meta() {
        let mut chain = Blockchain::new();
        chain.policy.base_fee_per_tx = 100;
        chain.policy.burn_bps = 500;
        chain.policy.treasury_pct_base_bps = 3000;
        chain.policy.treasury.reserve_balance = 10;

        let meta = CoinbaseEconMetaV3 {
            v: 3,
            base_fee_per_tx: 100,
            user_txs: 0,
            total_fees: 999,
            burned: 99,
            to_treasury_from_fees: 77,
            slashed_to_treasury: 7,
            reward_total: 3,
            reward_to_treasury: 2,
            reward_to_miner_base: 1,
            reward_base_schedule: 3,
            reward_effective: 3,
            reward_multiplier_bps: 10_000,
            validator_fee_budget: 999,
            emission_phase: chain.policy.emission_state.phase,
            emission_controller_active: false,
        };

        let mut coinbase = Transaction {
            sender: "COINBASE".to_string(),
            receiver: "miner".to_string(),
            amount: 1,
            max_fee_per_tx: 0,
            nonce: 0,
            signature: String::new(),
            hash: String::new(),
            is_coinbase: true,
            memo: Some(serde_json::to_string(&meta).unwrap()),
        };
        coinbase.hash = coinbase.calculate_hash();

        let block = Block {
            index: 1,
            timestamp: 1000,
            transactions: vec![coinbase],
            previous_hash: "prev".to_string(),
            hash: "h1".to_string(),
            tx_root: String::new(),
            state_root: String::new(),
            miner_pub_key: "miner".to_string(),
            signature: None,
            governance_txs: vec![],
            cognitive_txs: vec![],
            pos_epoch: 0,
            pos_slot: 0,
            pos_round: 0,
            pos_proof: None,
            finality_qc: None,
            evidence: vec![],
            nft_events: vec![],
        };

        let report = chain.build_economy_apply_report(
            &block,
            EconomyApplySource::RemoteApplied,
            chain.policy.base_fee_per_tx,
            "idle".to_string(),
            chain.policy.treasury.reserve_balance,
            chain.total_supply,
            chain.policy.burn_bps,
            chain.policy.treasury_pct_base_bps as u64,
            &chain.policy.reward_schedule,
            0,
        );

        assert_eq!(report.user_txs, 0);
        assert_eq!(report.total_fees, 0);
        assert_eq!(report.burned, 0);
        assert_eq!(report.to_treasury_from_fees, 0);
        assert_eq!(report.slashed_to_treasury, 7);
        assert_eq!(report.reward_to_treasury, 2);

        chain.treasury_apply_block_fees(&block);
        assert_eq!(chain.policy.treasury.reserve_balance, 10 + 7 + 2);
    }

    #[test]
    fn empty_block_state_root_ignores_fee_fields_in_legacy_non_strict_meta() {
        fn coinbase_with_meta(meta: CoinbaseEconMetaV3) -> Transaction {
            let mut tx = Transaction {
                sender: "COINBASE".to_string(),
                receiver: "miner".to_string(),
                amount: 1,
                max_fee_per_tx: 0,
                nonce: 0,
                signature: String::new(),
                hash: String::new(),
                is_coinbase: true,
                memo: Some(serde_json::to_string(&meta).unwrap()),
            };
            tx.hash = tx.calculate_hash();
            tx
        }

        let clean = CoinbaseEconMetaV3 {
            v: 3,
            base_fee_per_tx: 100,
            user_txs: 0,
            total_fees: 0,
            burned: 0,
            to_treasury_from_fees: 0,
            slashed_to_treasury: 0,
            reward_total: 0,
            reward_to_treasury: 0,
            reward_to_miner_base: 0,
            reward_base_schedule: 0,
            reward_effective: 0,
            reward_multiplier_bps: 10_000,
            validator_fee_budget: 0,
            emission_phase: EmissionSunsetPhase::Launch,
            emission_controller_active: false,
        };
        let mut forged = clean.clone();
        forged.total_fees = 10_000;
        forged.burned = 100;
        forged.to_treasury_from_fees = 777;
        forged.validator_fee_budget = 9_999;

        let root_clean =
            Blockchain::compute_state_root_for_txs_ephemeral("", 1, &[coinbase_with_meta(clean)])
                .unwrap();
        let root_forged =
            Blockchain::compute_state_root_for_txs_ephemeral("", 1, &[coinbase_with_meta(forged)])
                .unwrap();

        assert_eq!(root_clean, root_forged);
    }

    #[test]
    fn ft_transfer_to_self_keeps_balance_constant() {
        use crate::governance::{Council, GovernanceParams, GovernanceState, ValidatorSet};
        use serde_json::json;

        fn ft_gov_enabled() -> GovernanceState {
            GovernanceState::new(
                Council {
                    members: vec![],
                    threshold: 0,
                },
                Council {
                    members: vec![],
                    threshold: 0,
                },
                Council {
                    members: vec![],
                    threshold: 0,
                },
                GovernanceParams {
                    min_timelock_blocks: 0,
                    max_proposal_lifetime_blocks: 100_000,
                    max_emergency_duration_blocks: 0,
                    wallet_reputation_promotion_quorum: 2,
                    e2_worker_admission_activation_height: 0,
                    validator_compute_transition_min_active_validators: 2,
                    validator_compute_transition_min_finality_quorum: 2,
                    validator_compute_transition_validator_quality_floor: 600,
                    validator_compute_transition_exit_cooldown_blocks: 10,
                    validator_compute_transition_max_finality_lag_blocks: 2,
                    validator_compute_transition_max_recent_missed_slots: 3,
                    ft_activation_height: 0,
                    ft_max_tokens_per_owner: 100,
                    ft_create_cooldown_blocks: 0,
                    ft_create_fee_native: 0,
                    nft_activation_height: 0,
                    nft_max_collections_per_owner: 100,
                    nft_create_cooldown_blocks: 0,
                    nft_create_fee_native: 0,
                    nft_enabled: true,
                    nft_public_create_enabled: true,
                    nft_public_mint_enabled: true,
                    nft_public_transfer_enabled: true,
                    nft_public_approval_enabled: true,
                    nft_public_burn_enabled: true,
                    nft_public_revoke_enabled: true,
                    nft_public_metadata_update_enabled: true,
                    nft_public_freeze_enabled: true,
                    nft_public_policy_update_enabled: true,
                    nft_public_issuer_update_enabled: true,
                    nft_public_pause_enabled: true,
                    nft_metadata_hash_required: true,
                    nft_max_memo_bytes: crate::nft::NFTV1_MEMO_MAX_BYTES as u32,
                    nft_max_uri_bytes: crate::nft::NFTV1_URI_MAX_BYTES as u32,
                    nft_max_name_bytes: crate::nft::NFTV1_NAME_MAX_BYTES as u32,
                    nft_max_symbol_bytes: crate::nft::NFTV1_SYMBOL_MAX_BYTES as u32,
                    nft_max_tokens_per_collection: 0,
                    nft_max_tokens_per_owner: 0,
                    nft_mint_fee_native: 0,
                    nft_transfer_fee_native: 0,
                    nft_approval_fee_native: 0,
                    nft_burn_fee_native: 0,
                    nft_revoke_fee_native: 0,
                    nft_metadata_update_fee_native: 0,
                    nft_freeze_fee_native: 0,
                    nft_policy_update_fee_native: 0,
                    nft_issuer_update_fee_native: 0,
                    nft_pause_fee_native: 0,
                },
                ValidatorSet::default(),
            )
        }

        let smt = StateSmt::ephemeral();
        let gov = ft_gov_enabled();

        let create_memo = serde_json::to_string(&json!({
            "v": 1,
            "ctx": crate::ft::CTX_FT_CREATE,
            "op": "create_token",
            "symbol": "GEMS",
            "decimals": 0,
            "max_supply": "100",
            "initial_supply": "100",
            "mintable": false,
            "burnable": true,
            "freeze_enabled": false
        }))
        .unwrap();

        let tx_create = Transaction::new(
            "OWNER_PK_B64".to_string(),
            crate::ft::FT_RECEIVER.to_string(),
            0,
            1,
            0,
            String::new(),
            false,
            Some(create_memo),
        );

        let root1 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            "",
            1,
            &[tx_create],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("ft create must succeed");
        let r1 = bytes32_from_hex(&root1).unwrap();

        let bal1 = smt
            .get_account(r1, crate::ft::k_ft_balance(1, "OWNER_PK_B64"))
            .unwrap()
            .expect("owner ft balance must exist");
        assert_eq!(crate::ft::decode_balance_amount_v1(&bal1).unwrap(), 100);

        let transfer_self_memo = serde_json::to_string(&json!({
            "v": 1,
            "ctx": crate::ft::CTX_FT_TRANSFER,
            "op": "transfer",
            "token_id": 1,
            "to": "OWNER_PK_B64",
            "amount": "25"
        }))
        .unwrap();

        let tx_self = Transaction::new(
            "OWNER_PK_B64".to_string(),
            crate::ft::FT_RECEIVER.to_string(),
            0,
            2,
            0,
            String::new(),
            false,
            Some(transfer_self_memo),
        );

        let root2 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root1,
            2,
            &[tx_self],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("ft self transfer must succeed");
        let r2 = bytes32_from_hex(&root2).unwrap();

        let bal2 = smt
            .get_account(r2, crate::ft::k_ft_balance(1, "OWNER_PK_B64"))
            .unwrap()
            .expect("owner ft balance must still exist");
        assert_eq!(crate::ft::decode_balance_amount_v1(&bal2).unwrap(), 100);
    }

