    // ---------------------------------------------------------------------
    // Phase 1 — Staking + Validator Registry on-chain (unit tests)
    // ---------------------------------------------------------------------
    #[test]
    fn phase1_staking_register_bond_unbond_withdraw_rotate_is_deterministic() {
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
        use ed25519_dalek::{Signer, SigningKey};
        use serde_json::json;

        // Temp DB + SMT
        let smt = StateSmt::ephemeral();

        // Deterministic keys (no RNG in tests)
        let owner_sk = SigningKey::from_bytes(&[1u8; 32]);
        let owner_pk_b64 = B64.encode(owner_sk.verifying_key().to_bytes());

        let val_old_sk = SigningKey::from_bytes(&[2u8; 32]);
        let val_old_pk_b64 = B64.encode(val_old_sk.verifying_key().to_bytes());

        let val_new_sk = SigningKey::from_bytes(&[3u8; 32]);
        let val_new_pk_b64 = B64.encode(val_new_sk.verifying_key().to_bytes());

        // PoS params for the test chain
        let pos_params = staking::PosParamsV1 {
            min_stake: 500,
            unbonding_epochs: 2,
            epoch_len: 1,
            committee_size: 64,
        };

        let genesis_memo = serde_json::to_string(&GenesisPosParamsMemoV1 {
            v: 1,
            kind: "genesis_pos_params_v1".to_string(),
            pos_params: pos_params.clone(),
        })
        .unwrap();

        // Block 0: allocate 1_000 to owner + bootstrap PoS params via coinbase memo
        let tx0 = Transaction::new(
            "COINBASE".to_string(),
            owner_pk_b64.clone(),
            1_000,
            0,
            0,
            "".to_string(),
            true,
            Some(genesis_memo),
        );
        let txs0 = vec![tx0];

        let root0 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, "", 0, &txs0, true, None, None, None,
        )
        .expect("genesis state_root");
        let r0 = bytes32_from_hex(&root0).unwrap();

        // Params present and equal to genesis
        let st_params = smt
            .get_account(r0, staking::k_stake_params())
            .unwrap()
            .expect("stake params must exist");
        let got_params = staking::decode_params_state(&st_params).unwrap();
        assert_eq!(got_params, pos_params);

        // Total bonded = 0
        let st_tb = smt
            .get_account(r0, staking::k_total_bonded())
            .unwrap()
            .expect("total_bonded must exist");
        assert_eq!(staking::decode_total_bonded_state(&st_tb).unwrap().total, 0);

        // Helper to build stake-call memo
        let memo = |v: serde_json::Value| -> String { serde_json::to_string(&v).unwrap() };

        // Block 1: register validator
        let tx1 = Transaction::new(
            owner_pk_b64.clone(),
            staking::STAKE_RECEIVER.to_string(),
            0,
            1,
            0,
            "".to_string(),
            false,
            Some(memo(json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "register_validator",
                "consensus_pubkey_b64": val_old_pk_b64.clone(),
                "net_addr": "/ip4/127.0.0.1/tcp/1234".to_string(),
                "commission_bps": 500u64,
                "metadata": "validator-A".to_string()
            }))),
        );
        let txs1 = vec![tx1];
        let root1 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, &root0, 1, &txs1, false, None, None, None,
        )
        .expect("register root");
        let r1 = bytes32_from_hex(&root1).unwrap();

        // Owner link exists → points to validator pk hex
        let st_link = smt
            .get_account(r1, staking::k_owner_link(&owner_pk_b64))
            .unwrap()
            .expect("owner link must exist");
        let link = staking::decode_owner_link_state(&st_link).unwrap();
        let old_hex = crate::keyfmt::pk_hex_from_any(&val_old_pk_b64).unwrap();
        assert_eq!(link.owner, owner_pk_b64);
        assert_eq!(link.validator_pk_hex, old_hex);

        // Validator record exists and is inactive (bonded=0 < min_stake)
        let st_v = smt
            .get_account(r1, staking::k_validator(&old_hex))
            .unwrap()
            .expect("validator record must exist");
        let mut vr = staking::decode_validator_state(&st_v).unwrap();
        assert_eq!(vr.bonded, 0);
        assert_eq!(vr.status, staking::ValidatorStatusV1::Inactive);

        // Block 2: bond 600
        let tx2 = Transaction::new(
            owner_pk_b64.clone(),
            staking::STAKE_RECEIVER.to_string(),
            600,
            2,
            0,
            "".to_string(),
            false,
            Some(memo(json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "bond",
                "validator_pk_b64": val_old_pk_b64.clone()
            }))),
        );
        let root2 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root1,
            2,
            &[tx2],
            false,
            None,
            None,
            None,
        )
        .expect("bond root");
        let r2 = bytes32_from_hex(&root2).unwrap();

        let owner_acc2 = smt
            .get_account(r2, addr_key(&owner_pk_b64))
            .unwrap()
            .expect("owner account must exist");
        assert_eq!(owner_acc2.balance, 400);

        let st_v2 = smt
            .get_account(r2, staking::k_validator(&old_hex))
            .unwrap()
            .expect("validator record must exist");
        vr = staking::decode_validator_state(&st_v2).unwrap();
        assert_eq!(vr.bonded, 600);
        assert_eq!(vr.status, staking::ValidatorStatusV1::Active);

        let st_tb2 = smt
            .get_account(r2, staking::k_total_bonded())
            .unwrap()
            .expect("total_bonded must exist");
        assert_eq!(
            staking::decode_total_bonded_state(&st_tb2).unwrap().total,
            600
        );

        // Block 3: unbond 200 (unlock_epoch = current_epoch(3) + 2 = 5)
        let tx3 = Transaction::new(
            owner_pk_b64.clone(),
            staking::STAKE_RECEIVER.to_string(),
            200,
            3,
            0,
            "".to_string(),
            false,
            Some(memo(json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "unbond",
                "validator_pk_b64": val_old_pk_b64.clone()
            }))),
        );
        let root3 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root2,
            3,
            &[tx3],
            false,
            None,
            None,
            None,
        )
        .expect("unbond root");
        let r3 = bytes32_from_hex(&root3).unwrap();

        let st_v3 = smt
            .get_account(r3, staking::k_validator(&old_hex))
            .unwrap()
            .expect("validator record must exist");
        vr = staking::decode_validator_state(&st_v3).unwrap();
        assert_eq!(vr.bonded, 400);
        assert_eq!(vr.status, staking::ValidatorStatusV1::Inactive); // below min_stake

        let st_tb3 = smt
            .get_account(r3, staking::k_total_bonded())
            .unwrap()
            .unwrap();
        assert_eq!(
            staking::decode_total_bonded_state(&st_tb3).unwrap().total,
            400
        );

        let st_ul3 = smt
            .get_account(r3, staking::k_unbond(&old_hex))
            .unwrap()
            .expect("unbond list must exist");
        let ul3 = staking::decode_unbond_list_state(&st_ul3).unwrap();
        assert_eq!(ul3.len(), 1);
        assert_eq!(ul3[0].amount, 200);
        assert_eq!(ul3[0].unlock_epoch, 5);

        // Block 4: rotate key (moves validator record + unbond list)
        let msg =
            staking::rotate_message_v1(&owner_pk_b64, &val_old_pk_b64, &val_new_pk_b64).unwrap();
        let sig = val_old_sk.sign(&msg);
        let proof_b64 = B64.encode(sig.to_bytes());

        let tx4 = Transaction::new(
            owner_pk_b64.clone(),
            staking::STAKE_RECEIVER.to_string(),
            0,
            4,
            0,
            "".to_string(),
            false,
            Some(memo(json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "rotate_key",
                "new_pubkey_b64": val_new_pk_b64.clone(),
                "proof_signed_by_old": proof_b64
            }))),
        );
        let root4 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root3,
            4,
            &[tx4],
            false,
            None,
            None,
            None,
        )
        .expect("rotate root");
        let r4 = bytes32_from_hex(&root4).unwrap();

        let new_hex = crate::keyfmt::pk_hex_from_any(&val_new_pk_b64).unwrap();

        // Old record removed
        let old_v = smt.get_account(r4, staking::k_validator(&old_hex)).unwrap();
        assert!(old_v.is_none());

        // New record present and unbond list moved
        let new_v = smt
            .get_account(r4, staking::k_validator(&new_hex))
            .unwrap()
            .expect("new validator record must exist");
        vr = staking::decode_validator_state(&new_v).unwrap();
        assert_eq!(vr.bonded, 400);

        let old_ul = smt.get_account(r4, staking::k_unbond(&old_hex)).unwrap();
        assert!(old_ul.is_none());

        let new_ul = smt
            .get_account(r4, staking::k_unbond(&new_hex))
            .unwrap()
            .expect("unbond list must have moved");
        let ul4 = staking::decode_unbond_list_state(&new_ul).unwrap();
        assert_eq!(ul4.len(), 1);
        assert_eq!(ul4[0].unlock_epoch, 5);

        // Owner link updated
        let st_link4 = smt
            .get_account(r4, staking::k_owner_link(&owner_pk_b64))
            .unwrap()
            .unwrap();
        let link4 = staking::decode_owner_link_state(&st_link4).unwrap();
        assert_eq!(link4.validator_pk_hex, new_hex);

        // Block 5: withdraw (epoch=5) unlocks the 200
        let tx5 = Transaction::new(
            owner_pk_b64.clone(),
            staking::STAKE_RECEIVER.to_string(),
            0,
            5,
            0,
            "".to_string(),
            false,
            Some(memo(json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "withdraw",
                "validator_pk_b64": val_new_pk_b64.clone()
            }))),
        );
        let root5 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root4,
            5,
            &[tx5],
            false,
            None,
            None,
            None,
        )
        .expect("withdraw root");
        let r5 = bytes32_from_hex(&root5).unwrap();

        let owner_acc5 = smt
            .get_account(r5, addr_key(&owner_pk_b64))
            .unwrap()
            .unwrap();
        assert_eq!(owner_acc5.balance, 600);

        let ul5 = smt.get_account(r5, staking::k_unbond(&new_hex)).unwrap();
        assert!(ul5.is_none());

        // Block 6: bond 200 (back to active)
        let tx6 = Transaction::new(
            owner_pk_b64.clone(),
            staking::STAKE_RECEIVER.to_string(),
            200,
            6,
            0,
            "".to_string(),
            false,
            Some(memo(json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "bond",
                "validator_pk_b64": val_new_pk_b64.clone()
            }))),
        );
        let root6 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root5,
            6,
            &[tx6],
            false,
            None,
            None,
            None,
        )
        .expect("bond2 root");

        // Determinism / replay gate: re-run the same blocks from scratch and compare final root.
        let smt2 = StateSmt::ephemeral();

        let r0b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, "", 0, &txs0, true, None, None, None,
        )
        .unwrap();
        let r1b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, &r0b, 1, &txs1, false, None, None, None,
        )
        .unwrap();
        let r2b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2,
            &r1b,
            2,
            &[Transaction::new(
                owner_pk_b64.clone(),
                staking::STAKE_RECEIVER.to_string(),
                600,
                2,
                0,
                "".to_string(),
                false,
                Some(memo(json!({
                    "v": 1,
                    "kind": "stake_call_v1",
                    "op": "bond",
                    "validator_pk_b64": val_old_pk_b64.clone()
                }))),
            )],
            false,
            None,
            None,
            None,
        )
        .unwrap();
        let r3b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2,
            &r2b,
            3,
            &[Transaction::new(
                owner_pk_b64.clone(),
                staking::STAKE_RECEIVER.to_string(),
                200,
                3,
                0,
                "".to_string(),
                false,
                Some(memo(json!({
                    "v": 1,
                    "kind": "stake_call_v1",
                    "op": "unbond",
                    "validator_pk_b64": val_old_pk_b64.clone()
                }))),
            )],
            false,
            None,
            None,
            None,
        )
        .unwrap();

        let msg2 =
            staking::rotate_message_v1(&owner_pk_b64, &val_old_pk_b64, &val_new_pk_b64).unwrap();
        let proof2 = B64.encode(val_old_sk.sign(&msg2).to_bytes());
        let r4b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2,
            &r3b,
            4,
            &[Transaction::new(
                owner_pk_b64.clone(),
                staking::STAKE_RECEIVER.to_string(),
                0,
                4,
                0,
                "".to_string(),
                false,
                Some(memo(json!({
                    "v": 1,
                    "kind": "stake_call_v1",
                    "op": "rotate_key",
                    "new_pubkey_b64": val_new_pk_b64.clone(),
                    "proof_signed_by_old": proof2
                }))),
            )],
            false,
            None,
            None,
            None,
        )
        .unwrap();

        let r5b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2,
            &r4b,
            5,
            &[Transaction::new(
                owner_pk_b64.clone(),
                staking::STAKE_RECEIVER.to_string(),
                0,
                5,
                0,
                "".to_string(),
                false,
                Some(memo(json!({
                    "v": 1,
                    "kind": "stake_call_v1",
                    "op": "withdraw",
                    "validator_pk_b64": val_new_pk_b64.clone()
                }))),
            )],
            false,
            None,
            None,
            None,
        )
        .unwrap();

        let r6b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2,
            &r5b,
            6,
            &[Transaction::new(
                owner_pk_b64.clone(),
                staking::STAKE_RECEIVER.to_string(),
                200,
                6,
                0,
                "".to_string(),
                false,
                Some(memo(json!({
                    "v": 1,
                    "kind": "stake_call_v1",
                    "op": "bond",
                    "validator_pk_b64": val_new_pk_b64.clone()
                }))),
            )],
            false,
            None,
            None,
            None,
        )
        .unwrap();

        assert_eq!(root6, r6b, "replay must produce identical final state_root");
    }

    #[test]
    #[ignore]
    fn phase1_staking_1000_validators_register_and_bond_replayable() {
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
        use ed25519_dalek::SigningKey;
        use serde_json::json;

        const N: usize = 1000;
        const INIT_BAL: u64 = 25;
        const MIN_STAKE: u64 = 10;

        let pos_params = staking::PosParamsV1 {
            min_stake: MIN_STAKE,
            unbonding_epochs: 2,
            epoch_len: 1,
            committee_size: 64,
        };

        let genesis_memo = serde_json::to_string(&GenesisPosParamsMemoV1 {
            v: 1,
            kind: "genesis_pos_params_v1".to_string(),
            pos_params: pos_params.clone(),
        })
        .unwrap();

        // Deterministic seed → ed25519 key (no RNG)
        let mk_seed = |i: u32, tag: u8| -> [u8; 32] {
            let mut s = [0u8; 32];
            s[0..4].copy_from_slice(&i.to_le_bytes());
            s[4] = tag;
            s
        };

        // Block 0: allocations + PoS params meta coinbase
        let mut txs0: Vec<Transaction> = Vec::with_capacity(N + 1);
        for i in 0..(N as u32) {
            let owner_sk = SigningKey::from_bytes(&mk_seed(i, 1));
            let owner_b64 = B64.encode(owner_sk.verifying_key().to_bytes());

            let mut t = Transaction {
                sender: "COINBASE".to_string(),
                receiver: owner_b64,
                amount: INIT_BAL,
                max_fee_per_tx: 0,
                nonce: 0,
                signature: "".to_string(),
                hash: String::new(),
                is_coinbase: true,
                memo: Some("genesis_alloc".to_string()),
            };
            t.hash = t.calculate_hash();
            txs0.push(t);
        }

        let mut meta_tx = Transaction {
            sender: "COINBASE".to_string(),
            receiver: "GENESIS".to_string(),
            amount: 0,
            max_fee_per_tx: 0,
            nonce: 0,
            signature: "".to_string(),
            hash: String::new(),
            is_coinbase: true,
            memo: Some(genesis_memo),
        };
        meta_tx.hash = meta_tx.calculate_hash();
        txs0.push(meta_tx);

        // Block 1: 1000 registrations
        // Block 2: 1000 bonds
        let mut txs1: Vec<Transaction> = Vec::with_capacity(N);
        let mut txs2: Vec<Transaction> = Vec::with_capacity(N);

        for i in 0..(N as u32) {
            let owner_sk = SigningKey::from_bytes(&mk_seed(i, 1));
            let owner_b64 = B64.encode(owner_sk.verifying_key().to_bytes());

            let val_sk = SigningKey::from_bytes(&mk_seed(i, 2));
            let val_b64 = B64.encode(val_sk.verifying_key().to_bytes());

            let reg_memo = serde_json::to_string(&json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "register_validator",
                "consensus_pubkey_b64": val_b64.clone(),
                "net_addr": format!("/ip4/127.0.0.1/tcp/{}", 10_000 + (i as u64)),
                "commission_bps": 0u64,
                "metadata": format!("v{}", i),
            }))
            .unwrap();

            txs1.push(Transaction::new(
                owner_b64.clone(),
                staking::STAKE_RECEIVER.to_string(),
                0,
                1,
                0,
                "".to_string(),
                false,
                Some(reg_memo),
            ));

            let bond_memo = serde_json::to_string(&json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "bond",
                "validator_pk_b64": val_b64.clone(),
            }))
            .unwrap();

            txs2.push(Transaction::new(
                owner_b64,
                staking::STAKE_RECEIVER.to_string(),
                MIN_STAKE,
                2,
                0,
                "".to_string(),
                false,
                Some(bond_memo),
            ));
        }

        // Run once
        let smt = StateSmt::ephemeral();

        let r0 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, "", 0, &txs0, true, None, None, None,
        )
        .unwrap();
        let r1 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, &r0, 1, &txs1, false, None, None, None,
        )
        .unwrap();
        let r2 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, &r1, 2, &txs2, false, None, None, None,
        )
        .unwrap();

        let rb = bytes32_from_hex(&r2).unwrap();
        let st_tb = smt
            .get_account(rb, staking::k_total_bonded())
            .unwrap()
            .unwrap();
        assert_eq!(
            staking::decode_total_bonded_state(&st_tb).unwrap().total,
            (N as u64) * MIN_STAKE
        );

        // Replay from scratch
        let smt2 = StateSmt::ephemeral();

        let r0b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, "", 0, &txs0, true, None, None, None,
        )
        .unwrap();
        let r1b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, &r0b, 1, &txs1, false, None, None, None,
        )
        .unwrap();
        let r2b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, &r1b, 2, &txs2, false, None, None, None,
        )
        .unwrap();

        assert_eq!(r2, r2b, "replay must match for 1000 validators");
    }

    // -----------------------------------------------------
    // Phase 2 tests (RANDAO seed/committee + penalty)
    // -----------------------------------------------------

    #[test]
    fn phase2_randao_seed_committee_penalty_deterministic_even_with_empty_epoch_boundary_block() {
        // Bind seed(0) deterministically to a fixed chain id for the unit test.
        crate::chain_identity::init_chain_id("unit-test-chain-phase2").unwrap();

        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
        use serde_json::json;

        // Small epoch_len so we can cross epoch boundaries quickly in a unit test.
        let params = staking::PosParamsV1 {
            min_stake: 10,
            unbonding_epochs: 1,
            epoch_len: 2,
            committee_size: 2,
        };

        // Deterministic pseudo-keys (no signature checks in Phase 1/2 register/bond).
        let v1: [u8; 32] = [1u8; 32];
        let v2: [u8; 32] = [2u8; 32];
        let v3: [u8; 32] = [3u8; 32];

        let pk1_b64 = B64.encode(v1);
        let pk2_b64 = B64.encode(v2);
        let pk3_b64 = B64.encode(v3);

        let _pk1_hex = hex::encode(v1);
        let _pk2_hex = hex::encode(v2);
        let pk3_hex = hex::encode(v3);

        // Secrets & commits for epoch 1 (commit in epoch 0, reveal in epoch 1).
        let s1: [u8; 32] = [0xA1u8; 32];
        let s2: [u8; 32] = [0xA2u8; 32];
        let s3: [u8; 32] = [0xA3u8; 32];

        let c1_b64 = B64.encode(pos::commit_hash_v1(&s1));
        let c2_b64 = B64.encode(pos::commit_hash_v1(&s2));
        let c3_b64 = B64.encode(pos::commit_hash_v1(&s3));

        let s1_b64 = B64.encode(s1);
        let s2_b64 = B64.encode(s2);
        let _s3_b64 = B64.encode(s3);

        // Common coinbase meta memo (keeps economic counters deterministic).
        let meta = CoinbaseEconMetaV2 {
            v: 2,
            base_fee_per_tx: 0,
            user_txs: 0,
            total_fees: 0,
            burned: 0,
            to_treasury_from_fees: 0,
            slashed_to_treasury: 0,
            reward_total: 0,
            reward_to_treasury: 0,
            reward_to_miner_base: 0,
        };
        let meta_memo = serde_json::to_string(&meta).unwrap();

        // Genesis PoS params memo
        let genesis_memo = serde_json::to_string(&GenesisPosParamsMemoV1 {
            v: 1,
            kind: "genesis_pos_params_v1".to_string(),
            pos_params: params.clone(),
        })
        .unwrap();

        let owner1 = "OWNER_1";
        let owner2 = "OWNER_2";
        let owner3 = "OWNER_3";

        // -------------------------------------------------
        // Block 0 (height 0): fund owners + set params + register + bond
        // -------------------------------------------------
        let mut txs0: Vec<Transaction> = Vec::new();

        // coinbase meta
        txs0.push(Transaction {
            sender: "COINBASE".to_string(),
            receiver: "MINER".to_string(),
            amount: 0,
            max_fee_per_tx: 0,
            nonce: 0,
            signature: "".to_string(),
            hash: "cb0".to_string(),
            is_coinbase: true,
            memo: Some(meta_memo.clone()),
        });

        // fund owners
        for (i, o) in [owner1, owner2, owner3].iter().enumerate() {
            txs0.push(Transaction {
                sender: "COINBASE".to_string(),
                receiver: (*o).to_string(),
                amount: 1_000,
                max_fee_per_tx: 0,
                nonce: 0,
                signature: "".to_string(),
                hash: format!("alloc{}", i),
                is_coinbase: true,
                memo: Some("genesis_alloc".to_string()),
            });
        }

        // genesis pos params
        txs0.push(Transaction {
            sender: "COINBASE".to_string(),
            receiver: "MINER".to_string(),
            amount: 0,
            max_fee_per_tx: 0,
            nonce: 0,
            signature: "".to_string(),
            hash: "pos_params".to_string(),
            is_coinbase: true,
            memo: Some(genesis_memo),
        });

        // register + bond x3
        let regs = [
            (owner1, pk1_b64.clone(), "9001"),
            (owner2, pk2_b64.clone(), "9002"),
            (owner3, pk3_b64.clone(), "9003"),
        ];

        for (idx, (owner, pk_b64, port)) in regs.iter().enumerate() {
            let reg_memo = serde_json::to_string(&json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "register_validator",
                "consensus_pubkey_b64": pk_b64,
                "net_addr": format!("/ip4/127.0.0.1/tcp/{}", port),
                "commission_bps": 0u64,
                "metadata": format!("v{}", idx),
            }))
            .unwrap();

            txs0.push(Transaction {
                sender: (*owner).to_string(),
                receiver: staking::STAKE_RECEIVER.to_string(),
                amount: 0,
                max_fee_per_tx: 0,
                nonce: 1,
                signature: "".to_string(),
                hash: format!("reg{}", idx),
                is_coinbase: false,
                memo: Some(reg_memo),
            });

            let bond_memo = serde_json::to_string(&json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "bond",
                "validator_pk_b64": pk_b64,
            }))
            .unwrap();

            txs0.push(Transaction {
                sender: (*owner).to_string(),
                receiver: staking::STAKE_RECEIVER.to_string(),
                amount: params.min_stake,
                max_fee_per_tx: 0,
                nonce: 2,
                signature: "".to_string(),
                hash: format!("bond{}", idx),
                is_coinbase: false,
                memo: Some(bond_memo),
            });
        }

        // -------------------------------------------------
        // Block 1 (height 1): commits for epoch 1 (end of epoch 0)
        // -------------------------------------------------
        let mut txs1: Vec<Transaction> = Vec::new();
        txs1.push(Transaction {
            sender: "COINBASE".to_string(),
            receiver: "MINER".to_string(),
            amount: 0,
            max_fee_per_tx: 0,
            nonce: 0,
            signature: "".to_string(),
            hash: "cb1".to_string(),
            is_coinbase: true,
            memo: Some(meta_memo.clone()),
        });

        let commits = [
            (owner1, c1_b64.clone()),
            (owner2, c2_b64.clone()),
            (owner3, c3_b64.clone()),
        ];

        for (idx, (owner, c_b64)) in commits.iter().enumerate() {
            let memo = serde_json::to_string(&json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "randao_commit",
                "epoch": 1u64,
                "commit_b64": c_b64,
            }))
            .unwrap();

            txs1.push(Transaction {
                sender: (*owner).to_string(),
                receiver: staking::STAKE_RECEIVER.to_string(),
                amount: 0,
                max_fee_per_tx: 0,
                nonce: 3,
                signature: "".to_string(),
                hash: format!("commit{}", idx),
                is_coinbase: false,
                memo: Some(memo),
            });
        }

        // -------------------------------------------------
        // Block 2 (height 2): reveals for epoch 1 (only 2/3 reveal)
        // -------------------------------------------------
        let mut txs2: Vec<Transaction> = Vec::new();
        txs2.push(Transaction {
            sender: "COINBASE".to_string(),
            receiver: "MINER".to_string(),
            amount: 0,
            max_fee_per_tx: 0,
            nonce: 0,
            signature: "".to_string(),
            hash: "cb2".to_string(),
            is_coinbase: true,
            memo: Some(meta_memo.clone()),
        });

        let reveals = [
            (owner1, s1_b64.clone()),
            (owner2, s2_b64.clone()),
            // owner3 intentionally DOES NOT reveal (penalty at end of epoch 1)
        ];

        for (idx, (owner, s_b64)) in reveals.iter().enumerate() {
            let memo = serde_json::to_string(&json!({
                "v": 1,
                "kind": "stake_call_v1",
                "op": "randao_reveal",
                "epoch": 1u64,
                "secret_b64": s_b64,
            }))
            .unwrap();

            txs2.push(Transaction {
                sender: (*owner).to_string(),
                receiver: staking::STAKE_RECEIVER.to_string(),
                amount: 0,
                max_fee_per_tx: 0,
                nonce: 4,
                signature: "".to_string(),
                hash: format!("reveal{}", idx),
                is_coinbase: false,
                memo: Some(memo),
            });
        }

        // -------------------------------------------------
        // Block 3 (height 3): empty (coinbase-only) end of epoch 1
        // MUST still finalize seed(2) + committee(2) and apply non-reveal penalty.
        // -------------------------------------------------
        let txs3: Vec<Transaction> = vec![Transaction {
            sender: "COINBASE".to_string(),
            receiver: "MINER".to_string(),
            amount: 0,
            max_fee_per_tx: 0,
            nonce: 0,
            signature: "".to_string(),
            hash: "cb3".to_string(),
            is_coinbase: true,
            memo: Some(meta_memo.clone()),
        }];

        // ---- Run once ----
        let smt = StateSmt::ephemeral();

        let r0 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, "", 0, &txs0, true, None, None, None,
        )
        .unwrap();
        let r1 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, &r0, 1, &txs1, true, None, None, None,
        )
        .unwrap();
        let r2 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, &r1, 2, &txs2, true, None, None, None,
        )
        .unwrap();
        let r3 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt, &r2, 3, &txs3, true, None, None, None,
        )
        .unwrap();

        // Seed(1) and committee(1) must exist after height 1 finalization.
        let rb1 = bytes32_from_hex(&r1).unwrap();
        assert!(
            smt.get_account(rb1, pos::k_seed(1)).unwrap().is_some(),
            "seed(1) missing"
        );
        assert!(
            smt.get_account(rb1, pos::k_committee(1)).unwrap().is_some(),
            "committee(1) missing"
        );

        // Seed(2) and committee(2) must exist after height 3 finalization (coinbase-only boundary block).
        let rb3 = bytes32_from_hex(&r3).unwrap();
        assert!(
            smt.get_account(rb3, pos::k_seed(2)).unwrap().is_some(),
            "seed(2) missing"
        );
        let comm2_st = smt.get_account(rb3, pos::k_committee(2)).unwrap().unwrap();
        let comm2 = pos::decode_committee_state_any(&comm2_st).unwrap();
        assert!(
            !comm2.pk_hex_list().iter().any(|x| x == &pk3_hex),
            "non-revealer must not be selected in committee(2)"
        );

        // Non-revealer must be jailed deterministically.
        let v3_st = smt
            .get_account(rb3, staking::k_validator(&pk3_hex))
            .unwrap()
            .unwrap();
        let v3_rec = staking::decode_validator_state(&v3_st).unwrap();
        assert!(matches!(v3_rec.status, staking::ValidatorStatusV1::Jailed));
        assert!(v3_rec.jailed_until_epoch >= 3);

        // ---- Replay determinism ----
        let smt2 = StateSmt::ephemeral();

        let r0b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, "", 0, &txs0, true, None, None, None,
        )
        .unwrap();
        let r1b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, &r0b, 1, &txs1, true, None, None, None,
        )
        .unwrap();
        let r2b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, &r1b, 2, &txs2, true, None, None, None,
        )
        .unwrap();
        let r3b = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt2, &r2b, 3, &txs3, true, None, None, None,
        )
        .unwrap();

        assert_eq!(r3, r3b, "phase2 replay must match");
    }

