    // -----------------------------------------------------
    // Phase 3C — Fork-choice deterministic (finality-first)
    // -----------------------------------------------------

    fn mk_block_for_test(index: u64, prev_hash: &str, hash: &str, pos_epoch: u64) -> Block {
        Block {
            index,
            timestamp: index, // deterministic
            transactions: Vec::new(),
            tx_root: "0".repeat(64),
            state_root: "0".repeat(64),
            previous_hash: prev_hash.to_string(),
            hash: hash.to_string(),
            miner_pub_key: "miner".to_string(),
            signature: None,
            governance_txs: Vec::new(),
            cognitive_txs: Vec::new(),
            pos_epoch,
            pos_slot: index,
            pos_round: 0,
            pos_proof: None,
            finality_qc: None,
            evidence: Vec::new(),
            nft_events: Vec::new(),
        }
    }

    fn mk_chain_with_hashes(hashes: &[String]) -> Blockchain {
        let mut bc = Blockchain::new();
        // force slot mode on for Phase 3C fork-choice path
        bc.slot_pacing.slot_pacing_enabled = true;
        bc.slot_pacing.pos_finality_bft_activation_epoch = 0;

        // Start from a deterministic genesis and then override hashes for controllability.
        // Keep previous_hash linking coherent (structural).
        let mut chain: Vec<Block> = Vec::new();
        let ghash = hashes.first().cloned().unwrap_or_else(|| "00".repeat(32));
        let genesis = mk_block_for_test(0, "GENESIS", &ghash, 0);
        chain.push(genesis);

        for (i, h) in hashes.iter().enumerate().skip(1) {
            let prev = chain[i - 1].hash.clone();
            let blk = mk_block_for_test(i as u64, &prev, h, 1);
            chain.push(blk);
        }

        bc.chain = chain;
        if let Some(g) = bc.chain.first() {
            bc.genesis_hash = g.hash.clone();
            bc.genesis_time = g.timestamp;
        }
        bc
    }

    fn set_meta(bc: &mut Blockchain, finalized_h: u64, highest_qc_h: u64) {
        let fh_usize = finalized_h as usize;
        let qh_usize = highest_qc_h as usize;
        let fh_hash = bc
            .chain
            .get(fh_usize)
            .map(|b| b.hash.clone())
            .unwrap_or_default();
        let qh_hash = bc
            .chain
            .get(qh_usize)
            .map(|b| b.hash.clone())
            .unwrap_or_default();

        bc.finality_bft_meta_rt = FinalityBftMetaV1 {
            finalized_height: finalized_h,
            finalized_hash: fh_hash,
            highest_qc_height: highest_qc_h,
            highest_qc_round: 0,
            highest_qc_block_hash: qh_hash,
        };
    }

    #[test]
    fn fork_choice_prefers_higher_finalized_height() {
        let rep = crate::peer_reputation::PeerReputationManager::new(
            crate::peer_reputation::ReputationConfig::default(),
        );

        let mut a = mk_chain_with_hashes(&[
            "aa".repeat(32),
            "01".repeat(32),
            "02".repeat(32),
            "03".repeat(32),
        ]);
        let mut b = mk_chain_with_hashes(&[
            "aa".repeat(32),
            "01".repeat(32),
            "02".repeat(32),
            "ff".repeat(32),
        ]);

        set_meta(&mut a, 1, 2);
        set_meta(&mut b, 2, 2);

        assert!(a.is_other_chain_better(&b, &rep));
        assert!(!b.is_other_chain_better(&a, &rep));
    }

    #[test]
    fn fork_choice_prefers_higher_highest_qc_when_finalized_equal() {
        let rep = crate::peer_reputation::PeerReputationManager::new(
            crate::peer_reputation::ReputationConfig::default(),
        );

        let mut a = mk_chain_with_hashes(&[
            "aa".repeat(32),
            "10".repeat(32),
            "11".repeat(32),
            "12".repeat(32),
            "13".repeat(32),
        ]);
        let mut b = mk_chain_with_hashes(&[
            "aa".repeat(32),
            "10".repeat(32),
            "11".repeat(32),
            "12".repeat(32),
            "14".repeat(32),
        ]);

        set_meta(&mut a, 2, 3);
        set_meta(&mut b, 2, 4);

        assert!(a.is_other_chain_better(&b, &rep));
        assert!(!b.is_other_chain_better(&a, &rep));
    }

    #[test]
    fn fork_choice_tie_break_is_lowest_tip_hash() {
        let rep = crate::peer_reputation::PeerReputationManager::new(
            crate::peer_reputation::ReputationConfig::default(),
        );

        // same finalized & highest_qc & height, only tip hash differs
        let mut a = mk_chain_with_hashes(&[
            "aa".repeat(32),
            "10".repeat(32),
            "11".repeat(32),
            "22".repeat(32), // tip bigger
        ]);
        let mut b = mk_chain_with_hashes(&[
            "aa".repeat(32),
            "10".repeat(32),
            "11".repeat(32),
            "00".repeat(32), // tip smaller => should win
        ]);

        set_meta(&mut a, 2, 2);
        set_meta(&mut b, 2, 2);

        assert!(a.is_other_chain_better(&b, &rep));
        assert!(!b.is_other_chain_better(&a, &rep));
    }

    #[test]
    fn safety_gate_rejects_conflicting_finalized_checkpoint() {
        let rep = crate::peer_reputation::PeerReputationManager::new(
            crate::peer_reputation::ReputationConfig::default(),
        );

        let mut a = mk_chain_with_hashes(&[
            "aa".repeat(32),
            "10".repeat(32),
            "11".repeat(32),
            "12".repeat(32),
        ]);
        let mut b = mk_chain_with_hashes(&[
            "aa".repeat(32),
            "10".repeat(32),
            "ff".repeat(32), // diverge at height 2
            "12".repeat(32),
        ]);

        // Both claim finalized_height=2 but disagree on hash at height 2.
        set_meta(&mut a, 2, 2);
        set_meta(&mut b, 2, 2);

        // other cannot be considered "better" because it violates finalized consistency gate.
        assert!(!a.is_other_chain_better(&b, &rep));
        assert!(!b.is_other_chain_better(&a, &rep));
    }

    #[test]
    fn anti_equivocation_persists_across_restart() {
        use std::sync::Arc;

        let _lock = test_process_lock();
        let dir = tempfile::tempdir().unwrap();
        let storage1 = Arc::new(crate::storage::DbStore::open(dir.path()).unwrap());

        let mut bc1 = Blockchain::new();
        bc1.attach_storage(storage1.clone());

        let vote = crate::finality_bft::FinalityBftVoteV1 {
            epoch: 1,
            height: 123,
            round: 0,
            block_hash: "11".repeat(32),
            voter_pk_hex: "aa".repeat(32),
            sig_b64: "sig".to_string(), // signature not checked by storage
        };

        bc1.finality_bft_last_vote_store(&vote).unwrap();

        drop(bc1);
        drop(storage1);
        crate::storage::evict_canonical_db_for_path(dir.path());

        let storage2 = Arc::new(crate::storage::DbStore::open(dir.path()).unwrap());
        let mut bc2 = Blockchain::new();
        bc2.attach_storage(storage2);

        let err = bc2
            .finality_bft_enforce_no_double_vote(123, 0, &"ff".repeat(32))
            .expect_err("must reject different block_hash for same (height,round)");
        assert!(err.contains("bft_double_vote_blocked"));

        // idempotent if same hash
        bc2.finality_bft_enforce_no_double_vote(123, 0, &"11".repeat(32))
            .expect("same vote must be idempotent");
    }

    #[test]
    fn finality_meta_persists_across_restart() {
        use std::sync::Arc;

        let _lock = test_process_lock();
        let dir = tempfile::tempdir().unwrap();
        let storage1 = Arc::new(crate::storage::DbStore::open(dir.path()).unwrap());

        let hashes = [
            "aa".repeat(32),
            "01".repeat(32),
            "02".repeat(32),
            "03".repeat(32),
        ];

        let mut bc1 = mk_chain_with_hashes(&hashes);
        bc1.attach_storage(storage1.clone());
        bc1.set_test_finality_meta(1, hashes[1].clone(), 2, 7, hashes[2].clone());
        bc1.finality_bft_store_meta_best_effort();

        drop(bc1);
        drop(storage1);
        crate::storage::evict_canonical_db_for_path(dir.path());

        let storage2 = Arc::new(crate::storage::DbStore::open(dir.path()).unwrap());
        let mut bc2 = mk_chain_with_hashes(&hashes);
        bc2.attach_storage(storage2);

        assert_eq!(bc2.finality_bft_meta_rt.finalized_height, 1);
        assert_eq!(bc2.finality_bft_meta_rt.finalized_hash, hashes[1]);
        assert_eq!(bc2.finality_bft_meta_rt.highest_qc_height, 2);
        assert_eq!(bc2.finality_bft_meta_rt.highest_qc_round, 7);
        assert_eq!(bc2.finality_bft_meta_rt.highest_qc_block_hash, hashes[2]);
    }

    #[test]
    fn finality_qc_archive_persists_across_restart_and_restores_cache() {
        use std::sync::Arc;

        let _lock = test_process_lock();
        let dir = tempfile::tempdir().unwrap();
        let storage1 = Arc::new(crate::storage::DbStore::open(dir.path()).unwrap());

        let (_seed_a, a_pk, a_sk_b64) = test_signing_key_material(0x91);
        let (_seed_b, b_pk, b_sk_b64) = test_signing_key_material(0x92);
        let (_seed_c, c_pk, c_sk_b64) = test_signing_key_material(0x93);
        let committee = vec![(a_pk.clone(), 11), (b_pk.clone(), 17), (c_pk.clone(), 23)];
        let validator_weights = vec![(a_pk.clone(), 3), (b_pk.clone(), 5), (c_pk.clone(), 7)];
        let state_root = build_pos_state_root(&storage1, &committee, 100);

        let mut bc1 = Blockchain::new();
        let gov = test_governance(&validator_weights);
        bc1.governance = Some(gov);
        bc1.chain[0].state_root = state_root.clone();
        bc1.chain[0].hash = "aa".repeat(32);

        let mut prev = bc1.chain[0].clone();
        prev.index = 1;
        prev.timestamp = 1;
        prev.state_root = state_root;
        prev.hash = "10".repeat(32);
        prev.previous_hash = bc1.chain[0].hash.clone();
        bc1.chain.push(prev.clone());

        let mut blk = prev.clone();
        blk.index = 2;
        blk.timestamp = 2;
        blk.hash = "11".repeat(32);
        blk.previous_hash = prev.hash.clone();
        bc1.chain.push(blk.clone());
        bc1.attach_storage(storage1.clone());

        let sk_a = SigningKey::from_bytes(
            &STANDARD
                .decode(a_sk_b64)
                .unwrap()
                .as_slice()
                .try_into()
                .unwrap(),
        );
        let sk_b = SigningKey::from_bytes(
            &STANDARD
                .decode(b_sk_b64)
                .unwrap()
                .as_slice()
                .try_into()
                .unwrap(),
        );
        let sk_c = SigningKey::from_bytes(
            &STANDARD
                .decode(c_sk_b64)
                .unwrap()
                .as_slice()
                .try_into()
                .unwrap(),
        );
        let vote_a = crate::finality_bft::sign_vote_v1(
            &sk_a,
            crate::chain_identity::chain_id(),
            0,
            blk.index,
            9,
            &blk.hash,
        )
        .unwrap();
        let vote_b = crate::finality_bft::sign_vote_v1(
            &sk_b,
            crate::chain_identity::chain_id(),
            0,
            blk.index,
            9,
            &blk.hash,
        )
        .unwrap();
        let vote_c = crate::finality_bft::sign_vote_v1(
            &sk_c,
            crate::chain_identity::chain_id(),
            0,
            blk.index,
            9,
            &blk.hash,
        )
        .unwrap();
        let committee_pk = vec![a_pk.clone(), b_pk.clone(), c_pk.clone()];
        let qc = crate::finality_bft::build_cert_v1(
            crate::chain_identity::chain_id(),
            0,
            blk.index,
            9,
            &blk.hash,
            &committee_pk,
            &[vote_a, vote_b, vote_c],
        )
        .unwrap();

        bc1.finality_bft_qc_archive_put_best_effort(&qc, 3);
        drop(bc1);
        drop(storage1);
        crate::storage::evict_canonical_db_for_path(dir.path());

        let storage2 = Arc::new(crate::storage::DbStore::open(dir.path()).unwrap());
        let state_root2 = build_pos_state_root(&storage2, &committee, 100);
        let mut bc2 = Blockchain::new();
        let gov2 = test_governance(&validator_weights);
        bc2.governance = Some(gov2);
        bc2.chain[0].state_root = state_root2.clone();
        bc2.chain[0].hash = "aa".repeat(32);
        let mut prev2 = bc2.chain[0].clone();
        prev2.index = 1;
        prev2.timestamp = 1;
        prev2.state_root = state_root2;
        prev2.hash = "10".repeat(32);
        prev2.previous_hash = bc2.chain[0].hash.clone();
        bc2.chain.push(prev2.clone());
        let mut blk2 = prev2.clone();
        blk2.index = 2;
        blk2.timestamp = 2;
        blk2.hash = "11".repeat(32);
        blk2.previous_hash = prev2.hash.clone();
        bc2.chain.push(blk2);
        bc2.attach_storage(storage2);

        let restored = bc2
            .finality_bft_rt
            .qc_by_block
            .get(&"11".repeat(32))
            .expect("qc cache must be restored from durable archive on restart");
        assert_eq!(restored.height, 2);
        assert_eq!(restored.round, 9);
        assert_eq!(restored.block_hash, "11".repeat(32));
    }

