    #[test]
    fn nft_indexes_update_on_create_mint_transfer_and_burn() {
        let smt = StateSmt::ephemeral();
        let gov = nft_gov_enabled(0);
        let owner = nft_test_addr(1);
        let alice = nft_test_addr(2);

        let root1 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            "",
            1,
            &[nft_tx(
                &owner,
                0,
                &nft_create_op(
                    "IDX",
                    crate::nft::NftAssetTypeV1::Collectible,
                    crate::nft::NftTransferPolicyV1::Transferable,
                    false,
                    true,
                ),
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("create collection");
        let r1 = bytes32_from_hex(&root1).unwrap();
        assert_eq!(
            smt.get_account(r1, crate::nft::k_nft_owner_count(&owner))
                .unwrap()
                .unwrap()
                .balance,
            1
        );
        let cidx = smt
            .get_account(r1, crate::nft::k_nft_owner_collection_item(&owner, 0))
            .unwrap()
            .unwrap();
        let cref = crate::nft::decode_collection_ref_state_v1(&cidx).unwrap();
        assert_eq!(cref.collection_id, 1);

        let root2 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root1,
            2,
            &[nft_tx(&owner, 1, &nft_mint_op(owner.clone(), None))],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("mint");
        let r2 = bytes32_from_hex(&root2).unwrap();
        assert_eq!(
            smt.get_account(r2, crate::nft::k_nft_owner_token_count(&owner))
                .unwrap()
                .unwrap()
                .balance,
            1
        );
        assert_eq!(
            smt.get_account(r2, crate::nft::k_nft_collection_token_count(1))
                .unwrap()
                .unwrap()
                .balance,
            1
        );
        let tref = crate::nft::decode_token_ref_state_v1(
            &smt.get_account(r2, crate::nft::k_nft_owner_token_item(&owner, 0))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!((tref.collection_id, tref.serial), (1, 1));
        let idx_ref = crate::nft::decode_token_index_ref_state_v1(
            &smt.get_account(r2, crate::nft::k_nft_token_index_ref(1, 1))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(idx_ref.owner_b64, owner);
        assert_eq!(idx_ref.owner_index, 0);
        assert_eq!(idx_ref.collection_index, 0);

        let root3 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root2,
            3,
            &[nft_tx(
                &owner,
                2,
                &crate::nft::NftOpV1::Transfer {
                    collection_id: 1,
                    serial: 1,
                    to_b64: alice.clone(),
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("transfer");
        let r3 = bytes32_from_hex(&root3).unwrap();
        assert_eq!(
            smt.get_account(r3, crate::nft::k_nft_owner_token_count(&owner))
                .unwrap()
                .unwrap()
                .balance,
            0
        );
        assert_eq!(
            smt.get_account(r3, crate::nft::k_nft_owner_token_count(&alice))
                .unwrap()
                .unwrap()
                .balance,
            1
        );
        assert_eq!(
            smt.get_account(r3, crate::nft::k_nft_collection_token_count(1))
                .unwrap()
                .unwrap()
                .balance,
            1
        );
        let idx_ref = crate::nft::decode_token_index_ref_state_v1(
            &smt.get_account(r3, crate::nft::k_nft_token_index_ref(1, 1))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(idx_ref.owner_b64, alice);
        assert_eq!(idx_ref.owner_index, 0);
        assert_eq!(idx_ref.collection_index, 0);

        let root4 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root3,
            4,
            &[nft_tx(
                &alice,
                0,
                &crate::nft::NftOpV1::Burn {
                    collection_id: 1,
                    serial: 1,
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("burn");
        let r4 = bytes32_from_hex(&root4).unwrap();
        assert_eq!(
            smt.get_account(r4, crate::nft::k_nft_owner_token_count(&alice))
                .unwrap()
                .unwrap()
                .balance,
            0
        );
        assert_eq!(
            smt.get_account(r4, crate::nft::k_nft_collection_token_count(1))
                .unwrap()
                .unwrap()
                .balance,
            0
        );
        assert!(smt
            .get_account(r4, crate::nft::k_nft_token_index_ref(1, 1))
            .unwrap()
            .is_none());
    }

    #[test]
    fn nft_owner_index_swap_remove_updates_moved_token_ref() {
        let smt = StateSmt::ephemeral();
        let gov = nft_gov_enabled(0);
        let owner = nft_test_addr(1);
        let alice = nft_test_addr(2);

        let root1 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            "",
            1,
            &[nft_tx(
                &owner,
                0,
                &nft_create_op(
                    "OWNIDX",
                    crate::nft::NftAssetTypeV1::Collectible,
                    crate::nft::NftTransferPolicyV1::Transferable,
                    false,
                    true,
                ),
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("create collection");
        let root2 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root1,
            2,
            &[
                nft_tx(&owner, 1, &nft_mint_op(owner.clone(), None)),
                nft_tx(&owner, 2, &nft_mint_op(owner.clone(), None)),
            ],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("mint two tokens");
        let root3 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root2,
            3,
            &[nft_tx(
                &owner,
                3,
                &crate::nft::NftOpV1::Transfer {
                    collection_id: 1,
                    serial: 1,
                    to_b64: alice.clone(),
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("transfer non-last owner token");
        let r3 = bytes32_from_hex(&root3).unwrap();

        assert_eq!(
            smt.get_account(r3, crate::nft::k_nft_owner_token_count(&owner))
                .unwrap()
                .unwrap()
                .balance,
            1
        );
        assert_eq!(
            smt.get_account(r3, crate::nft::k_nft_owner_token_count(&alice))
                .unwrap()
                .unwrap()
                .balance,
            1
        );
        let moved = crate::nft::decode_token_ref_state_v1(
            &smt.get_account(r3, crate::nft::k_nft_owner_token_item(&owner, 0))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!((moved.collection_id, moved.serial), (1, 2));
        assert!(smt
            .get_account(r3, crate::nft::k_nft_owner_token_item(&owner, 1))
            .unwrap()
            .is_none());
        let moved_idx = crate::nft::decode_token_index_ref_state_v1(
            &smt.get_account(r3, crate::nft::k_nft_token_index_ref(1, 2))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(moved_idx.owner_b64, owner);
        assert_eq!(moved_idx.owner_index, 0);
        assert_eq!(moved_idx.collection_index, 1);
        let transferred_idx = crate::nft::decode_token_index_ref_state_v1(
            &smt.get_account(r3, crate::nft::k_nft_token_index_ref(1, 1))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(transferred_idx.owner_b64, alice);
        assert_eq!(transferred_idx.owner_index, 0);
        assert_eq!(transferred_idx.collection_index, 0);
    }

