    #[test]
    fn nft_revoke_gate_is_independent_from_burn_gate() {
        let mut gov = nft_gov_enabled(0);
        gov.params.nft_public_burn_enabled = false;
        gov.params.nft_public_revoke_enabled = true;
        let smt = StateSmt::ephemeral();
        let issuer = nft_test_addr(1);
        let alice = nft_test_addr(2);
        let root1 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            "",
            1,
            &[nft_tx(
                &issuer,
                0,
                &nft_create_op(
                    "RVK",
                    crate::nft::NftAssetTypeV1::Certificate,
                    crate::nft::NftTransferPolicyV1::Soulbound,
                    true,
                    true,
                ),
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("collection create allowed");
        let root2 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root1,
            2,
            &[nft_tx(&issuer, 1, &nft_mint_op(alice.clone(), None))],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("mint allowed");
        let burn_err = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root2,
            3,
            &[nft_tx(
                &alice,
                0,
                &crate::nft::NftOpV1::Burn {
                    collection_id: 1,
                    serial: 1,
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect_err("burn disabled must reject burn");
        assert!(
            burn_err.contains("nft_burn_disabled"),
            "unexpected error: {burn_err}"
        );
        Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root2,
            3,
            &[nft_tx(
                &issuer,
                2,
                &crate::nft::NftOpV1::Revoke {
                    collection_id: 1,
                    serial: 1,
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("revoke enabled must not depend on burn gate");
    }

