        #[test]
        fn emission_controller_policy_overrides_normalize_runtime_state() {
            let mut chain = Blockchain::test_make_emission_chain();
            let policy_file: EconomyPolicyFile = serde_json::from_value(serde_json::json!({
                "emission_controller_enabled": true,
                "emission_blocks_per_day": 1440,
                "emission_window_days": 14,
                "emission_consecutive_days_required": 21,
                "emission_hard_cap_days": 10,
                "emission_taper_days": 20,
                "emission_min_budget_per_validator_day_base": 420,
                "emission_launch_multiplier_max_bps": 12500,
                "emission_steady_multiplier_max_bps": 11000,
                "emission_multiplier_min_bps": 9000,
                "emission_reward_delta_max_bps_per_day": 25,
                "emission_reward_alpha_days_ppm": 15000,
                "emission_fill_raise_block_ppm": 400000,
                "emission_fill_lower_ppm": 700000,
                "emission_backlog_raise_block_ppm": 200000,
                "emission_backlog_lower_ppm": 800000
            }))
            .unwrap();

            chain.policy.emission_state.reward_multiplier_bps = 20_000;
            chain.policy.emission_state.reward_shadow_bps_fp = 0;
            chain
                .policy
                .emission_window
                .rolling_validator_fee_budget_days = vec![1, 2, 3];
            chain.policy.emission_window.rolling_reward_subsidy_days = vec![4, 5, 6];

            chain.apply_policy_file_overrides(&policy_file).unwrap();

            assert!(chain.policy.emission_controller.enabled);
            assert_eq!(chain.policy.emission_controller.blocks_per_day, 1_440);
            assert_eq!(chain.policy.emission_controller.window_days, 14);
            assert_eq!(
                chain.policy.emission_controller.consecutive_days_required,
                20
            );
            assert_eq!(chain.policy.emission_controller.hard_cap_days, 20);
            assert_eq!(chain.policy.emission_controller.taper_days, 20);
            assert_eq!(
                chain
                    .policy
                    .emission_controller
                    .min_budget_per_validator_day_base,
                420
            );
            assert_eq!(
                chain.policy.emission_controller.launch_multiplier_max_bps,
                12_500
            );
            assert_eq!(
                chain.policy.emission_controller.steady_multiplier_max_bps,
                11_000
            );
            assert_eq!(chain.policy.emission_controller.multiplier_min_bps, 9_000);
            assert_eq!(
                chain
                    .policy
                    .emission_controller
                    .reward_delta_max_bps_per_day,
                25
            );
            assert_eq!(
                chain.policy.emission_controller.reward_alpha_days_ppm,
                15_000
            );
            assert_eq!(chain.policy.emission_window.blocks_per_day, 1_440);
            assert_eq!(chain.policy.emission_window.window_days, 14);
            assert_eq!(
                chain
                    .policy
                    .emission_window
                    .rolling_validator_fee_budget_days
                    .len(),
                14
            );
            assert_eq!(
                chain
                    .policy
                    .emission_window
                    .rolling_reward_subsidy_days
                    .len(),
                14
            );
            assert_eq!(chain.policy.emission_state.reward_multiplier_bps, 12_500);
            assert_eq!(
                chain.policy.emission_state.reward_shadow_bps_fp,
                12_500u128 * EMISSION_MULTIPLIER_BPS_FP_SCALE
            );
        }

