        #[test]
        fn adaptive_fee_syncs_mempool_base_fee_hint_after_block_apply() {
            let mut chain = new_controller_chain();
            chain.policy.base_fee_per_tx = 115;
            chain.policy.base_fee_shadow = Blockchain::base_fee_shadow_from_fee_u64(115);

            let mempool = Arc::new(Mutex::new(Mempool::new()));
            {
                let mut mp = mempool.lock().unwrap_or_else(|e| e.into_inner());
                mp.set_base_fee_per_tx_hint(100);
                let tx = crate::transaction::Transaction::new(
                    "sender".to_string(),
                    "receiver".to_string(),
                    1,
                    1,
                    100,
                    String::new(),
                    false,
                    None,
                );
                assert!(mp.add(tx), "tx should enter with the old mempool fee hint");
                assert_eq!(mp.fee_policy_snapshot().2, 100);
                assert_eq!(mp.len(), 1);
            }

            let mut block = chain.create_block_dummy();
            block.index = 1;
            block.previous_hash = chain
                .chain
                .last()
                .map(|b| b.hash.clone())
                .unwrap_or_else(|| GENESIS_HASH.to_string());
            block.hash = "fee-sync-h1".to_string();
            chain.chain.push(block.clone());

            chain.on_block_applied_with_source(
                &block,
                Some(&mempool),
                EconomyApplySource::LocalMined,
            );

            let mp = mempool.lock().unwrap_or_else(|e| e.into_inner());
            assert_eq!(mp.fee_policy_snapshot().2, chain.policy.base_fee_per_tx);
            assert_eq!(chain.policy.base_fee_per_tx, 115);
            assert_eq!(
                mp.len(),
                0,
                "underpriced tx must be pruned after fee hint sync"
            );
        }

