        #[test]
        fn adaptive_fee_persistent_hot_backlog_holds_then_raises_after_cooldown() {
            let mut chain = new_controller_chain();
            chain.policy.base_fee_per_tx = 100;
            chain.policy.base_fee_shadow = Blockchain::base_fee_shadow_from_fee_u64(100);
            chain.policy.ema.ema_block_fill_ppm = 150_000;
            chain.policy.ema.ema_mempool = 40;
            chain.policy.ema.ctrl_cooldown = 1;

            chain.recompute_policy_from_ema();
            let first_fee = chain.policy.base_fee_per_tx;
            let mut saw_raise = chain.fee_action_for_api() == "raise";
            assert!(first_fee >= 100);
            assert!(matches!(chain.fee_action_for_api(), "hold" | "raise"));
            if first_fee > 100 {
                assert_eq!(chain.fee_action_for_api(), "raise");
                assert!(matches!(
                    chain.fee_reason_code_for_api(),
                    "hot_raise" | "raise_delta_capped"
                ));
            }

            chain.policy.ema.ema_block_fill_ppm = 150_000;
            chain.policy.ema.ema_mempool = 40;
            chain.recompute_policy_from_ema();
            saw_raise |= chain.fee_action_for_api() == "raise";
            assert!(chain.policy.base_fee_per_tx >= first_fee);
            assert!(matches!(chain.fee_action_for_api(), "hold" | "raise"));

            for _ in 0..6 {
                chain.policy.ema.ema_block_fill_ppm = 150_000;
                chain.policy.ema.ema_mempool = 40;
                chain.recompute_policy_from_ema();
                saw_raise |= chain.fee_action_for_api() == "raise";
            }

            assert!(chain.policy.base_fee_per_tx > 100);
            assert!(
                saw_raise,
                "persistent hot backlog must produce at least one raise over the cadence window"
            );
            assert!(matches!(chain.fee_action_for_api(), "hold" | "raise"));
        }

