        #[test]
        fn adaptive_fee_growth_is_bounded_under_long_congestion() {
            let mut chain = new_controller_chain();
            set_adaptive_test_fee(&mut chain, TEST_FEE_ANCHOR - 160);

            for _ in 0..50 {
                // Sustained hot backlog, not critical/excessive pressure. Critical pressure has
                // its own faster +15% path and is allowed to approach the configured max fee.
                chain.policy.ema.ema_block_fill_ppm = 150_000;
                chain.policy.ema.ema_mempool = 40;
                chain.recompute_policy_from_ema();
            }

            assert!(chain.policy.base_fee_per_tx > TEST_FEE_ANCHOR - 160);
            assert_eq!(chain.current_pressure_state_for_api(), "hot");
            assert!(
                chain.policy.base_fee_per_tx <= TEST_FEE_ANCHOR * 3 + TEST_FEE_ANCHOR / 2,
                "hot fee growth must remain bounded by cadence, got {}",
                chain.policy.base_fee_per_tx
            );
        }

        #[test]
        fn adaptive_fee_does_not_oscillate_aggressively_on_alternating_pressure() {
            let mut chain = new_controller_chain();
            set_adaptive_test_fee(&mut chain, TEST_FEE_ANCHOR);
            let mut min_seen = chain.policy.base_fee_per_tx;
            let mut max_seen = chain.policy.base_fee_per_tx;

            for step in 0..40u32 {
                let (fill, mempool) = if step % 2 == 0 {
                    (chain.policy.target_fill_ppm.saturating_add(50_000), 120)
                } else {
                    (chain.policy.target_fill_ppm.saturating_sub(50_000), 10)
                };
                chain.policy.ema.ema_block_fill_ppm = fill;
                chain.policy.ema.ema_mempool = mempool;
                chain.recompute_policy_from_ema();
                min_seen = min_seen.min(chain.policy.base_fee_per_tx);
                max_seen = max_seen.max(chain.policy.base_fee_per_tx);
            }

            assert!(max_seen.saturating_sub(min_seen) <= TEST_FEE_CEILING);
        }

