        #[test]
        fn stale_non_executable_backlog_holds_instead_of_raising() {
            let mut chain = new_controller_chain();
            let block = chain.create_block_dummy();

            // Total mempool backlog exists, but none of it is fee-eligible/mineable and no
            // new ingress arrives. After two observations this is stale backlog, not demand.
            chain.observe_block_stats(&block, 101, 101, 0, 0, 0, None);
            chain.observe_block_stats(&block, 101, 101, 0, 0, 0, None);

            assert!(chain.policy.last_observed_stale_backlog_hold_active);
            assert_eq!(chain.policy.last_observed_backlog_ratio_ppm, 0);

            chain.policy.last_fee_apply_height = 0;
            chain.recompute_policy_from_ema();

            assert_ne!(chain.current_pressure_state_for_api(), "hot");
            assert_ne!(chain.current_pressure_state_for_api(), "critical");
            assert_ne!(chain.fee_action_for_api(), "raise");
        }

