        #[test]
        fn adaptive_fee_enforces_min_max_and_directional_delta_caps() {
            let mut chain = new_controller_chain();
            chain.policy.base_fee_min = 90;
            chain.policy.base_fee_max = 115;
            chain.policy.base_fee_per_tx = 114;
            chain.policy.base_fee_shadow = Blockchain::base_fee_shadow_from_fee_u64(114);
            chain.policy.fee_max_raise_per_apply_bps = 100;
            chain.policy.fee_critical_raise_bps = 250;
            chain.policy.controller_observation_initialized = true;
            chain.policy.last_observed_block_fill_ppm = 1_000_000;
            chain.policy.last_observed_backlog_ratio_ppm = CTRL34_BACKLOG_MAX_PPM;
            chain.policy.ema.ema_block_fill_ppm = 1_000_000;
            chain.policy.ema.ema_mempool = 10_000;

            chain.recompute_policy_from_ema();
            assert!(chain.policy.base_fee_per_tx <= chain.policy.base_fee_max);
            assert!(
                chain.policy.fee_critical_raise_bps <= chain.policy.fee_max_raise_per_apply_bps
            );

            chain.policy.base_fee_per_tx = 91;
            chain.policy.base_fee_shadow = Blockchain::base_fee_shadow_from_fee_u64(91);
            chain.policy.controller_observation_initialized = true;
            chain.policy.last_observed_block_fill_ppm = 0;
            chain.policy.last_observed_backlog_ratio_ppm = 0;
            chain.policy.ema.ema_block_fill_ppm = 0;
            chain.policy.ema.ema_mempool = 0;
            chain.policy.current_regime = "idle".to_string();
            for _ in 0..8 {
                chain.recompute_policy_from_ema();
                chain.policy.ema.ema_block_fill_ppm = 0;
                chain.policy.ema.ema_mempool = 0;
                chain.policy.last_observed_block_fill_ppm = 0;
                chain.policy.last_observed_backlog_ratio_ppm = 0;
                chain.policy.controller_observation_initialized = true;
                chain.policy.current_regime = "idle".to_string();
            }
            assert!(chain.policy.base_fee_per_tx >= chain.policy.base_fee_min);
        }

