        #[test]
        fn adaptive_fee_raise_realized_delta_never_exceeds_controller_percent() {
            let mut chain = new_controller_chain();
            chain.policy.base_fee_per_tx = 50;
            // Simulate stale/future shadow state. A raise must still be bounded by the
            // selected critical raise percentage from the current visible fee.
            chain.policy.base_fee_shadow = Blockchain::base_fee_shadow_from_fee_u64(150);
            chain.policy.last_fee_apply_height = 0;
            chain.policy.controller_observation_initialized = true;
            chain.policy.last_observed_block_fill_ppm = 1_000_000;
            chain.policy.last_observed_backlog_ratio_ppm = CTRL34_BACKLOG_MAX_PPM;
            chain.policy.ema.ema_block_fill_ppm = 1_000_000;
            chain.policy.ema.ema_mempool = 10_000;

            chain.recompute_policy_from_ema();

            let expected_ceiling = Blockchain::max_base_fee_after_raise_delta_u64(
                50,
                chain.policy.fee_critical_raise_bps.saturating_mul(100),
                chain.policy.base_fee_min,
                chain.policy.base_fee_max,
            );
            assert_eq!(chain.current_pressure_state_for_api(), "critical");
            assert_eq!(chain.fee_action_for_api(), "raise");
            assert!(chain.policy.base_fee_per_tx <= expected_ceiling);
            assert!(
                chain.policy.last_fee_raise_delta_realized_ppm
                    <= chain.policy.fee_critical_raise_bps.saturating_mul(100)
            );
        }

