        #[test]
        fn adaptive_fee_critical_raises_faster_than_hot() {
            let mut hot = new_controller_chain();
            hot.policy.base_fee_per_tx = 100;
            hot.policy.base_fee_shadow = Blockchain::base_fee_shadow_from_fee_u64(100);
            hot.policy.last_fee_apply_height = 0;
            hot.policy.controller_observation_initialized = true;
            hot.policy.last_observed_block_fill_ppm = hot
                .policy
                .target_fill_ppm
                .saturating_add(hot.policy.deadband_fill_ppm);
            hot.policy.last_observed_backlog_ratio_ppm = hot
                .policy
                .backlog_congested_enter_ppm
                .saturating_add(10_000);
            hot.policy.ema.ema_block_fill_ppm = hot
                .policy
                .target_fill_ppm
                .saturating_add(hot.policy.deadband_fill_ppm);
            hot.policy.ema.ema_mempool = 60;
            hot.recompute_policy_from_ema();
            let hot_fee = hot.policy.base_fee_per_tx;

            let mut critical = new_controller_chain();
            critical.policy.base_fee_per_tx = 100;
            critical.policy.base_fee_shadow = Blockchain::base_fee_shadow_from_fee_u64(100);
            critical.policy.last_fee_apply_height = 0;
            critical.policy.last_fee_critical_streak =
                CTRL34_FEE_CRITICAL_STREAK_BLOCKS.saturating_sub(1);
            critical.policy.controller_observation_initialized = true;
            critical.policy.last_observed_block_fill_ppm = 1_000_000;
            critical.policy.last_observed_backlog_ratio_ppm = CTRL34_BACKLOG_MAX_PPM;
            critical.policy.ema.ema_block_fill_ppm = 1_000_000;
            critical.policy.ema.ema_mempool = 10_000;
            critical.recompute_policy_from_ema();
            let critical_fee = critical.policy.base_fee_per_tx;

            assert_eq!(hot.current_pressure_state_for_api(), "hot");
            assert_eq!(critical.current_pressure_state_for_api(), "critical");
            assert!(critical_fee > hot_fee);
        }

