        #[test]
        fn adaptive_fee_bounded_growth_and_decay_over_long_phase_sequence() {
            let mut chain = new_controller_chain();
            set_adaptive_test_fee(&mut chain, TEST_FEE_ANCHOR);
            let start_fee = chain.policy.base_fee_per_tx;

            for _ in 0..60 {
                // Hot/congested but below the critical/excessive threshold; this test validates
                // the +5% hot cadence rather than the emergency +15% critical path.
                chain.policy.ema.ema_block_fill_ppm = 150_000;
                chain.policy.ema.ema_mempool = 40;
                chain.recompute_policy_from_ema();
            }
            assert_eq!(chain.current_pressure_state_for_api(), "hot");
            let congested_fee = chain.policy.base_fee_per_tx;

            for _ in 0..20 {
                // Leave the congested regime instead of keeping fill exactly at the
                // congested-exit threshold. This validates a neutral/hold phase, not
                // another hot/congested raise phase.
                chain.policy.ema.ema_block_fill_ppm = chain
                    .policy
                    .target_fill_ppm
                    .saturating_sub(chain.policy.deadband_fill_ppm);
                chain.policy.ema.ema_mempool = 0;
                chain.recompute_policy_from_ema();
            }
            assert_eq!(chain.current_pressure_state_for_api(), "normal");
            let normalized_fee = chain.policy.base_fee_per_tx;

            for _ in 0..60 {
                // Force a real idle/cold phase. 100_000ppm is below idle-exit but
                // above idle-enter, so from normal it may stay normal and never lower.
                chain.policy.ema.ema_block_fill_ppm = CTRL34_IDLE_THRESHOLD_PPM;
                chain.policy.ema.ema_mempool = 0;
                chain.recompute_policy_from_ema();
            }
            let underutilized_fee = chain.policy.base_fee_per_tx;

            assert!(congested_fee > start_fee);
            assert!(
                congested_fee <= TEST_FEE_ANCHOR * 5,
                "fee growth must remain bounded by the simple hot cadence, got {}",
                congested_fee
            );
            assert!(normalized_fee <= congested_fee);
            assert!(underutilized_fee < normalized_fee);
            assert!(
                underutilized_fee
                    >= chain
                        .policy
                        .base_fee_min
                        .max(chain.security_runtime.min_fee_per_tx)
            );
        }

        #[test]
        fn adaptive_controller_sets_more_conservative_window_and_cooldown_when_unstable() {
            let mut chain = new_controller_chain();

            chain.policy.ema.ema_block_fill_ppm = 1_000_000;
            chain.policy.ema.ema_mempool = 300;
            chain.recompute_policy_from_ema();
            let unstable_window = chain.policy.ema.ctrl_window;
            let unstable_cooldown = chain.policy.ema.ctrl_cooldown;
            let unstable_stability = chain.policy.ema.stability_score_ppm;

            chain.policy.ema.ema_block_fill_ppm = chain.policy.target_fill_ppm;
            chain.policy.ema.ema_mempool = 0;
            chain.recompute_policy_from_ema();
            let stable_window = chain.policy.ema.ctrl_window;
            let stable_cooldown = chain.policy.ema.ctrl_cooldown;
            let stable_stability = chain.policy.ema.stability_score_ppm;

            assert!(unstable_stability < stable_stability);
            assert!(unstable_window >= stable_window);
            assert!(unstable_cooldown >= stable_cooldown);
        }

