        #[test]
        fn fill_estimation_user_bytes_uses_effective_builder_budget_not_raw_max_block_size() {
            let mut chain = new_controller_chain();
            chain.security_runtime.max_block_size = 10_000;
            let builder_budget = chain.block_builder_effective_user_tx_budget_bytes();
            assert_eq!(builder_budget, 7_452);

            let mut block = chain.create_block_dummy();
            let mut coinbase = Transaction {
                sender: "COINBASE".to_string(),
                receiver: "miner-a".to_string(),
                amount: 1,
                max_fee_per_tx: 0,
                nonce: 0,
                signature: String::new(),
                hash: String::new(),
                is_coinbase: true,
                memo: None,
            };
            coinbase.hash = coinbase.calculate_hash();
            let mut user_tx = Transaction {
                sender: "alice".to_string(),
                receiver: "bob".to_string(),
                amount: 7,
                max_fee_per_tx: chain.policy.base_fee_per_tx,
                nonce: 1,
                signature: "sig".to_string(),
                hash: String::new(),
                is_coinbase: false,
                memo: Some("x".repeat(4_500)),
            };
            user_tx.hash = user_tx.calculate_hash();
            block.transactions = vec![coinbase, user_tx.clone()];
            block.hash = block.calculate_hash();

            let user_tx_bytes = Blockchain::estimate_tx_size_bytes_deterministic(&user_tx);
            let expected = (((user_tx_bytes as u128) * (PPM as u128)) / (builder_budget as u128))
                .min(PPM as u128) as u32;
            let legacy_raw_max_block = (((user_tx_bytes as u128) * (PPM as u128))
                / (chain.security_runtime.max_block_size as u128))
                .min(PPM as u128) as u32;

            let actual = chain.block_fill_ppm_from_user_tx_bytes(&block);
            assert_eq!(actual, expected);
            assert!(actual > legacy_raw_max_block);
        }

