        #[test]
        fn genesis_validator_bootstrap_memo_seeds_committee0_and_registry() {
            let _lock = crate::tests::test_process_lock();
            crate::chain_identity::init_chain_id("genesis-validator-bootstrap-test").unwrap();

            let storage = open_test_storage("genesis_validator_bootstrap_memo_seeds_committee0");
            let smt = StateSmt::new(storage.state_node_store());

            let mut txs = Vec::new();

            let pos_params_memo = serde_json::to_string(&GenesisPosParamsMemoV1 {
                v: 1,
                kind: "genesis_pos_params_v1".to_string(),
                pos_params: staking::PosParamsV1 {
                    min_stake: 1,
                    unbonding_epochs: 1,
                    epoch_len: 10,
                    committee_size: 2,
                },
            })
            .unwrap();
            let mut pos_tx = Transaction {
                sender: "COINBASE".to_string(),
                receiver: "GENESIS_MINER".to_string(),
                amount: 0,
                max_fee_per_tx: 0,
                nonce: 0,
                signature: String::new(),
                hash: String::new(),
                is_coinbase: true,
                memo: Some(pos_params_memo),
            };
            pos_tx.hash = pos_tx.calculate_hash();
            txs.push(pos_tx);

            let bootstrap_memo = serde_json::to_string(&GenesisValidatorBootstrapMemoV1 {
                v: 1,
                kind: "genesis_validator_bootstrap_v1".to_string(),
                validators: vec![
                    GenesisValidatorBootstrapEntryV1 {
                        pk_hex: "11".repeat(32),
                        weight: 11,
                    },
                    GenesisValidatorBootstrapEntryV1 {
                        pk_hex: "22".repeat(32),
                        weight: 17,
                    },
                    GenesisValidatorBootstrapEntryV1 {
                        pk_hex: "33".repeat(32),
                        weight: 23,
                    },
                ],
            })
            .unwrap();
            let mut bootstrap_tx = Transaction {
                sender: "COINBASE".to_string(),
                receiver: "GENESIS_MINER".to_string(),
                amount: 0,
                max_fee_per_tx: 0,
                nonce: 0,
                signature: String::new(),
                hash: String::new(),
                is_coinbase: true,
                memo: Some(bootstrap_memo),
            };
            bootstrap_tx.hash = bootstrap_tx.calculate_hash();
            txs.push(bootstrap_tx);

            let root = Blockchain::compute_state_root_for_txs_with_smt_inner(
                &smt, "", 0, &txs, true, None, None, None,
            )
            .unwrap();
            let root_bytes = bytes32_from_hex(&root).unwrap();

            let committee_st = smt
                .get_account(root_bytes, pos::k_committee(0))
                .unwrap()
                .unwrap();
            let committee = pos::decode_committee_state_any(&committee_st).unwrap();
            assert_eq!(committee.pk_hex_list().len(), 2);

            let index_st = smt
                .get_account(root_bytes, staking::k_validator_index())
                .unwrap()
                .unwrap();
            let index = staking::decode_validator_index_state(&index_st).unwrap();
            assert_eq!(index.pk_hex.len(), 3);

            let total_st = smt
                .get_account(root_bytes, staking::k_total_bonded())
                .unwrap()
                .unwrap();
            let total = staking::decode_total_bonded_state(&total_st).unwrap();
            assert_eq!(total.total, 51);
        }
        #[test]
        fn empty_block_reward_applies_after_effective_multiplier() {
            let mut chain = Blockchain::new();
            chain.policy.reward_schedule = RewardSchedule {
                initial_per_block: 100,
                floor_per_block: 100,
                reward_to_treasury_bps: 2_000,
                empty_block_reward_bps: 5_000,
                ..RewardSchedule::default()
            };
            chain.policy.emission_controller.enabled = true;
            chain.policy.emission_controller.launch_multiplier_max_bps = 12_000;
            chain.policy.emission_controller.steady_multiplier_max_bps = 10_000;
            chain.policy.emission_controller.multiplier_min_bps = 8_500;
            chain.policy.emission_state.phase = EmissionSunsetPhase::Launch;
            chain.policy.emission_state.reward_multiplier_bps = 12_000;
            chain.sync_emission_controller_fields();

            let (total_full, miner_full, treasury_full) = chain.effective_reward_split(1, false);
            assert_eq!(total_full, 120);
            assert_eq!(treasury_full, 24);
            assert_eq!(miner_full, 96);

            let (total_empty, miner_empty, treasury_empty) = chain.effective_reward_split(1, true);
            assert_eq!(total_empty, 60);
            assert_eq!(treasury_empty, 12);
            assert_eq!(miner_empty, 48);
        }

