        #[test]
        fn reward_controller_is_deterministic_for_same_block_sequence() {
            let mut a = new_emission_chain();
            let mut b = new_emission_chain();

            for day in 0..40u64 {
                let budget = if day < 20 {
                    0
                } else {
                    a.target_validator_budget_per_day_base().saturating_mul(2)
                };
                for chain in [&mut a, &mut b] {
                    chain.policy.emission_state.validator_fee_budget_ma30 = budget;
                    chain.policy.ema.ema_block_fill_ppm = if day < 20 { 100_000 } else { 900_000 };
                    chain.policy.backlog_ratio_ppm = if day < 20 { 100_000 } else { 900_000 };
                    chain.policy.current_regime = if day < 20 {
                        "normal".to_string()
                    } else {
                        "congested".to_string()
                    };
                    chain.recompute_reward_multiplier_daily(day);
                }
            }

            assert_eq!(
                a.policy.emission_state.reward_multiplier_bps,
                b.policy.emission_state.reward_multiplier_bps
            );
            assert_eq!(a.policy.emission_state.phase, b.policy.emission_state.phase);
            assert_eq!(
                a.policy.emission_state.reward_shadow_bps_fp,
                b.policy.emission_state.reward_shadow_bps_fp
            );
        }

        #[test]
        fn emission_day_rollover_updates_window_and_phase_from_real_block_sequence() {
            let mut chain = new_emission_chain();
            chain.policy.base_fee_per_tx = 100;
            chain.policy.burn_bps = 0;
            chain.policy.treasury_pct_base_bps = 0;
            chain.policy.emission_controller.blocks_per_day = 2;
            chain.policy.emission_controller.window_days = 4;
            chain.policy.emission_controller.consecutive_days_required = 2;
            chain.policy.emission_controller.hard_cap_days = 10;
            chain.policy.emission_controller.taper_days = 2;
            chain.sync_emission_controller_fields();

            apply_emission_test_sequence(&mut chain, 2, &[20, 20, 0]);

            assert_eq!(chain.policy.emission_window.current_day_index, 3);
            assert_eq!(chain.policy.emission_window.consecutive_sustainable_days, 0);
            assert_eq!(
                chain.policy.emission_state.phase,
                EmissionSunsetPhase::Taper
            );
            // The sequence intentionally closes with an empty day. After V62
            // public-testnet config alignment the final rolling MA includes
            // that zero-fee day, so the assertion must prove the empty-day
            // rollover is accounted for instead of assuming the MA remains
            // sustainable after the phase transition has already happened.
            assert!(
                chain.policy.emission_state.validator_fee_budget_ma30
                    < chain.target_validator_budget_per_day_base()
            );
            assert_eq!(chain.policy.emission_state.under_target_streak, 1);
            assert!(
                chain.policy.emission_state.reward_multiplier_bps
                    <= chain.policy.emission_controller.launch_multiplier_max_bps
            );
        }

