        #[test]
        fn fee_and_emission_controllers_do_not_oscillate_badly_together() {
            let mut chain = new_emission_chain();
            let mut prev_fee = chain.policy.base_fee_per_tx;
            let mut prev_reward = chain.policy.emission_state.reward_multiplier_bps;
            for step in 0..20 {
                if step % 2 == 0 {
                    chain.policy.ema.ema_block_fill_ppm = 900_000;
                    chain.policy.ema.ema_mempool = 500;
                    chain.policy.backlog_ratio_ppm = 900_000;
                    chain.policy.current_regime = "congested".to_string();
                    chain.policy.emission_state.validator_fee_budget_ma30 = chain
                        .target_validator_budget_per_day_base()
                        .saturating_mul(2);
                } else {
                    chain.policy.ema.ema_block_fill_ppm = 100_000;
                    chain.policy.ema.ema_mempool = 10;
                    chain.policy.backlog_ratio_ppm = 100_000;
                    chain.policy.current_regime = "normal".to_string();
                    chain.policy.emission_state.validator_fee_budget_ma30 = 0;
                }
                chain.recompute_policy_from_ema();
                chain.recompute_reward_multiplier_daily(step as u64);
                assert!(chain.policy.base_fee_per_tx >= chain.policy.base_fee_min);
                assert!(chain.policy.base_fee_per_tx <= chain.policy.base_fee_max);
                assert!(
                    chain.policy.emission_state.reward_multiplier_bps
                        >= chain.policy.emission_controller.multiplier_min_bps
                );
                assert!(
                    chain.policy.emission_state.reward_multiplier_bps
                        <= chain.current_emission_phase_max_bps(step as u64)
                );
                assert!(
                    chain.policy.base_fee_per_tx.abs_diff(prev_fee) <= chain.policy.base_fee_max
                );
                assert!(
                    chain
                        .policy
                        .emission_state
                        .reward_multiplier_bps
                        .abs_diff(prev_reward)
                        <= chain
                            .policy
                            .emission_controller
                            .reward_delta_max_bps_per_day
                            .max(5000)
                );
                prev_fee = chain.policy.base_fee_per_tx;
                prev_reward = chain.policy.emission_state.reward_multiplier_bps;
            }
        }

