        #[test]
        fn fractional_reward_carry_makes_small_multiplier_changes_eventually_real() {
            let mut chain = new_emission_chain();
            chain.policy.reward_schedule = RewardSchedule {
                initial_per_block: 1,
                floor_per_block: 1,
                reward_to_treasury_bps: 0,
                empty_block_reward_bps: 10_000,
                ..RewardSchedule::default()
            };
            chain.policy.emission_state.reward_multiplier_bps = 10_500;
            chain.policy.emission_state.reward_shadow_bps_fp =
                10_500u128 * EMISSION_MULTIPLIER_BPS_FP_SCALE;
            chain.policy.emission_state.reward_effective_carry_fp = 0;
            // Keep the carry test isolated from the daily adaptive controller. The
            // assertion targets fractional reward carry, not budget-driven multiplier drift.
            chain.policy.emission_controller.blocks_per_day = 10_000;
            chain.policy.emission_window.blocks_per_day = 10_000;
            chain.sync_emission_controller_fields();

            let miner_pk_b64 = Blockchain::test_miner_pub_b64();
            let miner_pub_hex = Blockchain::test_miner_pub_hex();
            let mut total_reward = 0u64;
            for height in 1..=20u64 {
                let block = make_applied_block_with_coinbase(
                    &mut chain,
                    height,
                    1,
                    miner_pk_b64,
                    miner_pub_hex,
                );
                let meta = Blockchain::coinbase_econ_meta_v3(&block);
                let reward_total = meta.map(|m| m.reward_total).unwrap_or(0);
                total_reward = total_reward.saturating_add(reward_total);
                chain.chain.push(block.clone());
                chain.on_block_applied(&block, None);
            }
            assert!(total_reward > 20);
            assert!(
                chain.policy.emission_state.reward_effective_carry_fp
                    < REWARD_EFFECTIVE_CARRY_DENOM_FP
            );
            // This fixture intentionally avoids a day rollover so it remains a pure
            // fractional-carry test. The emission controller reason code is therefore
            // expected to remain unchanged from startup; daily controller reason-code
            // transitions are covered by the dedicated budget-streak tests above.
        }

