    #[test]
    fn wallet_misconduct_survives_immediate_validator_slash_mirror() {
        let validator = sample_pub(20);
        let mut gov = test_governance(&[(validator.clone(), 1)]);

        gov.apply_wallet_generic_misconduct_effect_v1(
            &validator,
            crate::governance::WalletMisconductKindV1::SignatureFraud,
            260,
            "attributed wallet signature fraud before validator slash mirror",
        );
        let before = gov
            .wallet_reputation
            .get(&validator)
            .expect("wallet misconduct before slash")
            .clone();

        Blockchain::apply_validator_slash_reputation_effect_v1(
            &mut gov,
            &validator,
            &SlashingReason::DoubleProposalSameHeight,
            270,
            Some(1_270),
        );

        let validator_rep = gov
            .validator_reputation
            .get(&validator)
            .expect("validator reputation");
        let wallet_rep = gov
            .wallet_reputation
            .get(&validator)
            .expect("wallet reputation mirror");

        assert_eq!(wallet_rep.slashed_count, validator_rep.slashed_count);
        assert_eq!(
            wallet_rep.last_slash_height,
            validator_rep.last_slash_height
        );
        assert_eq!(
            wallet_rep.jailed_until_height,
            validator_rep.jailed_until_height
        );
        assert_eq!(
            wallet_rep.temporarily_revoked,
            validator_rep.temporarily_revoked
        );
        assert!(wallet_rep.misbehavior_points >= before.misbehavior_points);
        assert_eq!(wallet_rep.failure_count, before.failure_count);
        assert_eq!(wallet_rep.recent_failure_count, before.recent_failure_count);
        assert_eq!(wallet_rep.consecutive_failures, before.consecutive_failures);
        assert_eq!(
            wallet_rep.last_hard_fault_height,
            Some(270),
            "validator slash hard fault is authoritative when newer, while wallet-specific counters survive"
        );
    }

    #[test]
    fn validator_slash_fields_remain_authoritative_after_wallet_sync() {
        let validator = sample_pub(19);
        let mut gov = test_governance(&[(validator.clone(), 1)]);
        Blockchain::apply_validator_slash_reputation_effect_v1(
            &mut gov,
            &validator,
            &SlashingReason::DoubleProposalSameHeight,
            230,
            Some(1_230),
        );

        let mut stale_wallet = gov
            .wallet_reputation
            .get(&validator)
            .expect("wallet mirror")
            .clone();
        stale_wallet.slashed_count = 99;
        stale_wallet.last_slash_height = 9_999;
        stale_wallet.jailed_until_height = Some(9_999);
        stale_wallet.temporarily_revoked = true;
        stale_wallet.misbehavior_points = stale_wallet.misbehavior_points.saturating_add(7);
        gov.wallet_reputation
            .insert(validator.clone(), stale_wallet);

        let mut bc = Blockchain::new();
        bc.governance = Some(gov);
        bc.sync_wallet_reputation_plane();

        let gov = bc.governance.as_ref().expect("governance");
        let validator_rep = gov
            .validator_reputation
            .get(&validator)
            .expect("validator reputation");
        let wallet_rep = gov
            .wallet_reputation
            .get(&validator)
            .expect("wallet reputation");

        assert_eq!(wallet_rep.slashed_count, validator_rep.slashed_count);
        assert_eq!(
            wallet_rep.last_slash_height,
            validator_rep.last_slash_height
        );
        assert_eq!(
            wallet_rep.jailed_until_height,
            validator_rep.jailed_until_height
        );
        assert_eq!(
            wallet_rep.temporarily_revoked,
            validator_rep.temporarily_revoked
        );
        assert_eq!(wallet_rep.slashed_count, 1);
        assert_eq!(wallet_rep.last_slash_height, 230);
        assert_eq!(wallet_rep.jailed_until_height, Some(1_230));
        assert!(wallet_rep.misbehavior_points >= validator_rep.misbehavior_points);
    }

