    #[test]
    fn nft_utility_ops_update_metadata_freeze_and_unfreeze() {
        let smt = StateSmt::ephemeral();
        let gov = nft_gov_enabled(0);
        let issuer = nft_test_addr(1);
        let alice = nft_test_addr(2);
        let root1 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            "",
            1,
            &[nft_tx(
                &issuer,
                0,
                &nft_create_op(
                    "UTIL",
                    crate::nft::NftAssetTypeV1::Collectible,
                    crate::nft::NftTransferPolicyV1::Transferable,
                    true,
                    true,
                ),
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("create collection");
        let root2 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root1,
            2,
            &[nft_tx(&issuer, 1, &nft_mint_op(issuer.clone(), None))],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("mint");
        let root3 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root2,
            3,
            &[nft_tx(
                &issuer,
                2,
                &crate::nft::NftOpV1::SetTokenUri {
                    collection_id: 1,
                    serial: 1,
                    token_uri: "ipfs://updated-token".to_string(),
                    metadata_hash: nft_test_hash(0x91),
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("set token uri");
        let r3 = bytes32_from_hex(&root3).unwrap();
        let tm = crate::nft::decode_token_meta_state_v1(
            &smt.get_account(r3, crate::nft::k_nft_token_meta(1, 1))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(tm.token_uri, "ipfs://updated-token");
        assert_eq!(tm.metadata_hash, nft_test_hash(0x91));

        let root4 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root3,
            4,
            &[nft_tx(
                &issuer,
                3,
                &crate::nft::NftOpV1::FreezeToken {
                    collection_id: 1,
                    serial: 1,
                    frozen: true,
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("freeze token");
        let frozen_root = bytes32_from_hex(&root4).unwrap();
        let tm = crate::nft::decode_token_meta_state_v1(
            &smt.get_account(frozen_root, crate::nft::k_nft_token_meta(1, 1))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(tm.status, crate::nft::NftTokenStatusV1::Frozen);
        let err = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root4,
            5,
            &[nft_tx(
                &issuer,
                4,
                &crate::nft::NftOpV1::Transfer {
                    collection_id: 1,
                    serial: 1,
                    to_b64: alice.clone(),
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect_err("frozen token must reject transfer");
        assert!(err.contains("nft_token_frozen"), "unexpected error: {err}");

        let root5 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root4,
            6,
            &[nft_tx(
                &issuer,
                5,
                &crate::nft::NftOpV1::FreezeToken {
                    collection_id: 1,
                    serial: 1,
                    frozen: false,
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("unfreeze token");
        let root6 = Blockchain::compute_state_root_for_txs_with_smt_inner(
            &smt,
            &root5,
            7,
            &[nft_tx(
                &issuer,
                6,
                &crate::nft::NftOpV1::Transfer {
                    collection_id: 1,
                    serial: 1,
                    to_b64: alice.clone(),
                },
            )],
            true,
            None,
            None,
            Some(&gov),
        )
        .expect("transfer after unfreeze");
        let r6 = bytes32_from_hex(&root6).unwrap();
        let owner = crate::nft::decode_token_owner_b64_v1(
            &smt.get_account(r6, crate::nft::k_nft_token_owner(1, 1))
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(owner, alice);
    }

