    #[test]
    fn block5_standard_evidence_hard_candidate_records_without_automatic_mutation() {
        let mut fixture = setup_finalized_order(false);
        let ev = evidence_for_fixture(
            &fixture,
            false,
            crate::e2_worker_evidence::FAILURE_SIGNATURE_INVALID,
            crate::e2_worker_evidence::FAULT_WORKER,
            crate::e2_worker_evidence::EFFECT_HARD_PENALTY,
            true,
            crate::e2_worker_evidence::VERDICT_WORKER_PENALTY_CANDIDATE,
            4,
        );
        let tx = evidence_submit_tx(&fixture.attester_sk, &fixture.attester_pk_b64, ev, 12);
        fixture
            .chain
            .validate_e2_worker_standard_evidence_tx_v1(&tx)
            .unwrap();
        let outcome = fixture
            .chain
            .apply_e2_worker_standard_evidence_from_compute_tx_v1(&tx, 4)
            .unwrap()
            .expect("evidence submit tx must return an apply outcome");
        assert_eq!(outcome.status, "recorded_pending_secondary_governance");
        assert_eq!(outcome.applied_delta, 0);
        assert!(outcome.candidate_delta < 0);
        assert!(outcome.requires_governance);

        assert!(!fixture
            .chain
            .e2_worker_reputation_history_index
            .contains_key(&crate::e2_worker_evidence::e2_worker_history_key_v1(
                &fixture.worker_hex,
                &fixture.operator_hex,
            )));
        let maybe_rep = fixture
            .chain
            .governance
            .as_ref()
            .unwrap()
            .validator_reputation
            .get(&fixture.worker_hex);
        if let Some(rep) = maybe_rep {
            assert_eq!(rep.failure_count, 0);
            assert_eq!(rep.recent_invalid_output_count, 0);
            assert_eq!(rep.accepted_run_evidence_count, 0);
        }
        assert_eq!(fixture.chain.e2_worker_reputation_evidence_log.len(), 1);
        assert!(fixture.chain.e2_worker_reputation_evidence_log[0].requires_governance);
    }

